quests[780] = { id = 780, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kampfeber", description = "Die Kampfeber der Dornrankenklamm im Osten sind in unser Stammesjagdterritorium eingedrungen. Sie wurden von den Borstennackenstachelebern, mit denen wir uns im Krieg befinden, abgerichtet, niederträchtig zu sein.\n\nTötet diese elenden Kreaturen und bringt mir ein paar ihrer Schnauzen und Flanken, damit wir daraus einen Eintopf für unsere Jungen zubereiten können.", sourceObjective = "Grull Falkenwind im Camp Narache möchte, dass Ihr für ihn Kampfeber tötet und ihm 8 Kampfeberschnauzen und 8 Kampfeberflanken bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[781] = { id = 781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Attack on Camp Narache" }
quests[782] = { id = 782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerbrochene Allianzen", description = "Durch die Allianz der Horde mit dem Großdrachen Todesschwinge während des zweiten Krieges wissen wir, dass zwei ihrer Offiziere, Schattenbringer und Hematus, in der Lethlorklamm weit im Osten eingesperrt sind. Wir müssen unsere verderbten Verbündeten von damals zum Stillschweigen bringen, um die Ehre der Horde wiederherzustellen!\n\nWir hatten Tho'grun und seine Gruppe Ogersöldner angeheuert, damit sie uns helfen, das Zeichen der Erde in die Hände zu bekommen, ein Schlüssel, mit dem das Gefängnis des Drachen geöffnet werden kann. Tho'grun hat uns jedoch verraten, uns überrumpelt und ihn sich selbst angeeignet. Begebt Euch zum Camp Boff und holt ihn zurück!", sourceObjective = "Tötet Tho'grun und bringt Gorn in Kargath das Zeichen der Erde.", sourceObjectiveStatus = "unverified-source-field" }
quests[783] = { id = 783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bedrohung von innen", description = "Ich hoffe, Ihr habt Euren Gürtel festgezurrt, {class}, denn es gibt hier in Nordhain viel Arbeit.\n\nUnd ich meine damit nicht Landarbeit.\n\nDie Wachen von Sturmwind haben alle Hände voll zu tun, um den Frieden zu bewahren; viele von uns weilen in fernen Ländern und viele Bedrohungen rücken immer näher. Deshalb rekrutieren wir jeden, der gewillt ist, seine Heimat zu verteidigen. Und die Allianz.\n\nFalls Ihr hier seid, um dem Aufruf zu folgen, sprecht mit meinem Vorgesetzten, Marschall McBride. Er ist in der Abtei hinter mir.", sourceObjective = "Sprecht mit Marschall McBride.", sourceObjectiveStatus = "unverified-source-field" }
quests[784] = { id = 784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vernichtet die Verräter", description = "Angeführt von Admiral Prachtmeer drangen die Menschen von Kul Tiras nach Durotar vor und brachen damit den Pakt, den der Kriegshäuptling vor Jahren mit Jaina Prachtmeer geschlossen hatte, um Archimonde zu besiegen.\n\nDie Menschenaggressoren wurden zurückgeschlagen und Burg Tiragarde fiel. Kürzlich jedoch hat die Reserve des Admirals unter der Führung von Leutnant Benedict die Burg zurückerobert und stellt erneut eine Bedrohung für unser Heimatland dar. Diese Menschen haben keinen Respekt vor Diplomatie.\n\nBeweist Eure Ehre und reist gen Süden zur Burg Tiragarde, um die Menscheneindringlinge zu eliminieren.", sourceObjective = "Tötet 10 Matrosen von Kul Tiras, 8 Marinesoldaten von Kul Tiras sowie Leutnant Benedict und kehrt dann zu Gar'Thok in Klingenhügel zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[785] = { id = 785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine strategische Allianz", description = "Thrall ist ein äußerst weiser und edler Anführer. Seine Beharrlichkeit auf dem Schlachtfeld wird nur von seinem diplomatischen Feingefühl übertroffen.\n\nDie Trolle der Dunkelspeere haben sich als unschätzbare Verbündete für die Orcs erwiesen. Wir haben aus Loyalität und Ehrgefühl einen Schutzpakt mit ihnen geschlossen.\n\nDer Kriegshäuptling hat Befehle ausgegeben, dafür zu sorgen, dass unsere Dunkelspeerfreunde in Sen'jin nicht unmittelbar in Gefahr sind. Einer ihrer verlässlichsten Späher, Lar Lauerzahn, hat ein wachsames Auge auf ihre Westflanke.\n\nSucht Lar und unterstützt ihn notwendigenfalls.", sourceObjective = "Sucht Lar Lauerzahn an der Westflanke von Sen'jin auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[786] = { id = 786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vereitelung der Kolkaraggression", description = "Sprecht leiser, {class}. Die Zentauren der Kolkar liegen gleich hinter jener Kuppe im Westen der Kolkarklippe.\n\nWährend ihres Angriffs letzte Nacht schlich ich mich in ihr Dorf und fand heraus, dass diese dreckigen Bestien einen dreistufigen Angriff auf die Trolle und Orcs von Durotar geplant hatten.\n\nIhre Invasion muss verhindert werden. Vielleicht könnt Ihr die Streitmacht zusammenziehen, die nötig ist, um die Kolkarklippe zu unterwandern und deren Angriffspläne zu vernichten.\n\nZuletzt sah ich, dass Sie sich auf drei ihrer Anführer verteilten.", sourceObjective = "Lar Lauerzahn außerhalb von Sen'jin möchte, dass Ihr die 3 Sets der Angriffspläne zerstört, die innerhalb der Kolkarklippe verwahrt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[787] = { id = 787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die neue Horde", description = "Throm-ka, {class}. Ich bin Etrigg, von Thrall beauftragt, die Ausbildung der Rekruten zu beaufsichtigen.\n\nDie Horde ist nicht mehr das, was sie einmal war. Es gab eine Zeit, da ich die Horde verließ, enttäuscht durch den wachsenden Einfluss der machthungrigen Marionetten der Brennenden Legion. Während meines Exils wurde ich von einer Gruppe Menschen gefangen genommen, aber dann von dem Kriegshäuptling gerettet. Er erzählte mir von seiner Vision einer Horde, frei von dämonischen Einflüssen, von den Schamanen geleitet, und so kehrte ich zurück.\n\nGornek wird weitere Anweisungen für Euch haben.", sourceObjective = "Meldet Euch bei Gornek beim Höhlenbau.", sourceObjectiveStatus = "unverified-source-field" }
quests[788] = { id = 788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erste Erfahrungen", description = "Als Erstes werden wir Euer Rückgrat etwas kräftigen. Ich könnte Euch ins Brachland schicken, um Kodos zu jagen, aber mal ehrlich, lebend seid Ihr uns nützlicher als tot.\n\nIch glaube, die scheckigen Eber nördlich von hier wären genau das Richtige für Euch.", sourceObjective = "Tötet 8 scheckige Eber und kehrt dann zu Gornek beim Höhlenbau zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[789] = { id = 789, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stich des Skorpiden", description = "Sowohl mächtige Krieger als auch tollpatschige Anfänger fallen dem Giftstachel der Skorpide zum Opfer. Nordwestlich von hier findet Ihr eine größere Ansammlung Skorpide. Bringt mir als Beweis Eurer Leistungsfähigkeit im Kampf 8 ihrer Schwänze.\n\nDas Gegengift für ihren Stich wird aus genau dem Gift gewonnen, das aus ihren Stacheln extrahiert wurde. Wir haben immer einen großen Vorrat an Gegengift für dieses Skorpidgift, um Grünschnäbel wie Euch damit zu heilen...\n\nAber Ihr werdet das doch bestimmt nicht brauchen, oder?", sourceObjective = "Bringt 8 Skorpidarbeiterschwänze zu Gornek im Höhlenbau.", sourceObjectiveStatus = "unverified-source-field" }
quests[790] = { id = 790, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sarkoth", description = "{class}! Ich dachte schon, ich müsste hier draußen sterben und niemand würde es bemerken. Auf der Jagd nach den Skorpiden des Tals stieß ich auf ein besonders heimtückisches Exemplar. Ich stürzte mich auf ihn und konnte einer seiner Klauen einen ordentlichen Draufschlag versetzen, bevor sie sich um mein Bein schloss.\n\nIch hatte jedoch nicht mit seinem Stecher gerechnet, den er tief in meine Brust trieb, mit dem er mein Fleisch zerschnitt und mir einen großen Blutverlust verursachte. Bitte, Ihr müsst den Skorpid für mich töten! Meine Ehre darf nicht besudelt werden! Da oben auf dem Plateau im Süden habe ich gegen ihn gekämpft.", sourceObjective = "Tötet Sarkoth und bringt seine Klaue zu Hana'zua.", sourceObjectiveStatus = "unverified-source-field" }
quests[791] = { id = 791, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Akzeptiert Euer Schicksal", description = "Das Alter hat mich nutzlos für die Schlacht gemacht. Jetzt mache ich mich eben auf andere Weise nützlich.\n\nVon diesem Aussichtspunkt aus achte ich auf Eindringlinge. Während unsere Kraft hier zunimmt, muss ich mein Signalhorn immer seltener benutzen.\n\nUm mir die Zeit zu vertreiben, fertige ich Dinge an, die den jüngeren und fähigeren Kriegern bei der Verteidigung unserer Heimat helfen können.\n\nFür Euch könnte ich eine Tasche für Eure Habseligkeiten anfertigen. Falls ein solcher Gegenstand Euch nützlich sein könnte, bringt mir etwas Segeltuch, ein Material, das unter Menschen und Zentauren verbreitet ist.", sourceObjective = "Furl Hohnbraue im Wachturm von Klingenhügel möchte 8 Segeltuchreste haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[792] = { id = 792, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Üble Familiare", description = "Ich denke, das Tal der Prüfungen wird Euch viel lehren, {class}.\n\nMan hat mich eigentlich ins Tal geschickt, um Euch anzuleiten, aber ich habe dort eine sich ausbreitende Besudelung entdeckt...\n\nEine Gruppe, die sich die 'Brennende Klinge' nennt, hat hier im Tal der Prüfungen einen Koven für ihre Mitglieder. Sie lungern im Nordosten in einer Höhle herum und ihre üblen Familiare kriechen daraus hervor, um Chaos anzurichten.\n\nAls erste Aktion gegen die Brennende Klinge bitte ich Euch, diese Familiare zu vernichten. Tötet so viele Ihr könnt, und falls Ihr überlebt, kehrt zu mir zurück.", sourceObjective = "Tötet 8 üble Familiare.\n\nKehrt dann zu Zureetha Fernblick beim Höhlenbau zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[793] = { id = 793, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerbrochene Allianzen", description = "Das Siegel der Erde wird von drei Runensteinen gebildet, die in der Lethlorklamm auf Säulen aus Diamant, Opal und Amethyst liegen. Ihr könnt die Runensteine mithilfe des Zeichens der Erde entfernen und so das Siegel der Erde brechen.\n\nSeid jedoch vorsichtig, {name}, die Schwarzdrachen Schattenbringer und Hematus sollte man nicht unterschätzen. Tötet sie und kehrt mit ihren Bindungen zu mir zurück.\n\nUm die Klamm zu erreichen, müsst Ihr in den östlichsten Teil des Ödlands reisen. Lasst jedoch Vorsicht walten, da die Klamm zahllose Drachen beherbergt.", sourceObjective = "Benutzt das Zeichen der Erde, um die Säulen aus Diamant, Opal und Amethyst zu aktivieren und die Runensteine zu holen.\n\nLegt die Runensteine auf das Siegel der Erde, um Schattenbringer und Hematus zu befreien.\n\nTötet sie und bringt dann Gorn Schattenbringers Bindung, Hematus' Ketten und das Zeichen der Erde.", sourceObjectiveStatus = "unverified-source-field" }
quests[794] = { id = 794, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Medaillon der Brennenden Klinge", description = "Durch meine hellseherischen Kräfte weiß ich, dass im Koven der Brennenden Klinge ein Gegenstand der Macht verborgen ist, der durch Bestien und schwarze Magie bewacht wird.\n\nEr wird das Medaillon der Brennenden Klinge genannt und Eure nächste Aufgabe besteht darin, es zu finden und aus dem Koven zu entfernen.\n\nSeid jedoch vorsichtig, denn das Medaillon könnte im Besitz eines Agenten der Brennenden Klinge sein, und falls dem so ist, ist die Macht dieses Agenten weitaus stärker als die der Familiare, auf die Ihr bereits gestoßen seid.\n\nGeht, {name}. Ihr findet den Koven in einer Höhle im Norden und Westen.", sourceObjective = "Bringt Zureetha Fernblick beim Höhlenbau das Medaillon der Brennenden Klinge.", sourceObjectiveStatus = "unverified-source-field" }
quests[795] = { id = 795, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siegel der Erde" }
quests[804] = { id = 804, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sarkoth", description = "Was Ihr für mich getan habt, gibt mir Zuversicht. Ich darf nicht einfach so gehen! Ich muss durchhalten!\n\nOhne Hilfe schaffe ich jedoch den Weg zurück zum Höhlenbau nicht. Bitte, {name}, kehrt zum Höhlenbau zurück und berichtet Gornek von meiner Lage. Vielleicht kann er mir helfen.", sourceObjective = "Informiert Gornek beim Höhlenbau über Hana'zuas Notlage.", sourceObjectiveStatus = "unverified-source-field" }
quests[805] = { id = 805, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bericht erstatten in Sen'jin", description = "Eure Prüfungen durch die Brennende Klinge sind beendet... jedenfalls hier im Tal. Ich möchte aber, dass Ihr von Euren Funden berichtet.\n\nBegebt Euch in das Trolldorf Sen'jin und sucht nach Meister Gadrin. Sen'jin liegt östlich hinter dem Tal und dann geht es an der Weggabelung nach rechts.\n\nBerichtet Gadrin von der Brennenden Klinge und dass sie das Tal der Prüfungen erreicht haben. Bringt von ihm in Erfahrung, ob sie Sen'jin schon erreicht haben.\n\nGeht, {name}, und beeilt Euch. Ich fürchte, dass das Böse, das wir im Koven der Brennenden Klinge entdeckt haben, nur der Vorbote eines viel größeren Übels ist...", sourceObjective = "Sprecht mit Meister Gadrin in Sen'jin.", sourceObjectiveStatus = "unverified-source-field" }
quests[806] = { id = 806, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkle Stürme", description = "Wir können der Brennenden Klinge nicht erlauben, in Durotar Fuß zu fassen! Wir müssen sie vernichten, bevor das Böse zu schwären beginnt!\n\nIch habe selbst Nachforschungen unternommen und herausgefunden, dass ein Hexenmeister der Brennenden Klinge, der Goblin Zischel Düstersturm, nahe dem Donnergrat im Nordwesten kampiert. Er und seine Kultdiener verbreiten dort Chaos.\n\nSucht und besiegt Zischel und bringt mir seine Klaue!", sourceObjective = "Bringt Zischels Klaue zu Orgnil Narbenseele in Klingenhügel.", sourceObjectiveStatus = "unverified-source-field" }
quests[808] = { id = 808, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Minshinas Schädel", description = "Ich höre die Stimme meines Bruders Minshina, der in meinen Träumen zu mir spricht.\n\nEr wurde von Zalazane, dem Hexenmeister auf den Echoinseln im Osten, gefangen genommen. Und er ist tot.\n\nAber der Tod bedeutet nicht Freiheit für meinen Bruder. Minshinas Geist ist durch Zalazanes Magie in seinem eigenen Schädel gefangen. In meinen Träumen sehe ich ihn zusammen mit weiteren Schädeln in einem Kreis der Macht auf der Größten der Echoinseln. Solange er dort bleibt, ist die Seele meines Bruders verdammt.\n\nBitte, {name}. Sucht den Kreis und bringt Minshinas Schädel zurück. Bringt ihn mir.\n\nBefreit ihn!", sourceObjective = "Holt Minshinas Schädel aus dem Kreis der Macht auf den Echoinseln.\n\nBringt ihn Meister Gadrin in Sen'jin.", sourceObjectiveStatus = "unverified-source-field" }
quests[809] = { id = 809, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ak'Zeloth", description = "Seit dem letzten großen Krieg, in dem die Brennende Legion besiegt wurde, suche ich nach den Quellen dämonischer Verderbnis innerhalb der orcischen Gesellschaft. Das Halsband, das Ihr mir brachtet, bestätigt meine Befürchtungen.\n\nEs gehört der Brennenden Klinge, einem Kult, der sich um einen Gegenstand dämonischer Macht schart. Er wird 'Dämonensaat' genannt und im Brachland hoch über dem Glutnebelgipfel aufbewahrt. Er muss zerstört werden!\n\nGeht zur Fernwacht an der Grenze zum Brachland im Westen und sprecht dort mit meinem Assistenten Ak'Zeloth. Er wird Euch weitere Anweisungen geben.", sourceObjective = "Sprecht im Brachland mit Ak'Zeloth.", sourceObjectiveStatus = "unverified-source-field" }
quests[812] = { id = 812, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heilmittel benötigt", description = "{name}, Ihr hättet den Zeitpunkt nicht besser wählen können. Ich hoffe nur, dass ich Euch auch zu Eurer Eile beglückwünschen kann.\n\nWährend eines Kampfes mit ein paar Siechstachelskorpiden war ich unvorsichtig und ich wurde von einem von ihnen heftig gestochen. Während wir uns unterhalten, spüre ich, wie sein Gift mich schwächt. Bei dieser Geschwindigkeit bleibt mir vielleicht noch eine Stunde zu leben. Aber selbst dazu brauche ich Eure Hilfe...\n\nKor'ghan in Orgrimmar weiß, wie man das Gegengift herstellt. Sucht ihn... und zwar schnell, {name}. Ich werde nicht mehr lange durchhalten. Er sollte sich in der Kluft der Schatten befinden.", sourceObjective = "Sucht Kor'ghan in Orgrimmar und besorgt das Siechstachelgegengift. Bringt das Gegengift dann zu Rhinag an der nordwestlichen Grenze von Durotar.", sourceObjectiveStatus = "unverified-source-field" }
quests[813] = { id = 813, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach dem Gegengift", description = "Siechstachelskorpide sind eine der tödlichsten Skorpidarten in ganz Durotar. Es war dumm von Rhinag, sie zu jagen, ohne etwas von dem Gegengift mit sich zu führen, aber momentan ist eine ordentliche Standpauke das Letzte, was er benötigt.\n\nBringt mir ein paar Giftbeutel von den Siechstachelskorpiden in der Nähe des Eingangs nach Orgrimmar, dann stelle ich ein Gegengift für ihn her.\n\nBeeilt Euch, {name}. Einer der Unseren braucht Eure Hilfe.", sourceObjective = "Bringt Kor'ghan in Orgrimmar 4 Giftbeutel eines Siechstachelskorpiden.", sourceObjectiveStatus = "unverified-source-field" }
quests[815] = { id = 815, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerbrecht ein paar Eier", description = "Pah! Jetzt hätte ich doch beinahe vergessen, Frühstück zu machen.\n\n{name}, setzt Euch in Bewegung und bringt mir ein paar Schwanzpeitschereier. Ich brauche mindestens drei davon, wenn ich genug für die morgige Mahlzeit haben möchte.\n\nDie Blutkrallenschwanzpeitscher können ganz schön wild sein und beschützen ihre Eier bis in den Tod. Manchmal vergraben sie ihre Eier allerdings zu tief in der Erde, um sie sicher ausgraben zu können, aber reist doch zu den Echoinseln südöstlich von Sen'jin, dort findet man sie gewöhnlich überall auf den Inseln verteilt.", sourceObjective = "Bringt dem Koch Torka in Klingenhügel 3 Schwanzpeitschereier.", sourceObjectiveStatus = "unverified-source-field" }
quests[816] = { id = 816, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verloren, aber nicht vergessen", description = "{name}, bitte, könnt Ihr mir helfen? Mein Sohn Kron ist vor Tagen auf die Jagd gegangen und immer noch nicht zurück. Er wollte nach Westen in Richtung des Brachlandes, um dort am Ufer des Südstroms Krokilisken zu jagen. Ich fürchte das Schlimmste.\n\nSo stark wie er ist, hat ihn sein starrköpfiger Stolz doch immer wieder in Schwierigkeiten gebracht. Ich habe ihn gewarnt, dass die Krokilisken mächtig und heimtückisch sind. Er wurde wütend und stürmte davon.\n\nFalls Ihr ihn nicht finden könnt, so bringt mir doch wenigstens einen Hinweis darauf, was aus ihm geworden ist... und wenn Ihr dazu jedem einzelnen Krokilisken an den Ufern des Südstroms den Bauch aufschlitzen müsst.", sourceObjective = "Bringt Misha Tor'kren auf dem Bauernhof nordwestlich von Klingenhügel einen Hinweis auf Krons Schicksal.", sourceObjectiveStatus = "unverified-source-field" }
quests[817] = { id = 817, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Praktische Beute", description = "Viele der Bälge, die wir benutzen, stammen von den Durotartigern, {name}. Decken, Rüstungen, Zelte: Es gibt viele Gründe, warum wir Jagd auf die Wildtiere machen, und ebenso viele Gründe, warum wir sie leben lassen.\n\nDie Zeit ist gekommen, dass wir den Bestand dezimieren. Wir werden immer mehr, und unser Bedarf übersteigt bald unsere Bestände. Ich brauche mehr Bälge, wenn ich geeignete Dinge für unser Volk anfertigen möchte.\n\nBringt mir 4 Durotartigerfelle, dann werde ich Euch belohnen. Ihr findet sie auf den Inseln südlich von hier.", sourceObjective = "Bringt Vel'rin Fang in Sen'jin 4 Durotartigerfelle.", sourceObjectiveStatus = "unverified-source-field" }
quests[818] = { id = 818, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein geistvolles Getränk", description = "Meine Augen sind zwar nicht mehr so scharf, aber ich kann immer noch gut genug sehen. Immer öfter muss ich mich auf meine Alchemiefertigkeiten verlassen, um mir bei Dingen, die mir früher leicht fielen, nun mit Magie zu helfen. Ich weigere mich jedoch, einen Lehrling einzustellen - bislang ist mir noch kein Troll oder Orc begegnet, der sich als würdig genug erwiesen hätte.\n\nSeid Ihr dessen würdig? Ja, natürlich seid Ihr das... natürlich glaubt Ihr, dass Ihr es seid.\n\nIch brauche ein paar Dinge. Würdet Ihr sie für mich besorgen?\n\nIch brauche intakte Makruraaugen und Phiolen mit Kriechersekret. Ihr findet das überall in Durotar, wo es Makruras oder Kriecher gibt. Wir sehen uns bald wieder.", sourceObjective = "Bringt Meister Vornal in Sen'jin 4 intakte Makruraaugen und 8 Phiolen Kriechersekret.", sourceObjectiveStatus = "unverified-source-field" }
quests[819] = { id = 819, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chen's Empty Keg" }
quests[821] = { id = 821, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chens leeres Fässchen", description = "Möchtet Ihr eine Kostprobe von Chens Namensvetter? Ahh, das Sturmbräu ist ein gehaltvolles Bier. Chen gab das Rezept an meinen Mentor weiter und mein Mentor gab es mir. Ich möchte, dass Ihr mir ein paar Dinge besorgt, aber eins möchte ich Euch sagen: Der Kick ist es wert.\n\nBringt mir 5 Savannenlöwenhauer von beliebigen Savannenlöwen, 5 Ebenenschreiternieren von beliebigen Ebenenschreitern und 1 Donnerechsenhorn von einer Sturmschnauze. Das sollte bestens funktionieren.\n\nIhr findet diese Zutaten überall im Brachland.", sourceObjective = "Bringt Braumeister Drohn in Ratschet 5 Savannenlöwenhauer, 5 Ebenenschreiternieren und 1 Donnerechsenhorn.", sourceObjectiveStatus = "unverified-source-field" }
quests[822] = { id = 822, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chens leeres Fässchen", description = "Gutes Zeug, dieses Sturmbräu, was?\n\nIch habe noch ein Rezept, das ich von Chen gelernt habe. Hättet Ihr Interesse? Die Herstellung dauert nicht lange und es könnte Euch nützlich sein, wenn Ihr Eure Abenteuer fortsetzen wollt.\n\nBringt mir 5 Blitzschlagdrüsen einer beliebigen Sturmechse, 1 Donnerfalkenspeicheldrüse von großen Donnerfalken und eine Kodoleber einer beliebigen Kodoart des Brachlandes.\n\nWie ich sagte, das Zeug hat es in sich; das ist das Troggbier, das ich kürzlich erwähnte.", sourceObjective = "Bringt Braumeister Drohn in Ratschet 5 Blitzschlagdrüsen, 1 Donnerfalkenspeicheldrüse und 1 Kodoleber.", sourceObjectiveStatus = "unverified-source-field" }
quests[823] = { id = 823, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bericht an Orgnil", description = "Auch wir in Sen'jin sind nicht ohne eigene Probleme und wir danken Euch für Eure Hilfe. Aber die Neuigkeiten, die Ihr über die Brennende Klinge bringt, können Probleme für jedermann bedeuten.\n\nIn Klingenhügel ist ein Orc stationiert, Orgnil Narbenseele, der Durotar vor solch Bösem wie der Brennenden Klinge bewacht! Geht zu Orgnil und berichtet ihm von unserer Not sowie von Euren Neuigkeiten über das Tal der Prüfungen. Er wird diese Dinge wissen wollen.\n\nKlingenhügel liegt im Norden.", sourceObjective = "Sprecht mit Orgnil Narbenseele in Klingenhügel.", sourceObjectiveStatus = "unverified-source-field" }
quests[824] = { id = 824, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Je'neu vom Irdenen Ring", description = "Der Irdene Ring ist eine schamanistische Gruppe, die sich dem Studium und dem Erhalt der Elemente widmet. Sie hat bereits mehr über verrückte Alte Götter und uralte Legenden und Lehren vergessen, als die meisten Gelehrten jemals in Erfahrung bringen werden.\n\nZu Eurem Glück kenne ich jemanden hier im Eschental, der Mitglied des Irdenen Rings ist. Geht hinüber zum Außenposten von Zoram'gar an der Küste des Zoramstrandes und zeigt Je'neu Sancrea, was Ihr gefunden habt. Wenn überhaupt jemand die Bedeutung dieser Kugel herausfinden kann, dann er.", sourceObjective = "Bringt die beschmutzte Wasserkugel zu Je'neu Sancrea in der Tiefschwarzen Grotte.\n\nBereitgestellter Gegenstand:", completion = "Diese Kugel... ist sehr beunruhigend. Viele der mächtigeren Elementare beziehen ihre Kraft und Energie aus solchen Gegenständen. Einen davon quasi intakt zu finden, ist eine Sache. Ihn dermaßen besudelt vorzufinden, eine ganz andere.\n\nIch werde dafür Sorge tragen, dass diese Kugel vom Irdenen Ring gründlich untersucht wird. Vielleicht können wir dieser Verderbnis der Elemente ein Ende bereiten. Bitte, nehmt dies zum Tausch dafür, dass Ihr die Aufmerksamkeit des Irdenen Rings auf diese Kugel gelenkt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[825] = { id = 825, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus den Wrackteilen geborgen...", description = "Einer meiner aufmerksamsten Späher hat mir Kunde gebracht, dass die Trümmer von Prachtmeers Flotte immer noch an der Küste Durotars liegen, gleich östlich von Burg Tiragarde.\n\nEs ist kein Geheimnis, dass die Menschen, die sich mit diesen elenden kleinen, als Gnome bekannte Kreaturen verbündet haben, über reichliches Wissen auf dem Gebiet der Mechanik verfügen. Wir müssen so viel wie möglich über unsere potenziellen Feinde in Erfahrung bringen. Dann kann unser Volk von diesem neuen Wissen profitieren.\n\nSchwimmt durch die Wrackteile, {name}, und bringt mir die Werkzeuge der Allianz.", sourceObjective = "Gar'Thok von Klingenhügel möchte, dass Ihr 3 Gnomenwerkzeuge aus den Wrackteilen vor der Küste holt.", sourceObjectiveStatus = "unverified-source-field" }
quests[826] = { id = 826, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zalazane", description = "Der Hexendoktor Zalazane lebt auf den Echoinseln im Osten. Das sind die Inseln, die wir einst Heimat nannten.\n\nVon dort aus entsendet er seine Trolle zum Festland, wo sie unser Volk verhexen und immer mehr von uns in ihren Bann ziehen.\n\nEr muss aufgehalten werden.\n\nBesiegt Zalazane und seine Diener - ehemalige Trolle der Dunkelspeere, die jetzt nicht mehr zu uns gehören. Bringt mir seinen Kopf, dann weiß ich, dass seine Schreckensherrschaft vorbei ist.", sourceObjective = "Besiegt Zalazane.\n\nTötet 8 Voodootrolle und 8 verhexte Trolle.\n\nBringt Gadrin Zalazanes Kopf.", sourceObjectiveStatus = "unverified-source-field" }
quests[827] = { id = 827, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Knochenhöhle", description = "{name}. Die Brennende Klinge hat die Knochenhöhle östlich von Orgrimmar besetzt. Sie führen in dieser Höhle schlimme Rituale durch und fügen sich durch Senghalsbänder selbst Brandwunden zu.\n\nIch glaube, indem sie diese Halsbänder tragen, bringen die Kultisten sich in Einklang mit dämonischen Mächten. Um das zu bestätigen, benötige ich jedoch ein paar dieser Halsbänder, um sie zu studieren.\n\nGeht zur Knochenhöhle und besorgt ein paar Senghalsbänder von den Kultisten, die Ihr dort findet. Bringt sie mir, dann werde ich ihre Geheimnisse enthüllen.", sourceObjective = "Besorgt von den Kultisten an der Knochenhöhle ein paar Senghalsbänder.\n\nBringt sie Margoz in seinem Lager.", sourceObjectiveStatus = "unverified-source-field" }
quests[828] = { id = 828, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Margoz", description = "Margoz, einer unserer Schamanen, weiß mehr über die Verderbnis der Brennenden Klinge. Er sprach von einer Höhle namens Knochenhöhle in den Bergen - gleich vor den Toren Orgrimmars! - dort soll sich eine große Gruppe von Kultisten der Brennenden Klinge eingenistet haben.\n\nBevor Ihr jedoch zur Knochenhöhle geht, sprecht mit Margoz. Er ist weise und sein Rat wird geschätzt.\n\nEr lagert im Nordosten zwischen der Küste und der Staubwindklamm.\n\nFolgt seinem Rat, aber was immer Margoz auch sagt, {name}, ich möchte, dass Ihr diese Kultisten vernichtet!", sourceObjective = "Sprecht mit Margoz.", sourceObjectiveStatus = "unverified-source-field" }
quests[829] = { id = 829, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neeru Feuerklinge", description = "Die Senghalsbänder, die Ihr mir brachtet, sind mächtige, dämonische Werkzeuge. Ihre Herkunft zu bestimmen liegt jedoch leider außerhalb meiner Künste als Schamane. Wir werden einen Hexenmeister bitten müssen, sie zu studieren.\n\nBringt ein Senghalsband zu Neeru Feuerklinge. Er ist zwar ein talentierter Hexenmeister, doch nutzt er seine Mächte nur, um Dämonen zu bekämpfen, und er behauptet, dass seine Forschungen auf dem Gebiet des Okkultismus gutartiger Natur sind. Ob es stimmt oder nicht, wir brauchen dennoch seine Hilfe gegen den Dämonenkult in Durotar.\n\nIhr findet Neeru in Orgrimmar in der Kluft der Schatten.", sourceObjective = "Bringt Neeru Feuerklinge in Orgrimmar ein Senghalsband-Muster.", sourceObjectiveStatus = "unverified-source-field" }
quests[830] = { id = 830, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Admiral's Orders" }
quests[831] = { id = 831, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Befehle des Admirals", description = "Menschen kann man nicht trauen. Wir haben immer mit wachsamen Augen an ihrer Seite gekämpft, weil wir wussten, dass sie uns eines Tages verraten würden.\n\nLeider war Admiral Prachtmeers Tod nicht genug, um sein Vermächtnis des Betrugs aufzuhalten. Der Menschenabschaum hatte vor seinem Ableben alles gut durchgeplant.\n\nSeine Herrschaft würde, wie es scheint, nicht einmal mit Benedict enden. Wer weiß, wann die nächste Welle von Prachtmeers Männern an unseren Küsten landen wird.\n\nWir müssen diese Befehle sofort zu Vol'jin in Orgrimmar bringen! Man findet ihn in Thralls Kammer.", sourceObjective = "Bringt Vol'jin in Thralls Kammer in Orgrimmar Admiral Prachtmeers Befehle.", sourceObjectiveStatus = "unverified-source-field" }
quests[832] = { id = 832, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burning Shadows" }
quests[833] = { id = 833, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine heilige Bestattung", description = "Nur die tapfersten Tauren werden bei den Teufelsfelsen, unserer heiligen Begräbnisstätte, bestattet. Es ist eine Ehre, die jenen großen Kriegern zuteil wird, die dazu beitrugen, Donnerfels zu gründen und zu verteidigen, und jenen, die ihr Leben für das Wohl ihres Stammes und ihrer Häuptlinge gegeben haben.\n\nNun sieht es jedoch so aus, als wäre es einer üblen Bedrohung gelungen, in unser heiliges Land einzudringen. Eine Gruppe Borstennacken verheert das Grabmal und ich bin zu alt und gebrechlich, um sie selbst zu vertreiben.\n\nSie müssen mit Gewalt von dort verjagt werden, {name}.", sourceObjective = "Tötet 8 Eindringlinge der Borstennacken bei den Teufelsfelsen.", completion = "Gut gemacht. Ihr habt diesen elenden Borstennacken eine deutliche Warnung erteilt. Sie werden es sich zweimal überlegen, bevor sie erneut versuchen, sich an diesem heiligen Ort zu vergreifen.", sourceObjectiveStatus = "unverified-source-field" }
quests[834] = { id = 834, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wind in der Wüste", description = "Ich bin Rezlak, einer von Gazlowes Jungs. Boss hat mich geschickt, den Orcs hier in Durotar unter die Arme zu greifen. So weit läuft alles klar, abgesehen von den Karawanen. Ich schaff's einfach nicht, sie zu sichern! Das erschwert mir meinen Job ganz schön, wisst Ihr?\n\nDie letzte Lieferung, meine Güte, die hatten garantiert, dass sie durchkommt! Aber sie wurde von den Staubschwingenharpyien von... wo war das noch... in der Klingenschlucht geklaut.\n\nIch muss dieses Zeug zurückhaben! Folgt dem großen Canyon nach Süden, dort findet Ihr eine Klamm direkt westlich und östlich der Wände.", sourceObjective = "Beschafft 5 Vorratssäcke.", progress = "Ich bin gut, in dem was ich tue, versteht mich jetzt nicht falsch, aber das ist lächerlich! Was soll ich tun, Sandburgen bauen?", completion = "He, ist das nicht ein Ding? Ihr habt unsere Vorräte zurückgeholt. Is' ja doll. Jetzt kann ich mich wieder an die Arbeit machen, sobald ich ein paar Leute gefunden habe, die diese Säcke für mich schleppen.", sourceObjectiveStatus = "unverified-source-field" }
quests[835] = { id = 835, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sicherung der Linien", description = "Gazlowe sagte mal zu mir: Rezlak. Eines musst du im Leben wissen: Wenn du was richtig gemacht haben willst, dann tu's selbst.\n\nIch kann es mir nicht leisten, all unsere Karawanen zu verlieren, also muss ich die Sache selbst in die Hand nehmen. Harpyien stören unsere Versorgungsroute. Wenn wir alle Harpyien töten, sind die Karawanen wieder sicher.\n\nNatürlich gab's da noch was, das Gazlowe mir beigebracht hat, und das ist: \"Mit dem nötigen Kleingeld kann man alles erreichen.\" Seid Ihr dabei, {name}? Gut... Ich empfehle Euch, es zuerst in dem Canyon im Osten zu versuchen.", sourceObjective = "Tötet 12 Harpyien aus Durotar. Es genügt jede beliebige Art von Harpyie.", completion = "Ich glaube, ich kann jetzt wieder ruhiger schlafen, da ich weiß, dass die Harpyien unsere Versorgungskarawanen nicht mehr angreifen. Wurde auch langsam Zeit. Wie ich hörte, kommen mit der nächsten Lieferung ein paar nette Spielsachen für mich!\n\nIhr seid ziemlich gut, in dem was Ihr tut, {name}, solltet mal meinen Boss in Ratschet aufsuchen. Ich wette, er hat ein bisschen Arbeit für Euch.\n\nOh, und macht Euch keine Sorgen, ich vergess nicht, Euch für Eure Dienste zu bezahlen.", sourceObjectiveStatus = "unverified-source-field" }
quests[836] = { id = 836, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet OOX-09/HL!", description = "Aus dem Roboter ertönt erneut die blecherne Stimme des Gnoms:\n\n\"Ich muss OOX-09/HL an einen offenen, sicheren Ort schaffen, wo er die langwierige Startprozedur beginnen kann. Er hat eine eingebaute Tarnvorrichtung, aber ich brauche etwas Zeit, um sie von hier aus wieder funktionstüchtig zu machen. Eskortiert den Roboter von seinem derzeitigen Standort zu, sagen wir, ein paar großen Felsen, die die Sicht versperren! Das sollte der perfekte Ort für mein Vorhaben sein, und bis Ihr dort seid, sollte ich auch alles vorbereitet haben und online gehen können.\"\n\n\"Eskortiert ihn dorthin und kommt dann zu mir nach Beutebucht! Glotz Widrikus - Ende!\"", sourceObjective = "Bringt OOX-09/HL in Sicherheit und meldet Euch dann bei Glotz Widrikus in Beutebucht.", completion = "Ach, IHR habt so heldenhaft OOX-09/HL gerettet! Ich kann Euch gar nicht sagen, wie dankbar ich für Eure Hilfe bin! In meine Serie von Leitrobotern muss noch viel Entwicklungsaufwand gesteckt werden, aber Eure Bergung des Roboters hat mir zahllose Stunden zusätzlicher Schraubarbeit gespart, ganz zu schweigen von dem vielen Gold, das ich spare, weil ich ihn nicht neu bauen muss!\n\nBitte sucht Euch einen von diesen Gegenständen hier aus. Ich danke Euch nochmals für Eure großzügige Hilfe, {name}, meine Roboter und ich stehen in Eurer Schuld!", sourceObjectiveStatus = "unverified-source-field" }
quests[837] = { id = 837, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übergriff", description = "Als wir hier ankamen, war ein Großteil des Landes im Besitz der Klingenmähnenstacheleber, die sich als ein ziemlicher Dorn im Auge erwiesen. Durch unsere Anstrengungen konnten wir einen großen Teil von ihnen vertreiben, aber es gibt doch noch welche, die sich in einigen Gebieten verschanzt haben.\n\nDas geht jetzt jedoch schon viel zu lange so. Zu unserer eigenen Sicherheit dürfen wir nicht zulassen, dass sich die Klingenmähnen in unserem Land festsetzen. Ihre Lager befinden sich westlich von hier. Sucht nach dem Dornengestrüpp, dann findet Ihr sie. Heute vertreiben wir sie aus Durotar, morgen vielleicht schon aus Kalimdor.", sourceObjective = "Tötet für Gar'Thok in Klingenhügel 4 Stacheleber der Klingenmähnen, 4 Späher der Klingenmähnen, 4 Staubläufer der Klingenmähnen und 4 Schlachtwachen der Klingenmähnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[838] = { id = 838, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scholomance", description = "Auf der Insel Darrowehr liegt die Scholomance - eine Schule, die als Festung für die Geißel dient. Unser Feind haust dort, wo er sicher Forschungen betreiben kann, die seine Macht stärken. Eine Tür versperrt den Weg, und ganz gleich was wir versuchen, der Zutritt ist nur mit dem richtigen Schlüssel möglich.\n\nApotheker Zitters weiß viel über die Scholomance und hat eine Idee, wie ein Schlüssel zu erlangen ist. Ihr habt mir Euren Wert als jemand bewiesen, der knifflige Dinge erledigen kann; ich vertraue Euch nun diese Aufgabe an. Sprecht mit ihm über diese Angelegenheit.", sourceObjective = "Sprecht mit Apotheker Zitters am Bollwerk in den Westlichen Pestländer.", sourceObjectiveStatus = "unverified-source-field" }
quests[840] = { id = 840, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freiwilliger der Horde", description = "Hmmm, Ihr seht mir recht stark aus.\n\nHört mal, mein guter Freund Kargal braucht ein paar neue Rekruten für den Dienst im Brachland. Ich weiß, dass Ihr immer nur das Richtige für die Horde tun wollt. Das ist jetzt Eure Chance.\n\nBringt Kargal diesen Anwerbungsbrief und seht, ob er ihn unterzeichnet.", sourceObjective = "Gebt Kargal Schlachtnarbe im Brachlandaußenposten Euren Anwerbungsbrief.", progress = "Was wollt Ihr, Jungspund? Wenn Ihr nicht wegen einer Anwerbung hier seid, habe ich keine Zeit für Euch.", completion = "Oh, Takrin schickt Euch also?\n\n<Kargal beäugt Euren Anwerbungsbrief misstrauisch und stopft ihn kurzerhand in sein Wams.>\n\nDen werde ich unterschreiben, wenn Ihr es Euch verdient habt. Ich habe Berichte aus dem Süden erhalten, dass dieser gesamte Kontinent auseinandergerissen wird. Und währenddessen drängen sich Nachschubkarawanen bis zum Fluss und unsere Außenposten von hier bis zum Steinkrallengebirge werden belagert. Ihr wollt Euch der Horde unter Beweis stellen? Dann fangt mal an, Euch hier zu beweisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[841] = { id = 841, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine weitere Kraftquelle?", description = "Ich stelle mal eine Vermutung an - Ihr habt, welch weltbeendende, ruchlose Tat Ihr auch unternommen habt, diese Tat nicht rechtzeitig beendet. Nein, wartet, noch besser... Ihr habt die Sache in den Sand gesetzt! Nun, was auch immer der Grund sein mag, ich verfüge über eine weitere Kraftquelle, die ich Euch verkaufen werde. Dieses Mal wird sie Euch aber zehn, JAWOHL ZEHN Wasserbeutel eines Wüstenläufers kosten!\n\nDie Zeiten hier sind schwer, {name}, und Kraftquellen wachsen nicht auf Bäumen! Hmm, aber was wäre wohl, wenn sie es täten... Vielleicht könnten wir einen Kraftquellenbaum MACHEN...", sourceObjective = "Bringt Chefingenieur Bilgenritzel in Gadgetzan 10 Wasserbeutel eines Wüstenläufers im Austausch gegen eine weitere Kraftquelle.", sourceObjectiveStatus = "unverified-source-field" }
quests[842] = { id = 842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crossroads Conscription" }
quests[843] = { id = 843, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ganns Rekultivierung", description = "In Einsamkeit wandere ich auf diesen Straßen.\n\nDie Zwerge Bael Modans haben keinen Respekt vor meinem Land. Entsetzliche Schläge reißen tiefe Wunden in den Boden und brüllende Maschinen zerfetzen die Hügel. Land, das meinem Stamm einst als Heimat und Versorger diente, ist jetzt von zerstörerischen Zwergen durchfurcht.\n\nAlle Versuche, zu einer diplomatischen Einigung zu kommen, sind fehlgeschlagen. Jetzt ist die Zeit für entschlossenes Handeln gekommen.\n\nVertreibt die Zwerge mit Gewalt von der Bael Modan-Ausgrabung und bringt mir das Tagebuch ihres Anführers, Ausgrabungsleiter Khazgorm.", sourceObjective = "Gann Steinkeil möchte, dass Ihr 15 Ausgräber von Bael'dun und 5 Großknechte von Bael'dun tötet.\n\nBringt Gann Steinkeil dann Khazgorms Tagebuch.", sourceObjectiveStatus = "unverified-source-field" }
quests[844] = { id = 844, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ebenenschreiterbedrohung", description = "Kennt Ihr die Ebenenschreiter? Nutzlose Viecher. Können nicht fliegen. Schmecken nicht. Gehirne so groß wie meine Knöchel. Zu blöd, einem fahrenden Karren auszuweichen. Ich habe mir an deren dicken Schädeln schon mehr Achsen gebrochen... Manchmal glaube ich, die Stacheleber scheuchen Schwärme von denen in die Bahn unserer Karawanen, um ihre Hinterhalte vorzubereiten.\n\nMacht mich stolz, {class}. Schlagt Euch eine Bresche durch diese dreckigen Vögel, damit die Straßen frei bleiben und bringt mir ihre Schnäbel als Beweis.", sourceObjective = "Sammelt 7 Ebenenschreiterschnäbel.", progress = "Habt Ihr die Ebenenschreiterschnäbel schon?", completion = "Sehr gut, {name}. Eine Sorge weniger, über die man sich unterwegs Gedanken machen muss.", sourceObjectiveStatus = "unverified-source-field" }
quests[845] = { id = 845, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zhevras", description = "Wenn Ihr meiner geliebten Horde dienen wollt, dann müsst Ihr mir Eure Stärke beweisen, Welpe. Die Zhevrajagd wird Euch einen guten Anfang bieten. Zwar sind sie nicht die mächtigsten Tiere im Brachland, aber wenn man sich nicht vor ihren Tritten in Acht nimmt, bereut man es schnell.\n\nMacht Jagd auf die Zhevras im Norden und Süden und sammelt ihre Hufe. Bringt sie mir und vielleicht setzen wir Euch das nächste Mal auf etwas Stärkeres an.", sourceObjective = "Erschlagt Zhevraläufer, um 4 Zhevrahufe zu erhalten.", progress = "Wie viele Zhevras habt Ihr schon erschlagen?", completion = "Nicht schlecht, {name}. Diese Zhevras haben sehr viel Kraft in ihren Beinen. Ein gezielter Tritt von ihnen kann sogar einen {race} von den Hufen hauen!\n\nSieht aus, als würdet auch Ihr über ein bisschen Kraft verfügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[846] = { id = 846, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ganns Rache", description = "Es ist klar, dass ein Ausgrabungsleiter von Sprengstoff und diesen lärmenden Fahrzeugen abhängig ist, um den Boden aufzureißen. Wir müssen damit rechnen, dass schon bald ein neuer Großknecht die Sache übernimmt.\n\nIch möchte den Zwergen ihre eigene Medizin zu schmecken geben. Wenn wir laut diesen Plänen Nitroglyzerin mit Holzbrei und Natriumnitrat mischen, erhalten wir eine Sprengladung. Es ist bekannt, dass die Scharfschützen, Soldaten und Offiziere in der Burg diese Dinge besitzen.\n\nHolt diese Sachen und bringt sie mir; ich werde daraus eine Sprengladung basteln, die die Zwerge so schnell nicht vergessen werden!", sourceObjective = "Gann Steinkeil möchte, dass Ihr ihm 6 Phiolen Nitroglyzerin, 6 Teile Holzbrei und 6 Proben Natriumnitrat bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[847] = { id = 847, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arglist des Raptors", description = "Diese... diese Macht... Ist das die Macht der Schamanen, die Tor'gan mir zeigen wollte? Ich muss sagen, das ist wirklich interessant. Sagt Tor'gan, dass er mich überzeugt hat... jedenfalls für den Augenblick. Ich werde mir anhören, was er zu sagen hat.", sourceObjective = "Sprecht mit Tor'gan in Hammerfall im Arathihochland.", sourceObjectiveStatus = "unverified-source-field" }
quests[848] = { id = 848, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pilzsporen", description = "Die Oasen des Brachlandes verbergen ein Mysterium. In ihren Wassern fließt Lebensenergie, die alle Pflanzen und Wildtiere erquickt, die davon trinken.\n\nEs erquickt und verändert sie.\n\nBei den Oasen im Nordwesten wächst ein bestimmter Pilz. Seine Sporen besitzen Eigenschaften, die wir, die Apotheker Lordaerons, sehr nützlich finden.\n\nBringt mir diese Sporen, dann ist Euch unser Dank gewiss.", sourceObjective = "Sammelt 5 Pilzsporen von den Pilzen an den Vergessenen Teichen.", progress = "Habt Ihr die Sporen, {name}? Meine Kollegen und ich brennen darauf, dieses Phänomen zu untersuchen...", completion = "Ah, ja. Das sind wirklich Prachtexemplare. Sehr wirksam.\n\nIch bin ein Verlassener und wir halten unsere Versprechen. Hier ist Eure Belohnung, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[849] = { id = 849, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ganns Rache", description = "Wenn wir uns an Khazgorms Pläne halten, sollte es eigentlich kein Problem sein, eine Sprengladung herzustellen.\n\nAh, fertig.\n\nAlso, {name}, ich möchte Euch mit einer besonderen Aufgabe betrauen. Nehmt diese Dynamitstange und jagt damit den Flugapparat bei Bael Modan in die Luft.\n\nDieser Flugapparat ist nicht nur ein wichtiger Bestandteil der Infrastruktur der Grabungsstätte, sondern auch eine Kriegswaffe. Vor allem ist sie aber ein Symbol der Macht und eine Beleidigung des Andenkens an meinen Stamm.\n\nMacht mich stolz, indem Ihr diese heldenhafte Aufgabe erledigt, dann soll es Euer Schaden nicht sein.", sourceObjective = "Zerstört den Flugapparat bei Bael Modan und kehrt dann zu Gann Steinkeil zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[850] = { id = 850, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anführer der Kolkar", description = "Die Zentauren sind den Tauren schon seit Jahren ein Dorn im Auge. Die Kolkarzentauren des Brachlandes sind vor Kurzem zu einer echten Bedrohung geworden. Normalerweise sind sie in diesen Landen eher unorganisiert, aber es haben sich unter ihnen neue Anführer erhoben. Sie sammeln sich.\n\nWir müssen diese Zentaurenanführer vernichten, um unsere Position hier zu bewahren.\n\nBringt mir den Kopf von Barak Kodobann. Er lagert westlich der Vergessenen Teiche.\n\nBesiegt ihn und kehrt dann zu mir zurück.", sourceObjective = "Tötet Barak Kodobann und nehmt seinen Kopf an Euch.", progress = "Hallo, {name}. Bringt Ihr mir Kodobanns Kopf?", completion = "Gut gemacht, {name}. Kodobann ist nur ein einziger Faden in einem ganzen Knäuel - andernorts im Brachland gibt es noch weitere Anführer der Kolkar zu töten. Sucht meine Gefährten an den anderen Oasen auf, wenn ihr den Angriff vorantreiben wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[851] = { id = 851, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verog der Derwisch", description = "Verog ist zwar schwer aufzuspüren, aber den Informationen zufolge, die Ihr gesammelt habt, ist seine Gefährtin Wyneth immer in seinem Kommandozelt westlich von hier zu finden. Wenn wir sie töten, wird Verog in Windeseile auftauchen.\n\nRegthar hat uns zum Auskundschaften hierher geschickt, aber er sagte auch, wir sollen jede Gelegenheit nutzen, die Befehlskette der Zentauren zu stören. Lockt Verog aus der Defensive und tötet ihn!", sourceObjective = "Tötet Wyneth, um Verog den Derwisch hervorzulocken. Erschlagt ihn dann und nehmt seinen Kopf an Euch.", progress = "Habt Ihr Verog gefunden, {name}?", completion = "Ihr habt es geschafft! Das wird das Kräfteverhältnis hier unten wirklich verändern. Verog hinterlässt keinen eindeutigen Nachfolger, also vermute ich, dass dieser Schlägertrupp übereinander herfallen wird wie eine Meute reißender Hunde. Ich werde hier zurückbleiben und ein Auge auf die weiteren Entwicklungen haben.\n\nVerog unterstand direkt dem Kolkarhäuptling - ihn zu töten ist ein guter Anfang, aber es gibt noch mehr zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[852] = { id = 852, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hezrul Blutmal", description = "Hezrul Blutmal ist der Anführer der Kolkarzentauren im Brachland. Er ist wild, brutal und schlau. Könnte man ihn besiegen, würde das die Kolkar spalten und zerschlagen und die Bedrohung durch sie enorm entschärfen.\n\nAlso tötet ihn. Bringt mir Hezruls Kopf und ich werde ihn in diesem Außenposten aufspießen, damit sie Furcht kennenlernen.\n\nEr führt sein Volk von der Blühenden Oase im Süden aus an.", sourceObjective = "Tötet Hezrul Blutmal und nehmt seinen Kopf an Euch.", progress = "Ist Hezrul besiegt, {name}?", completion = "Ich muss Euch loben, {name}. Diese Zentauren sind undiszipliniert und können ihre Wut nicht so konzentrieren wie die Orcs, aber sie sind dennoch unerbittlich wild. Ihr habt Euren Wagemut bewiesen, indem Ihr sie besiegtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[853] = { id = 853, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Apothekerin Zamah", description = "Ich habe die Sporen, die Ihr mir gabt, zu einer Emulsion verarbeitet. Die muss ich jetzt meiner Kollegin schicken, der Apothekerin Zamah. Wenn Ihr sie ihr bringen könntet, würde sie Euch bestimmt etwas aus ihrem Vorrat alchemistischer Waren anbieten.\n\nSie lebt bei den Teichen der Visionen in einer Höhle unter den Schamanen von Donnerfels. Der Pfad zu dieser Höhle ist gut versteckt, aber Ihr könnt ihn am Steilhang der Anhöhe der Geister finden.\n\nBeeilt Euch. Die Emulsion verliert nach einer Weile ihre Wirksamkeit und muss vorher luftdicht verschlossen und weiterverarbeitet sein.", sourceObjective = "Bringt der Apothekerin Zamah in Donnerfels die weiterverarbeiteten Sporen, bevor die Zeit abgelaufen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[854] = { id = 854, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reise zum Wegekreuz", description = "Ich habe Eure Ankunft vorausgesehen, <junger/junge:c> {class}. Aber vielleicht seid Ihr ja gar nicht mehr so jung.\n\nIch glaube, dass es an der Zeit ist, dass Ihr Euch tiefer in dieses Land vorwagt. Ich fühle, dass Ihr zu Größerem berufen seid.\n\nDas Wegekreuz wartet auf Euch, denn die Orcs, mit denen wir eng verbunden sind, brauchen Unterstützung. Folgt dieser Straße weiter nach Osten und dann weiter nach Norden bis zum Wegekreuz. Sucht Thork in seinen Mauern, er hat den Segen der Erdenmutter.", sourceObjective = "Sprecht mit Thork beim Wegekreuz im Brachland.", sourceObjectiveStatus = "unverified-source-field" }
quests[855] = { id = 855, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zentaurenarmschienen", description = "Die Führungsspitze der Zentauren stützt sich auf einen Kern von vertrauenswürdigen, disziplinierten Kriegern, die dafür sorgen, dass die anderen Zentauren nicht aus der Reihe tanzen. Wenn wir diese Ränge lichten, werden die Kolkar nicht die nötige Macht haben, ihrem Zorn Taten folgen zu lassen. Also habe ich für Euch eine gewinnbringende Aufgabe.\n\nTötet Marodeure und Sturmseherinnen der Kolkar in der Umgebung der Blühenden Oase im Süden, um deren Armschienen zu erbeuten. Kehrt zurück wenn Ihr einen Haufen dieser Trophäen habt und die Horde wird Euch reich belohnen.", sourceObjective = "Sammelt 10 Zentaurenarmschienen von Marodeuren und Sturmsehern der Kolkar.", progress = "Wie läuft Eure Jagd, {name}?", completion = "Sehr gut gemacht. Ihr habt den überlebenden Zentauren bestimmt eine Heidenangst eingejagt, {name}. Nun da ihre mächtigsten Krieger tot sind, werden sie entweder ihre Angriffe aufgeben, oder uns leichtsinnig überfallen.\n\nIch hoffe auf Letzteres.", sourceObjectiveStatus = "unverified-source-field" }
quests[857] = { id = 857, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Träne der Monde", description = "Ich hatte die Macht! In diesen meinen Händen! Und ich möchte sie wiederhaben! Wiederhaben möchte ich sie!\n\nDiese dreckigen Ausgräber haben sie entdeckt... sie war so wunderschön. Die Träne der Monde war die erste größere Entdeckung, die wir in Bael Modan gemacht haben.\n\nSie hätte mir gehören sollen! Mir!\n\nGeneral Doppelzopf war eifersüchtig auf die Macht, die sie mir verlieh; er sperrte sie weg, in der Burg. Sagte, sie sei verflucht! Dieser Dummkopf!\n\nAndere wollten sie auch haben und sie mussten daran gehindert werden! Dieses Scheusal Doppelzopf jagte mich weg.\n\nJetzt möchte ich sie wiederhaben. Wiederhaben möchte ich sie!", sourceObjective = "Feegly der Verbannte möchte, dass Ihr ihm die Träne der Monde zurückbringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[858] = { id = 858, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zündung", description = "Euch hat nicht etwa Stotterspritter geschickt? Ich stecke in der Klemme. Ich bin hier reingesprungen, ohne daran zu denken, dass ich einen Schlüssel brauche, um die Antriebswelle des Schredders aufzuschließen. Einer der anderen Schredderbediener fragte mich, ob alles in Ordnung sei, und da bin ich in Panik geraten! Statt ihm zu sagen, dass ich meinen Schlüssel nicht dabei hatte, sagte ich ihm, dass es irgendeine mechanische Störung gäbe.\n\nWir müssen hier weg, und zwar schnellstens! Durchsucht die oberste Ebene der Plattform, Vorsteher Lugwizz sollte einen Schlüssel für diesen Schredder haben.\n\nHelft mir hier raus!", sourceObjective = "Holt den Zündschlüssel von Vorsteher Lugwizz.", progress = "Schnell, wir müssen hier weg, bevor jemand misstrauisch wird!", completion = "Ja, das sieht nach dem richtigen Schlüssel aus. Lasst mich nur kurz sehen, wie dieses Ding funktioniert...\n\nHmm... Rotationssteuerung... Damit werden Tempo und Stabilität reguliert... Auslegerfeinsteuerung. Seht Euch das nur mal an! Ich fasse es nicht, dass die Venture Company etwas entwickelt hat, das so viel besser ist als unseres. Ich muss das zum Außenposten zurückbringen!", sourceObjectiveStatus = "unverified-source-field" }
quests[860] = { id = 860, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sergra Dunkeldorn", description = "Wenn Ihr den Pfad der Jäger beschreiten möchtet, dann führt Euch Eure Reise ins Brachland. Die dortigen Wildtiere sind willensstark und unglaublich wild. Ihr werdet beim Jagen dort viel lernen und Euer Geist wird sich entfalten.\n\nSprecht mit Sergra Dunkeldorn. Sie wird im Brachland Eure Führerin sein.\n\nSergra ist beim Wegekreuz zu finden. Um zu ihr zu gelangen, müsst Ihr vom Dorf der Bluthufe aus gen Osten ins Brachland reisen und dann an der Weggabelung nach Norden abbiegen. Und seid vorsichtig auf dieser Reise - das Brachland hält für die Unvorbereiteten und Unachtsamen große Gefahren bereit.", sourceObjective = "Sprecht beim Wegekreuz mit Sergra Dunkeldorn.", sourceObjectiveStatus = "unverified-source-field" }
quests[861] = { id = 861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg der Jäger", description = "Euch hat das Jagdfieber gepackt, wie ich sehe. Auch ich war einst wanderlustig...\n\nWollte wandern und jagen. Denn die Jagd ist die größte Ehre für einen Tauren.\n\nWenn Ihr ernsthaft das Leben eines Jägers führen wollt, dann beweist mir Eure Geschicklichkeit und Entschlossenheit. Bringt mir die Krallen der Flachlandstreuner in Mulgore. Sie sind zäh und gerissen - <ein junger/eine junge:c> {class} auf der Pirsch sollte sich mit ihnen messen können.", sourceObjective = "Erhaltet 4 Flachlandstreunerklauen.", progress = "Wir verläuft Eure Jagd, {name}?", completion = "Gut gemacht, Jüngling.", sourceObjectiveStatus = "unverified-source-field" }
quests[862] = { id = 862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grubenratteneintopf", description = "<Ein/Eine:c> {class} wie Ihr muss hier im Brachland doch ziemlich hungrig sein. Ich bin den ganzen Tag am Verhungern.\n\nIch sag Euch was, ich bereite Euch einen feinen Eintopf zu. Ich brauche nur ein paar Grubenratten.\n\nScheint so, als würden diese dreckigen Zwerge in Bael Modan von unser aller Lieblingsspeise überrannt. Also reist gen Süden nach Bael Modan und bringt mir ein paar Grubenratten.\n\nIhr dürft Euch erst einen erfahrenen Abenteurer nennen, wenn Ihr Euch ein bisschen mit der Rattenjagd beschäftigt habt! Ha!", sourceObjective = "Bringt Grub östlich des Wegekreuzes 8 Grubenratten.", sourceObjectiveStatus = "unverified-source-field" }
quests[863] = { id = 863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Flucht", description = "Ich würde mal sagen, ich kann das nach und nach lernen... Kann ja nicht so schwer sein. Ein paar Knöpfchen hier, ein oder zwei Hebelchen da... Also, seid Ihr bereit zu gehen?", sourceObjective = "Beschützt Kurbelwizz und den gestohlenen Goblinschredder auf dem Weg aus dem Schlickmoor heraus.", completion = "Er hat ihn geschrottet?!\n\n<Stotterspritter murmelt ärgerlich vor sich hin, bevor er fortfährt.>\n\nHoffentlich liefert uns dieser Prototyp-Schrotthaufen etwas Brauchbares... mir läuft langsam die Zeit davon! Ich fange mal an, diesen Burschen hier auseinanderzunehmen, dann sehen wir schon, wie er funktioniert.\n\nOh, hier habt Ihr noch etwas für Eure Mühen.", sourceObjectiveStatus = "unverified-source-field" }
quests[864] = { id = 864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kehrt zu Apothekerin Zinge zurück", description = "\"Wir sind so weit, die Kraftquelle ist entfernt und die Daten sind gesichert. Also dann, sichere Reisen und all das. Ich hoffe, das ruchlose Wissenschaftsexperiment hat sich für Euch ausgezahlt.\"\n\nDer Goblin wendet sich von Euch ab, um sich den Belangen der Gadgetzan Water Company zu widmen. Ihr verstaut das versiegelte Testset sicher für die Reise zurück nach Unterstadt. Dort wartet Apothekerin Zinge auf Euch und das versiegelte Feldtestset.", sourceObjective = "Bringt das versiegelte Feldtestset nach Unterstadt zu Apothekerin Zinge.", sourceObjectiveStatus = "unverified-source-field" }
quests[865] = { id = 865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es muss im Horn stecken", description = "Die Raptoren des Brachlandes sind intelligenter als die Raptoren anderer Länder. Und ich glaube, dass ihre ganze Intelligenz in ihren Hörnern sitzt! Wenn dem so ist, könnte ich ihre Hörner zu Pulver zermahlen und benutzen, um \"Klugheitstränke\" zu kreieren. Dafür würde ich ein Vermögen bekommen!\n\nUnd Ihr könntet mir helfen: Ich will das Horn des klügsten Raptors weit und breit. \"König Schnitterklaue\" führt ein ganzes Rudel intelligenter Raptoren an, oben auf den Klippen nördlich von Ratschet. Bringt mir sein Horn! Und lasst Euch nicht in Fetzen reißen wie all die anderen, die ich geschickt habe.", sourceObjective = "Erhaltet das Horn von König Schnitterklaue.", progress = "Habt Ihr das Horn von König Schnitterklaue, {name}? Ich muss meinen ersten Klugheitstrank testen!", completion = "Toll, Ihr habt es! Jetzt muss ich es nur noch zermahlen und mit etwas Wein vermischen und...", sourceObjectiveStatus = "unverified-source-field" }
quests[866] = { id = 866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wurzelproben", description = "Die Kräuter des Brachlandes sind anders als Kräuter anderer Länder. Ihre Eigenschaften sind zwar fast dieselben, aber das Oasenwasser hier verändert die Pflanzen; sie sind ein klein bisschen anders.\n\nIch möchte diese Unterschiede studieren... um zu sehen, ob man daraus nicht Kapital schlagen kann!\n\nFalls Ihr in der Kräuterkunde bewandert seid, sammelt doch ein paar Wurzelproben der Kräuter, die Ihr im Brachland findet. Bringt mir diese Proben, damit ich sie mit Kräutern aus anderen Regionen vergleichen kann.", sourceObjective = "Sammelt 8 Wurzelproben von den Kräutern im Nördlichen Brachland.", progress = "Hallo, {name}. Habt Ihr die Wurzelproben?", completion = "Ja, ja, die sind wirklich gut! Aus diesen Wurzeln werde ich Pflanzen ziehen, die ich dann studieren kann. Ich erhoffe mir, ein paar neue Eigenschaften daran zu finden. Versteckte, wertvolle Eigenschaften...!\n\nUnd keine Sorge - sollte ich etwas finden, seid Ihr der Erste, der es erfährt. Weil ich dann jemanden brauche, der noch mehr sammelt!", sourceObjectiveStatus = "unverified-source-field" }
quests[867] = { id = 867, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Räuberische Harpyien", description = "Da Ihr gerade hier seid, könnt Ihr mir vielleicht bei einem kleinen Problem helfen. Die verdammten Harpyien haben unsere Karawanen lang genug geplündert; es ist an der Zeit, dass wir einigen von ihnen die Hälse abschneiden und ihre Anzahl verkleinern.\n\nDer vernichtendste Angriff wird einen guten Teil ihrer niederen Befehlskette zerstören und dann können wir uns bis zur Spitze vorarbeiten.\n\nWir fangen langsam an; schaltet beliebige Harpyien der Hexenschwingen im Nordwesten aus und bringt mir 6 Krallen der Hexenschwingen. Das sollte ein guter Anfang sein...", sourceObjective = "Sammelt 6 Krallen der Hexenschwingen von den Harpyien der Hexenschwingen.", sourceObjectiveStatus = "unverified-source-field" }
quests[868] = { id = 868, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eierjagd", description = "He, {name}. Man hat mich zum Wegekreuz geschickt, damit ich über das Land wache und meinen Meistern in Orgrimmar über eventuelle Vorkommnisse berichte.\n\nEines meiner Studienobjekte sind die insektenartigen Kreaturen, die man im Süden auf dem Feld der Riesen findet. Wir wissen nur wenig über diese Kreaturen, also haben wir es uns zur Aufgabe gemacht, mehr über sie zu erfahren. Sie scheinen intelligent zu sein, intelligenter als normale Tiere.\n\nNehmt diese Gräberklaue und grabt ein paar ihrer Eier aus den Hügeln aus, aber seid vorsichtig: einmal aufgeschreckt, werden sie Euch angreifen.", sourceObjective = "Bringt Korran beim Wegekreuz 12 Silithideneier und die Gräberklaue.", sourceObjectiveStatus = "unverified-source-field" }
quests[869] = { id = 869, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie man einen Dieb aufspürt", description = "Tierfährten umgeben die Trümmer, Fährten, die von enormen geschwungenen Klauen hinterlassen wurden. Es scheinen Raptorenspuren zu sein.\n\nEuer erster Verdacht ist, dass Raptorenreiter die Karawane überfallen haben, aber die Abdrücke sind nicht tief und es lassen sich keine Spuren finden, die nicht von Tieren stammen.\n\nDie Fährte führt nach Nordosten hin zur Ostseite vom Dornenhügel. Die Antwort auf dieses Rätsel muss in dessen Schatten liegen.", sourceObjective = "Die Fährte führt zur Ostseite vom Dornenhügel. Folgt ihr und schaut, was sich herausfinden lässt.", sourceObjectiveStatus = "unverified-source-field" }
quests[870] = { id = 870, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Vergessenen Teiche", description = "Habt Ihr das Beben gespürt, {class}? Irgendetwas hat das Land gespalten. Aber wir Druiden können auch noch andere Beben wahrnehmen.\n\nNeues Leben regt sich in einst trockenen und leblosen Landen. Die Oasen rund um das Wegekreuz erblühen plötzlich. Ich verspüre eine Macht, die an die Oberfläche hervordringt, nur woher? Hat dies etwas mit der Katastrophe zu tun, die das Brachland zerteilt hat?\n\nWir müssen dem auf den Grund gehen. Reist zu den Vergessenen Teichen nordwestlich des Wegekreuzes. Durchsucht die dortigen Gewässer nach einer Machtquelle und kehrt dann hierher zurück.", sourceObjective = "Sucht den Grund der Vergessenen Teiche nordwestlich des Wegekreuzes ab.", completion = "Ihr habt einen Riss in der Erde gefunden, aus dem Energie strömte? Seltsam. Irgendetwas verursacht, dass die Oase plötzlich vor Leben nur so übersprudelt.\n\nKommt, {class}, es gibt noch etwas anderes, das ich mit Euch untersuchen möchte.", sourceObjectiveStatus = "unverified-source-field" }
quests[871] = { id = 871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verteidigung der Fernwacht", description = "Alle Stacheleber sind unsere Feinde, {name}. Manche sind nur lästiger als andere.\n\nDer Klingenmähnenstamm hat unsere Nachschublinien von Durotar aus angegriffen, was uns nicht wenig Ärger bereitet. Ich habe Späher ausgeschickt, um den Anführer dieser Überfälle zu finden, aber bis es so weit ist, könnte es uns schon helfen, wenn Ihr diese dreckigen Schweinemenschen etwas dezimieren würdet.\n\nBeginnt südlich von hier, wo sie unsere Lager am Fluss angegriffen haben. Sucht sie und erschlagt sie.", sourceObjective = "Tötet 8 Brandschatzer der Klingenmähnen und 3 Jäger der Klingenmähnen.", completion = "Das habt Ihr gut gemacht, {name}. Diese unverschämten Stacheleber werden irgendwann lernen, dass mit der Stärke der Horde nicht zu spaßen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[872] = { id = 872, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Angriff der Fernwacht", description = "Amoklaufende Schweinemenschen direkt an der Grenze zu Durotar? Nicht mit mir! Wie es so schön heißt, {name}: Die beste Verteidigung ist alle zu zermalmen, die dir im Weg stehen.\n\nEiner meiner Späher ist den Stachelebern nach deren letztem Überfall auf unsere Karawane gefolgt und wir wissen nun, wo wir zuschlagen müssen. Kreenig Grantelschnauze ist der Drahtzieher hinter den Angriffen entlang des Flusses. Zerquetscht ihn, {class}. Besiegt ihn und schlitzt seinen Truppen die Bäuche auf, so dass die Angriffe auf dieses Lager ein Ende haben.\n\nSucht nach einer mit Stachelebern verseuchten Höhle entlang des Flusses, südlich von unseren Ställen.", sourceObjective = "Tötet 5 Verteidiger der Klingenmähnen, 5 Dornenwirker der Klingenmähnen und Kreenig Grantelschnauze. Nehmt Kreenig Grantelschnauzes Hauer an Euch.", progress = "Schneidet dem Anführer den Kopf ab, dann bricht das Chaos aus, {name}. Lernt diese Lektion sorgfältig. Sie wird Euch in der Zukunft helfen.", completion = "Gut gemacht, {name}. Da Kreenig tot ist, werden die Angriffe auf unsere Karawanen merklich nachlassen. Euer Volk kann sich stolz schätzen, Euch in seinen Reihen zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[873] = { id = 873, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Isha Awak", description = "Isha Awak ist der Herr über diese Gewässer. Groß ist seine Kraft und edel sein Stolz. Die Menschen an der Küste fürchten ihn, denn er hat großen Schaden unter ihnen angerichtet.\n\nIch jedoch fürchte ihn nicht. Ich bin froh, dass er hier ist. Er ist eine würdige Herausforderung und eine ehrenhafte Beute.\n\nWenn Ihr bereit seid, schwimmt hinaus und sucht nach Isha Awak, der Tiefsten Verdammnis.\n\nSein Geist wohnt in seinem Herzen, und dieses schlagen zu hören heißt, Euer Schicksal zu kennen.", sourceObjective = "Bringt Mahren Himmelsdeuter das Herz von Isha Awak.", sourceObjectiveStatus = "unverified-source-field" }
quests[874] = { id = 874, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mahren Himmelsdeuter", description = "Ihr habt die Wildtiere des Brachlandes gejagt. Euer Geist ist stark. Ein Jäger muss jedoch immer vorbereitet sein. Ein wahrer Jäger kann auf allen Pfaden seine Beute finden. Weder Berg noch Sumpf wird ihn wanken lassen.\n\nNicht einmal das Meer.\n\nSucht meine Schwester Mahren. Sie jagt die großen Wassertiere entlang der Küste. Sie wird Euch etwas über sie lehren.\n\nSeid jedoch vorsichtig, während Ihr nach ihr sucht, denn die Küste des Brachlandes ist in den Händen der Menschen.", sourceObjective = "Sprecht mit Mahren Himmelsdeuter.", sourceObjectiveStatus = "unverified-source-field" }
quests[875] = { id = 875, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Offiziere der Harpyien", description = "Die einzige Möglichkeit, die Übergriffe der Harpyien zu beenden besteht darin, ihre Befehlskette zu zerschlagen. Die Harpyien werden von furchtlosen Offizieren angeführt, den Töterinnen der Hexenschwingen. Wenn die Töterinnen fallen, wird der Rest ihnen folgen.\n\nBegebt Euch zu den Trockenen Hügeln und fegt die Töterinnen der Hexenschwingen vom Himmel. Sorgt dafür, dass sie einen schmerzhaften Tod sterben, {name}. Wir möchten, dass diese Spinatwachteln lernen, wie wahnwitzig es ist, sich mit der Horde anzulegen.", sourceObjective = "Tötet 6 Töterinnen der Hexenschwingen in den Trockenen Hügeln im Nördlichen Brachland.", sourceObjectiveStatus = "unverified-source-field" }
quests[876] = { id = 876, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Serena Blutfeder", description = "Die Harpyien, die Ihr getötet habt, sprachen von ihrer Matronin, Serena Blutfeder. So leidenschaftlich, wie die Harpyien die Horde hassen, muss sie irgendeinen tief verwurzelten Groll gegen die Horde hegen. Ihr entschließt Euch, Jagd auf Serena Blutfeder zu machen und die Sache ein für alle Mal zu Ende zu bringen.", sourceObjective = "Erschlagt Serena Blutfeder und nehmt ihren Kopf an Euch.", completion = "Ha! Gut gemacht, {name}! Sehr gut gemacht... Ich war mir nicht sicher, ob Ihr der Sache gewachsen seid, aber Ihr habt Euch als ausgezeichneter Halsabschneider erwiesen. Nochmals vielen Dank, dass Ihr uns geholfen habt, die Harpyienepidemie einzudämmen. Hier habt Ihr Eure Belohnung, verwendet sie klug.", sourceObjectiveStatus = "unverified-source-field" }
quests[877] = { id = 877, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Brackige Oase", description = "Könnte hier bei uns das Gleiche wie im Süden passieren? Demnach zu urteilen, was Ihr bei den Vergessenen Teichen gefunden habt, könnten die Oasen der Schlüssel sein. Führen wir ein Experiment durch.\n\nHier, nehmt diese Samenkörner, die ich von diesem Gipfel gesammelt habe. Sie sind tot und unfruchtbar, aber nehmt sie trotzdem mit zur Brackigen Oase am Fuß des Berges. Wenn es dort einen Riss gibt, dann pflanzt die Samenkörner darin ein... und beobachtet, was passiert. Berichtet Tonga am Wegekreuz, was Ihr gesehen habt.", sourceObjective = "Benutzt die Samenkörner, um die Risse in der Brackigen Oase zu untersuchen.", completion = "Eure Entdeckungen sind erstaunlich! Jerriks Entscheidung, Euch dorthin zu schicken, war weise. Wir wissen nun, dass das, was unter diesen Oasen schlummert, Leben aus dem Nichts hervorbringen kann! Zweifellos ist das auch der Grund für das Chaos im Süden, jedoch ist meine größte Sorge im Moment, das Gleichgewicht hier oben zu bewahren.\n\nWir müssen weitere Untersuchungen anstellen...", sourceObjectiveStatus = "unverified-source-field" }
quests[878] = { id = 878, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stämme im Krieg", description = "Ihr müsst meine Feinde schlagen. <schnaubt> Ihr müsst Quetschzahn und dem Klingenmähnenstamm helfen, indem Ihr die Borstennacken schwächt. Beide Stämme sind sehr spirituell - gebunden an die Erde und ihre Kraft. <schnaubt> Sie gibt uns Stärke in allen Dingen... besonders im Krieg.\n\nWenn ihr herausfinden wollt, wer Thork <schnaubt> und der Horde wirklich solche Angst bereitet, dann helft Quetschzahn! Ihr greift die spirituellen Anführer der Borstennacken im Norden an und schwächt sie, sodass die Klingenmähnen sie besiegen und das Brachland beherrschen können.", sourceObjective = "Erledigt 6 Wassersucher der Borstennacken, 12 Dornenwirker der Borstennacken sowie 12 Geomanten der Borstennacken und kehrt zu Quetschzahn im Camp Taurajo im Brachland zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[879] = { id = 879, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verräter in den eigenen Reihen", description = "Drei meines Stammes kamen aus dem Kral, um die Überfälle gegen die Horde anzuführen, {race}. <schnaubt> Sie sind ruchlos und schlau und wenn Ihr sie besiegt, dann wird das Wegekreuz und auch der Großteil des Brachlandes Frieden haben... <schnaubt> zumindest vor dem Klingenmähnenstamm. <schnaubt>\n\nSucht nach Nak, Kuz und Lok Orcfluch. Sie befinden sich weit im Süden des Brachlandes. Einer ist ein Zauberer, ein weiterer ein Fährtenleser und ihr Anführer, den sie Orcfluch nennen, <schnaubt> ist ein Krieger. Tötet sie, {race}, so wie sie mich töteten.", sourceObjective = "Tötet Nak, Kuz und Lok Orcfluch und bringt Quetschzahn im Camp Taurajo im Brachland ihre Schädel.", sourceObjectiveStatus = "unverified-source-field" }
quests[880] = { id = 880, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Veränderte Wesen", description = "Es wird wichtig sein, sowohl Flora als auch Fauna zu untersuchen, die von den Oasen und den von Euch entdeckten ungewöhnlichen Energien beeinflusst wurden. Die Brackige Oase zu unseren Füßen ist der Lebensraum einer Spezies von Schnappkieferschildkröten. In letzter Zeit hat sich ihre Population explosionsartig vergrößert. Außerdem werden diese einst so friedfertigen Tiere jetzt immer aggressiver, wie ich am eigenen Leib erfahren musste, bevor ich hier heraufgestiegen bin.\n\n<Jerrik hält einen bandagierten Finger hoch.>\n\nIch vermute, sie wurden von den Oasen verändert. Sammelt ihre Panzer und bringt sie zur weiteren Untersuchung zu Tonga am Wegekreuz.", sourceObjective = "Sammelt 6 Schnappkieferpanzer von den Schnappkiefern in der Brackigen Oase.", progress = "Was bringt Ihr mir denn noch?", completion = "Danke, {name}. Beim Studieren der Wildtiere eines Gebiets kann man viel über das Gebiet selbst herausfinden. Wir werden sehen, welche Geschichte uns diese Panzer erzählen.\n\nBitte lasst mich Euch für Eure Hilfe danken... und vielleicht habt Ihr ja Verwendung für diese Münzen. Ich zumindest brauche sie nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[881] = { id = 881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echeyakee", description = "Weißnebel, Echeyakee in der Sprache der Tauren, ist der König der Savannenkatzen. Er jagt mit solcher Verstohlenheit, dass man sagt, er sei wie ein dünner, weißer Nebel auf der Erde. Und er tötet so schnell, dass seine Beute weder Angst noch Schmerz verspürt.\n\nDie Tauren sagen, er sei sowohl Gnade als auch Tod.\n\n{name}, ich schicke Euch nun auf die Jagd nach Echeyakee. Sein Versteck befindet sich nordwestlich von hier an der Nordseite eines kleinen Berges zwischen den Knochen riesiger Kodos.\n\nGeht. Stoßt in dieses Horn, wenn ihr seinen Unterschlupf erreicht. Blast das Horn und er wird erscheinen.", sourceObjective = "Blast das Horn bei Echeyakees Unterschlupf, um ihn herbeizurufen. Tötet oder zähmt ihn.", completion = "Ihr habt Echeyakee geschlagen und obwohl seine Tage als Jäger vorbei sind... ist sein Geist mit Euch. Er wird Euch die Kraft zeigen, die im Feingefühl liegt, und welche Ehre Gnade birgt.\n\nIch habe Euch unterschätzt, {class}. Ihr seid eine Bereicherung für die Reihen der Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[882] = { id = 882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ishamuhale", description = "Ishamuhale - Speerzahn - ist der wildeste Sonnenschuppenraptor des Brachlandes. Er jagt weder zum Spaß noch für Nahrung. Er jagt, weil Jagen seine Leidenschaft ist. Er tötet, weil Töten seine Natur ist.\n\nUnd Ihr werdet Euch mit seiner Natur vertraut machen, {name}, denn Euer Weg folgt jetzt den Krallenspuren Ishamuhales.\n\nBeginnt mit der Jagd. Erlegt seine Lieblingsbeute, ein Zhevra, und bringt den Kadaver zum toten Baum im Nordwesten von Ratschet. Ishamuhale wird den Kadaver riechen und von ihm angezogen werden.\n\nSeid bereit, wenn er kommt.", sourceObjective = "Bringt Jorn Himmelsdeuter im Camp Taurajo Ishamuhales Fangzahn.", sourceObjectiveStatus = "unverified-source-field" }
quests[883] = { id = 883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lakota'mani" }
quests[884] = { id = 884, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Owatanka" }
quests[885] = { id = 885, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Washte Pawne" }
quests[886] = { id = 886, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Oasen des Brachlandes", description = "Die Druiden von Donnerfels spüren eine große Macht, die östlich von Mulgore ins Brachland sickert.\n\nTonga Runentotem wurde entsandt, um die Quelle dieser Macht ausfindig zu machen, aber wir befürchten, dass er Hilfe brauchen wird.\n\nReist ins Brachland und sprecht mit Tonga. Er wird in der Siedlung des Wegekreuzes sein. Um dorthin zu gelangen, folgt der Straße vom Dorf der Bluthufe aus nach Osten. Betretet das Brachland und wendet Euch bei der Weggabelung weiter nach Norden. Geht weiter Richtung Norden, dann gelangt Ihr zum Wegekreuz.\n\nUnd haltet Euch immer auf der Straße, {name}, denn das Brachland ist ein raues Land.", sourceObjective = "Sprecht beim Wegekreuz mit Tonga Runentotem.", sourceObjectiveStatus = "unverified-source-field" }
quests[887] = { id = 887, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Südmeerfreibeuter", description = "Gazlowe hat mir eine Beförderung versprochen, wenn ich ihm mit dem Piratenproblem in Ratschet helfen kann. Das Problem sind diese neuen Bukaniere, die angesegelt gekommen sind und Prügeleiland südlich von hier übernommen haben. Die sind nicht nur auf unsere Waren aus - die haben auch noch Rechnungen zu begleichen! Neulich nachts hatten sie es auf eine unserer Kriegsgaleonen abgesehen.\n\nIch habe Pläne, wie wir mit dieser Situation verfahren, aber Gazlowe will schnelle Ergebnisse sehen. Macht Euch doch auf den Weg rüber aufs Prügeleiland und fangt schon mal an, ein paar Köpfe abzuhacken, ja?", sourceObjective = "Tötet 8 Halsabschneider oder Kaperer der Südmeerfreibeuter auf Prügeleiland.", completion = "Grandios! Gazlowe wird mich fürstlich belohnen. Und ich belohne Euch. Weniger fürstlich, versteht sich. Schließlich muss ein Goblin ja sehen wo er bleibt, versteht Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[888] = { id = 888, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestohlene Beute", description = "Ich hätte zwar gern, dass Ihr mir all meine Waren zurückbringt, aber das dürfte wohl unmöglich sein. Es gibt jedoch ein paar Dinge, die ich unbedingt wiederhaben muss!\n\nWie Ihr seht, ist mein Observatorium fast einsatzbereit, aber es fehlt noch die kleinere der zwei Linsen. Die erste Linse ist mit der Karawane aus Durotar gekommen, aber die zweite wurde per Schiff verschickt und ist nie hier eingetroffen. Ebenso ist meine Stiefellieferung von Drizzlik aus Beutebucht nicht hier angekommen!\n\nBegebt Euch zum Piratenlager und seht mal nach, ob Ihr die Dinge dort finden könnt.", sourceObjective = "Bringt Gazlowe in Ratschet die Stiefellieferung und die Teleskoplinse zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[889] = { id = 889, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geist des Windes" }
quests[890] = { id = 890, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verloren gegangene Lieferung", description = "Ich warte schon eine Ewigkeit auf meine letzte Warenlieferung aus Beutebucht! Ich bin mir ziemlich sicher, dass die Seeräuber sie gestohlen haben; würdet Ihr wohl, nur um sicher zu sein, zu den Docks gehen und Flunkerblick fragen, ob meine Waren vielleicht ohne mein Wissen bereits ins Lagerhaus gebracht wurden?\n\nHier, nehmt mein Geschäftsbuch mit zu Flunkerblick, damit er meine Inventaraufzeichnungen mit seinen Büchern gegenprüft.", sourceObjective = "Bringt Werftmeister FlunkerblickGazlowes Geschäftsbuch.", sourceObjectiveStatus = "unverified-source-field" }
quests[891] = { id = 891, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rache des Kapitäns", description = "Wieder ist ein Schiff meiner Flotte diesen übereifrigen Menschen von Theramore in die Hände gefallen!\n\nDer neue Konteradmiral hat sein Schiff genau vor der Küste hier ankern lassen. Er entert oder versenkt jedes Schiff, das nicht auf seinen Befehl beidreht.\n\nReist nach Süden entlang der Händlerküste zu seinem Lager. Bringt mir die Medaillen der Marinesoldaten und Matrosen. Tötet seine Leutnants Pyre und Buckland. Versenkt sie, wie sie meine Flotte versenkt haben!", sourceObjective = "Sammelt 10 Medaillen von Theramore von Theramore Marinesoldaten und Matrosen. Tötet die Leutnants Pyre und Buckland.", progress = "Füllt meine Hände mit Medaillen von ihren Toten, damit ich weiß, dass meine gefallenen Freibeuter gerächt worden sind.", completion = "Ich sehe, Ihr habt den selbstherrlichen Konteradmiral leiden lassen, wie auch ich gelitten habe. Vielleicht wird dieser Schlag die Entschlossenheit in Nordwacht schwächen. Sein Vorrat an neuen Rekruten scheint unerschöpflich zu sein, aber der Verlust seiner obersten Leutnants wird ihn für eine gewisse Zeit schwächen.", sourceObjectiveStatus = "unverified-source-field" }
quests[892] = { id = 892, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verloren gegangene Lieferung", description = "Laut meinen Aufzeichnungen ist alles in Ordnung, {name}. Geht zurück und sagt Gazlowe, dass er wohl Pech gehabt hat. Es würde mich nicht überraschen, wenn sich die Piraten seine Waren geschnappt hätten.\n\nIch kann leider nicht mehr für ihn tun. Oh... Ihr könnt ihm allerdings sagen, dass ich ein paar Dinge aus Lorenhall für ihn habe, falls er die Zeit findet, sie abzuholen.", sourceObjective = "Bringt Gazlowe in Ratschet sein Geschäftsbuch zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[893] = { id = 893, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgewählte Waffen", description = "Die Stacheleber des Klingenmähnenstamms im Süden, hinter dem Feld der Riesen, haben keine erfahrenen Schmiede, soweit ich weiß, aber Sie haben anscheinend begonnen, stabilere Waffen zu entwickeln. Ich hätte gern ein paar verschiedene Arten davon, um etwas über ihre Techniken zu erfahren, so möglich.\n\nWenn Ihr der Horde Ehre bringen wollt, dann bringt mir Exemplare von ihren Waffen. Besorgt mir einen Dolch von ihren Schleichern, einen Zauberstab von ihren Sehern und einen Schild von ihren Kriegsberserkern. Das sollte reichen!", sourceObjective = "Bringt Tatternack Stahlformer im Camp Taurajo im Brachland einen Klingenmähnenrückenstecher, einen verkohlten Klingenmähnenzauberstab und einen Klingenmähnenkriegsschild.", sourceObjectiveStatus = "unverified-source-field" }
quests[894] = { id = 894, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Samophlang", description = "Die Venture Company hat weit nördlich von hier, westlich des Schlickmoores, eine kleine Forschungseinrichtung errichtet. Was die Leute dort tun, weiß ich nicht genau, aber ich habe herausgefunden, dass sie dort mit etwas experimentieren, das \"Samophlang\" genannt wird.\n\nWas zum Teufel ist ein Samophlang? Naja, was immer es auch ist, ich möchte es untersuchen, also brauche ich jemanden, der eines beschafft.\n\nIch habe ein Exemplar der Bedienungsanleitung für ihr Steuersystem in die Finger bekommen; Ihr solltet also herausfinden können, wie man das Samophlang daraus entfernt.", sourceObjective = "Verschafft Euch Zugang zur Steuerkonsole in der Forschungseinrichtung der Venture Company.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[895] = { id = 895, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Käpt'n Garvey", description = "GESUCHT!\n\n\"Käpt'n\" J. Garvey, Kapitän der\nDolch der Maid\n\nIst der Piraterie auf offenem Meer, Entführung, Erpressung, Brandstiftung, Sklaverei u.a. schuldig. Garvey ist kürzlich in diesen Gewässern angekommen, führt eine Besatzung von Südmeerfreibeutern an und wurde zuletzt bei einem Angriff auf Prügeleiland gesichtet. Überbringt uns einen Nachweis seines Ablebens in identifizierbarem Zustand!\n\n-- Gazlowe", sourceObjective = "Bringt Gazlowe in Ratschet Käpt'n Garveys Kopf.", progress = "Was geht ab? Kann ich Euch irgendwie helfen? Habt Ihr Waren zu verschiffen? Oder vielleicht einen Ingenieursjob?", completion = "Ahhhh!!! So eine Art Geschäft also. Wisst Ihr, diese Piraten passen immer aufeinander auf. Kaum ist Baron Küstenschipper hinter Schloss und Riegel, kommt dieser Bursche Garvey daher, um Rache zu nehmen... Meint Ihr jemand wird herkommen, um Garvey zu rächen? Vielleicht sollte ich Euch schon einmal einen Vorschuss dafür geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[896] = { id = 896, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Miner's Fortune" }
quests[897] = { id = 897, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ernter", description = "Diese seltsame, insektenartige Kreatur scheint außerhalb der natürlichen Ordnung zu stehen, so als würde sie nicht ins Brachland gehören.", sourceObjective = "Bringt den Ernterkopf zu Jorn Himmelsdeuter.", sourceObjectiveStatus = "unverified-source-field" }
quests[898] = { id = 898, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Free From the Hold" }
quests[899] = { id = 899, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Hass zerfressen", description = "Sie haben meine Frau ermordet. Sie haben mein Haus und meinen Hof niedergebrannt. Seit jener fürchterlichen Nacht streife ich von Sonnenaufgang bis -untergang in diesem Landstrich umher und suche den Horizont ab nach mehr von diesen Monstern. Ich habe jeden Schweinemenschen getötet, dem ich seitdem begegnet bin, aber mein Durst nach ihrem Blut ist noch lange nicht gestillt.\n\nTötet sie. Tötet so viele, wie Ihr könnt. Bringt mir ihre Hauer und wir werden ihren Tod gemeinsam feiern.", sourceObjective = "Sammelt 30 Stacheleberhauer.", progress = "Die Stacheleber werden dafür bezahlen, {name}. Ich schwöre es.", completion = "{class}, Ihr habt meine Aufgabe ernst genommen und dafür danke ich Euch.\n\nMein Verlangen nach Rache ist zwar noch nicht gestillt, aber ich kann immerhin wieder lächeln, da ich sehe, dass auch die Stacheleber leiden mussten.", sourceObjectiveStatus = "unverified-source-field" }
quests[900] = { id = 900, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Samophlang", description = "Die drei Steuerventile sind momentan geöffnet. Die verschiedenen Anzeigen der Steuerkonsole führen Euch zu der Annahme, dass man sie zunächst schließen muss, bevor der Apparat ausgeschaltet werden kann.", sourceObjective = "Schließt das Treibstoffzufuhrventil, das Regelventil und das Hauptsteuerventil, und benutzt dann noch einmal die Steuerkonsole.", sourceObjectiveStatus = "unverified-source-field" }
quests[901] = { id = 901, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Samophlang", description = "Da der Apparat jetzt ausgeschaltet ist, kann die Steuerkonsole geöffnet und das Samophlang entfernt werden. Alles andere sollte unangetastet bleiben und Ihr benötigt jetzt nur noch den Schlüssel, mit dem die Konsole geöffnet werden kann.", sourceObjective = "Besorgt Euch bei Tüftler Kichers den Konsolenschlüssel.", sourceObjectiveStatus = "unverified-source-field" }
quests[902] = { id = 902, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Samophlang", description = "Nach dem Öffnen der Front der Steuerkonsole zeigt sich ein dichtes Gewirr aus Kabeln, Schläuchen und anderen seltsamen, mechanischen Objekten - die meisten davon scheinen keinen praktischen Nutzen zu haben. Ihr schiebt sie beiseite und arbeitet Euch tiefer in die Konsole vor, bis Ihr schließlich das Samophlang gefunden habt. Mit einem Ruck zieht Ihr es aus der Halterung.", sourceObjective = "Bringt das Samophlang zu Stotterspritter in Düsentopfs Außenposten im Nördlichen Brachland zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[903] = { id = 903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagt die Jägerin", description = "Wenn Ihr wirklich Euren Mut unter Beweis stellen wollt, setze ich Euch jetzt auf etwas an, das sich wirklich wehrt. Die Savannenjägerinnen des Brachlandes sind die gerissensten ihrer Art. Zäh, erfinderisch, schnell... und tödlich. Sie haben in letzter Zeit unseren Spähern rund um die Siedlung das Leben schwer gemacht, besonders im Nordosten.\n\nSeid vorsichtig, wenn Ihr sie jagt, {name}, oder Ihr werdet feststellen, dass Ihr nicht mehr Jäger, sondern Gejagter seid.", sourceObjective = "Sammelt 5 Klauen der Jägerin von Savannenjägerinnen.", progress = "Wie läuft Eure Jagd, {name}?", completion = "Ah, ich sehe, Ihr wart fleißig. Ich hoffe Ihr habt von dieser Beute viel gelernt, {name}. Ihr werdet die Stärke und Schläue dieser Tiere brauchen, um meiner geliebten Horde zu dienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[905] = { id = 905, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Höhle des Raptors", description = "Tja, {name}, die Jagd wird schwieriger. Jetzt müsst Ihr Eure Beute in ihrem eigenen Unterschlupf besiegen.\n\nJagt die Sonnenschuppenraptoren im Süden, wo sie abseits der Straße einen Bau zwischen den Hügeln angelegt haben. Erledigt sie und nehmt Euch die Federn, die sie tragen. Legt die Federn in die Nester der Sonnenschuppenraptoren, um ihren Brüdern zu zeigen, dass Ihr sie nicht fürchtet!\n\nSeid vorsichtig, {class}. Raptoren jagen in Rudeln und werden Euch umzingeln, wenn Ihr Euch nicht vorseht.", sourceObjective = "Tötet Sonnenschuppenraptoren und nehmt ihre Federn mit. Benutzt die Federn bei den drei Sonnenschuppennestern.", completion = "Ihr wart also bei den Nestern und habt die Federn Eurer Beute dort abgelegt. Dafür war zweifellos eine gehörige Portion Mut notwendig.\n\nFühlt Ihr Euch ein bisschen stärker, {name}? Denn Ihr seht stärker aus als bei Eurem ersten Besuch hier. Ich glaube, das Brachland zeitigt Erfolg bei Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[906] = { id = 906, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verräter in den eigenen Reihen", description = "Bringt Loks Kopf zu Thork am Wegekreuz, {race}. <schnaubt> Er sollte ohne Worte wissen, was meinem Stamm zugestoßen ist - ha, nicht dass er denken würde, Quetschzahn hätte bei <schnaubt> solchen Dingen geholfen. Aber ich bin sicher, er wird Euch für das Ausführen einer solch großen Tat belohnen. <schnaubt>\n\nIch werde Euch auch weiterhin mit Agamaggans Macht segnen, solange ich in diesem Käfig verbleibe, {race}. Bis dann, lebt wohl.", sourceObjective = "Bringt Loks Kopf zu Thork beim Wegekreuz im Brachland.", sourceObjectiveStatus = "unverified-source-field" }
quests[907] = { id = 907, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wütende Donnerechsen", description = "Nun denn, {name}, jetzt müsst Ihr den großen Donnerechsen gegenübertreten. Diese Bestien sind so groß, dass der Boden erbebt, wenn sie über die Ebenen stampfen. Seid vorsichtig, wenn Ihr gegen sie kämpft, denn ein einziger falscher Schritt, und schon findet Ihr Euch unter ihren Füßen wieder.\n\nIhr findet die Donnerechsen im Südlichen Brachland. Man kennt sie als Sturmschnauzen, Sturmechsen und Donnerköpfe. Kehrt zu mir zurück, nachdem Ihr sie überwältigt habt.", sourceObjective = "Bringt das Blut von 3 Donnerechsen ins Camp Taurajo zu Jorn Himmelsdeuter.", sourceObjectiveStatus = "unverified-source-field" }
quests[908] = { id = 908, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inmitten der Ruinen", description = "Die Anhänger des Schattenhammers sind in die Mondschreinruinen der Tiefschwarzen Grotte eingezogen. Ihre Gegenwart kann nur dazu dienen, die Elemente gegen uns aufzubringen. Wenn dem kein Einhalt geboten wird, gehört ihnen diese Region bald ganz und gar.\n\n{name}, geht in die Tiefschwarze Grotte und findet den Tiefenstein der Ruinen. Er dürfte irgendwo in deren Nähe im Wasser liegen. Darin ist ein Tiefenkern. Das ist ein Gerät, das, wenn man es richtig abliest, eine Aufstellung über alle Aktivitäten der Elementare liefert. Wenn ich es habe, können der Irdene Ring und ich vielleicht etwas tun, um sie aufzuhalten.", sourceObjective = "Bringt den Tiefenkern zu Je'neu Sancrea beim Außenposten von Zoram'gar im Eschental.", sourceObjectiveStatus = "unverified-source-field" }
quests[909] = { id = 909, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baron Aquanis", description = "Der besiegte Wasserelementar hat eine seltsame Wasserkugel zurückgelassen. Ihr vermutet, dass das Objekt die Kreatur irgendwie mit Energie versorgt hat. In der Kugel schwappt faulig aussehendes Wasser herum. Die Kugel selbst zeigt sich unbeeindruckt von jeder äußerlichen Krafteinwirkung.\n\nWenn irgendwer aus diesem Gegenstand schlau werden kann, ist das wohl Je'neu Sancrea vom Irdenen Ring. Er befindet sich beim Außenposten von Zoram'gar der Horde im Eschental.", sourceObjective = "Bringt die seltsame Wasserkugel zu Je'neu Sancrea beim Außenposten von Zoram'gar im Eschental.", sourceObjectiveStatus = "unverified-source-field" }
quests[910] = { id = 910, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down at the Docks" }
quests[911] = { id = 911, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gateway to the Frontier" }
quests[912] = { id = 912, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Splittersteintroggverkleidung" }
quests[913] = { id = 913, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf des Donnerfalken", description = "Der Donnerfalke, {name}, ist ein ungestümes Wildtier. Es ist an der Zeit für Euch, ihm gegenüberzutreten. Ihr müsst herausfinden, wo er umherstreift, und mir seine Flügel als Beweis für Eure erfolgreiche Jagd bringen.\n\nWenn Ihr das tut, wird Eure Zeit mit mir sich ihrem Ende nähern.", sourceObjective = "Sucht und erschlagt einen Donnerfalken und bringt Jorn Himmelsdeuter in Taurajo seine Flügel.", sourceObjectiveStatus = "unverified-source-field" }
quests[914] = { id = 914, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anführer der Giftzähne", description = "Die Druiden in den Höhlen des Wehklagens, die Druiden des Giftzahns, sind eine Verirrung der Natur. Einst gehörten sie einem Orden edler Druiden an, deren Plan es war, das Brachland zu heilen, doch jetzt trachten sie danach, das Land ihren eigenen verderbten Träumen gleichzumachen.\n\nDie Druiden des Giftzahns haben vier Anführer, und jeder besitzt einen Traumedelstein. Selbst jetzt noch verfolgen mich ihre Gesichter! Besiegt die Anführer und bringt mir ihre Edelsteine, dann wird das Brachland endlich wieder Frieden haben.\n\nGeht, {name}. Sie halten sich tief in den Höhlen des Wehklagens verborgen.", sourceObjective = "Bringt die Edelsteine von Kobrahn, Anacondra, Pythas und Serpentis nach Donnerfels zu Nara Wildmähne.", sourceObjectiveStatus = "unverified-source-field" }
quests[915] = { id = 915, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Scream, I Scream..." }
quests[916] = { id = 916, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbnis der Waldweber", description = "Ich kam ins Laubschattental, um hier die Waldweberspinnen zu beobachten, die in der Schattenweberhöhle leben. Man sagte mir, dass sie mit Teldrassils jüngstem Segen weit weniger aggressiv sein sollten. Anscheinend wurde ich getäuscht.\n\nIch habe vor Kurzem ein paar ihrer Giftbeutel erhalten und musste eine sehr ungesunde Verderbnis in ihnen feststellen. Um es kurz zu machen, ich mache mir Sorgen darüber, was passieren könnte, wenn wir korrumpierte Tiere wie diese frei herumlaufen lassen.\n\nIch möchte, dass Ihr ihre Population verringert, damit wir etwas Zeit gewinnen.", sourceObjective = "Tötet 12 Waldweberspinnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[917] = { id = 917, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waldweberei", description = "Mir fällt gerade ein, dass Ihr mir vielleicht noch mit etwas Anderem helfen könnt. Ich bin hierhergekommen, um ein Waldweberei aus den Tiefen der Höhle zu besorgen, aber die Spinnen hatten etwas dagegen. Wenn Ihr ein Ei besorgen und es zurück zu Dirania bringen könntet, wären wir beide sehr dankbar.", sourceObjective = "Erhaltet ein Waldweberei.", sourceObjectiveStatus = "unverified-source-field" }
quests[918] = { id = 918, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bäumlingssamenkörner", description = "Die Bäumlinge von Teldrassil sind Naturelementare. In ihnen spiegelt sich in gewisser Weise die natürliche Ordnung von Flora und Fauna unseres großen Baums wider.\n\nDaher ist es höchst beunruhigend zu sehen, dass die Bäumlinge so wütend geworden sind, besonders wenn man bedenkt, dass inzwischen alles heilen sollte.\n\nIch will dem auf den Grund gehen. Ich habe mich viel mit verschiedenen Düngemethoden für Pflanzen beschäftigt und würde sie gern an Bäumlingssamenkörnern ausprobieren. Würdet Ihr bitte in der Gegend des Al'Amethsees ein paar Bäumlingssamenkörner sammeln und mir bringen?", sourceObjective = "Erhaltet 6 Bäumlingssamenkörner.", progress = "Habt Ihr die Samen? Ich kann es kaum erwarten, sie einzupflanzen.", completion = "Ihr habt sie. Das ist gut! Ich hoffe, dass mich eine sorgfältige Untersuchung verstehen lassen kann, woher die Verderbnis der Bäumlinge kommt.\n\nIch werde diese Samen in einer speziell vorbereiteten Erde einpflanzen. Ich glaube, aus den Samen werden Bäumlinge wachsen, die viel sanftmütiger sind.\n\nVielleicht könnt Ihr Euch später das Ergebnis ansehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[919] = { id = 919, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bäumlingssprosse", description = "Kleine Bäumlinge sprießen rund um das Wasser des Al'Amethsees. Ich fürchte, dass man diesen Schösslingen nicht mehr helfen kann - wir sollten versuchen, sie auszureißen, bevor sie groß genug sind, um Probleme zu bereiten.\n\nWenn Ihr auf Euren Wanderungen um den See Bäumlingssprosse seht, reißt sie bitte aus. Helft dabei, unser Land rein zu halten!", sourceObjective = "Sammelt 10 Bäumlingssprosse.", progress = "Hallo, {name}. Habt Ihr in der Nähe der Seen Schösslinge gefunden?", completion = "Sind das viele! Ich fürchte, sie verbreiten sich gefährlich schnell. Hoffentlich kann ich den Grund dafür finden, warum sie so besudelt sind.\n\nDanke für Eure Hilfe, {name}. Dank Euch ist das Land wieder viel sauberer.", sourceObjectiveStatus = "unverified-source-field" }
quests[920] = { id = 920, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tenarons Einladung", description = "Ah, {name}! Ich hörte, dass Tenaron nach Euch gefragt hat. Ihr findet ihn in dem am höchsten gelegenen Raum in Aldrassil.\n\nWir mögen zwar ein langes Leben haben, aber Ihr solltet ihn dennoch nicht allzu lang warten lassen.", sourceObjective = "Sprecht im Laubschattental über den Dächern von Aldrassil mit Tenaron Sturmgewalt.", sourceObjectiveStatus = "unverified-source-field" }
quests[921] = { id = 921, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teldrassil: Krone von Azeroth", description = "Es ist an der Zeit herauszufinden, was Euer Schicksal ist, {name}. Doch bevor Ihr bereit seid, in die Welt hinter unseren verzauberten Wäldern hinauszuziehen, gibt es noch vieles, was Ihr über unsere jüngste Vergangenheit lernen müsst.\n\nEs gibt eine Aufgabe, der Ihr Euch stellen müsst. Geht zum Mondbrunnen nördlich von Aldrassil und entnehmt eine Phiole seines Wassers. Dort werdet Ihr Zeuge eines kleinen Eindruckes unserer Magien werden und etwas über unsere Vergangenheit erfahren.\n\nWenn Ihr dort fertig seid, bringt das Wasser zu Tenaron Sturmgewalt. Ihr werdet ihn auf der westlichen Rampe an der Spitze Aldrassils finden.", sourceObjective = "Füllt die Kristallphiole.", sourceObjectiveStatus = "unverified-source-field" }
quests[922] = { id = 922, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rellian Grünwipfel", description = "{name}, würdet Ihr wohl eines der Samenkörner, die Ihr mir besorgt habt, meinem Freund Rellian Grünwipfel bringen? Er ist ein Druide, der sich bei der Hütte am Quell aufhält, und bei unserem letzten Gespräch machte er deutlich, dass er an meiner Arbeit mit den Bäumlingen interessiert sei. Er hatte selbst ein paar Ideen und würde sich über ein Exemplar dieser Samenkörner sicherlich freuen.\n\nDanke, {name}. Ihr wart mir eine große Hilfe. Ich hoffe, dass ich Euch eines Tages die Früchte meiner Arbeit zeigen kann.\n\nDie Hütte am Quell ist an der Straße, die in westlicher Richtung aus Dolanaar hinausführt, auf dem Weg nach Darnassus.", sourceObjective = "Bringt Rellian Grünwipfel bei der Hütte am Quell ein Bäumlingssamenkorn.", progress = "Hallo...\n\nKann ich Euch irgendwie helfen?", completion = "Ah, ein Bäumlingssamenkorn. Ich wollte schon immer eines davon haben, um Denalan bei seinen Studien zu unterstützen.\n\nLeider habe ich jedoch herausgefunden, dass viele der Bäumlinge eine Schädigung aufweisen und dass auch deren Samenkörner mit dieser Besudelung behaftet sind. Es ist mir nicht möglich, dies zu beheben.\n\nDenalan hat einen grünen Daumen mit Pflanzen. Er könnte ein Heilmittel für künftige Bäumlinge finden. Vielleicht ist er ihre einzige Hoffnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[923] = { id = 923, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moosartige Tumore", description = "Bosheit wuchert in den Bäumlingen. Wir versuchen, die Ursache dafür zu finden, aber bis dahin... Aus Sorge um Teldrassils Sicherheit müssen wir alle Bäumlinge fällen, denen nicht mehr geholfen werden kann. Diejenigen, die die Gegend um den Quellsee im Norden durchstreifen, sind am schlimmsten betroffen. Sie müssen ausgemerzt werden!\n\nVernichtet alle Bäumlinge, die Ihr dort findet, und sammelt die moosartigen Tumore, die auf ihnen wachsen. Bringt mir die Tumore, damit ich sie verbrennen kann.", sourceObjective = "Erhaltet 5 moosartige Tumore.", progress = "Wart Ihr schon am Quellsee, {name}? Habt Ihr dort Bäumlinge gejagt?", completion = "Gut gemacht! Diese Tumore sind ein Symptom der Bäumlingskrankheit. Sie sind mit einem Gift gefüllt, von dem wir unser neues Land säubern müssen.\n\nIch werde diese Tumore entsorgen. Danke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[924] = { id = 924, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Dämonensaat", description = "Die Dämonensaat ist ein mächtiges Werkzeug der Brennenden Legion. Sie lebt in einer Höhle des Glutnebelgipfels, oberhalb eines dämonischen Altars des Feuers.\n\nIch habe Kraftsteine vorbereitet, die, wenn sie in der Nähe der Saat platziert werden, deren Verbindung zur Legion unterbrechen.\n\nNehmt einen Stein vom Tisch und bringt ihn zum Altar des Feuers oben auf dem Glutnebelgipfel. Reist nach Westen und bei der Weggabelung weiter nach Norden. Der Gipfel liegt zu Eurer Linken. Die sicherste Aufstiegsmöglichkeit zur Spitze bietet sich an der Nordseite.\n\nUnd beeilt Euch - die Energie des Steins nimmt mit der Zeit ab.", sourceObjective = "Nehmt einen fehlerhaften Kraftstein. Bringt ihn zum Altar des Feuers, bevor dessen Wirkung erlischt, und kehrt dann zu Ak'Zeloth zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[925] = { id = 925, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cairnes Hufabdruck", description = "Ich habe gehört, dass Cairne Bluthuf einer der größten Helden ist, den die Horde je gesehen hat. Wenn ich mal groß bin, möchte ich auch ein Held der Horde werden!\n\nKennt Ihr Cairne, {name}? Tut Ihr mir einen Gefallen? Kriege ich ein Autogramm von ihm? Ich weiß gar nicht, wie ich ihn ansprechen soll, und wahrscheinlich ist er sowieso viel zu beschäftigt, um mich zu beachten...aber was ist mit Euch? Ihr seid doch genau wie er ein Abenteurer! Euch gibt er bestimmt ein Autogramm!\n\nBitte, {name}. Bitte...", sourceObjective = "Reist nach Donnerfels und versucht für Euren Schützling einen Hufabdruck von Cairne Bluthuf zu ergattern.", sourceObjectiveStatus = "unverified-source-field" }
quests[926] = { id = 926, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fehlerhafter Kraftstein" }
quests[927] = { id = 927, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das moosumschlungene Herz", description = "Das Herz von Schwarzmoos dem Stinker ist mit einem dunklen, öligen Moos bedeckt. Dass es sich wirklich um ein Herz handelt, kann man eigentlich nur daran erkennen, dass es langsam und rhythmisch schlägt... Ein Herzschlag, der sogar jetzt noch anhält.\n\nVielleicht würde Denalan dieses Herz gern einmal sehen.", sourceObjective = "Bringt Denalan am Al'Amethsee das moosumschlungene Herz.", progress = "{name}! Habt Ihr etwas für mich?", completion = "Was ist das denn? Ein Bäumlingsherz??? Es ist mit widerlichem Moos bedeckt!\n\nDanke, dass Ihr es mir gebracht habt, {name}. Ich werde das Herz untersuchen, und wenn ich Glück habe, finde ich heraus, was dies für eine Art Moos ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[928] = { id = 928, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teldrassil: Gebt das Wissen weiter", description = "Ich könnte Euch zwar noch so viel mehr über die Mondbrunnen und Teldrassil erzählen, doch leider muss ich Euch fortschicken. Corithras Mondzorn erwartet Euch. Ich habe das Wasser der Phiole, die Ihr mir brachtet, in dieses Gefäß geschüttet, damit Ihr es ihm bringen könnt.\n\nFragt nach Corithras. Ihr findet ihn am Mondbrunnen in Dolanaar. Folgt der Straße südlich von Aldrassil, die aus dem Laubschattental hinausführt und dann weiter auf dem Kopfsteinpflaster in Richtung Westen.\n\nBleibt unbedingt immer auf der Straße, {name}. Es gibt neuerdings ziemlich gefährliche Bestien in den Wäldern.", sourceObjective = "Bringt Corithras Mondzorn in Dolanaar das teilweise gefüllte Gefäß.", sourceObjectiveStatus = "unverified-source-field" }
quests[929] = { id = 929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teldrassil: Die Verweigerung der Aspekte", description = "Lasst mich Euch zunächst ein bisschen mehr von der Aufgabe erzählen, die Euch erwartet. Die Druiden in Darnassus verbrauchen das Wasser der Mondbrunnen Teldrassils, und deshalb muss ihr Mondbrunnen von Zeit zu Zeit wieder aufgefüllt werden. Ihr könnt mit diesen speziell gefertigten Phiolen Wasser aus den Mondbrunnen schöpfen.\n\nNehmt dieses Gefäß zum Mondbrunnen außerhalb von Sternenhauch im Osten mit und füllt es mit Wasser. Beachtet die Lehren der Mondbrunnen, sonst nähren wir nur unsere Verfehlungen.", sourceObjective = "Füllt die Jadephiole.", progress = "Hallo, {name}. Habt Ihr Eure Aufgabe erledigt?", completion = "Es ist nur natürlich, dass unser Volk, einst unsterblich und verehrt, sich schwer tut, sich selbst in dem bescheidenen Licht zu sehen, das uns wahrscheinlich gebührt. Wir müssen uns unserer Verbindung mit der Natur und mit Elune gewahr werden und unsere sterblichen Fehler hinter uns lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[930] = { id = 930, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die leuchtende Frucht", description = "Unter den Wedeln dieser leuchtenden Pflanze befindet sich eine große, runde Frucht.\n\nDenalan würde diese Frucht bestimmt gern studieren, da seid Ihr Euch sicher.", sourceObjective = "Bringt Denalan am Al'Amethsee die leuchtende Frucht.", progress = "{name}, Ihr seht aus, als wolltet Ihr mir etwas sagen. Habt Ihr Neuigkeiten bezüglich der Bäumlinge?", completion = "Ihr habt das in Teldrassil gefunden? Interessant... eine exotische Frucht. Vielleicht sind ihre Samen von weither hierher gelangt. Vielleicht sogar aus Azeroth! Irgendetwas ist mit dieser Frucht... sie scheint sich auf sehr seltsame Art dem Erdboden Teldrassils angepasst zu haben.\n\nDanke, {name}. Wenn Ihr mich jetzt bitte entschuldigen wollt, ich muss das hier näher untersuchen...", sourceObjectiveStatus = "unverified-source-field" }
quests[931] = { id = 931, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der schimmernde Wedel", description = "Die Wedel der Pflanze schimmern im Dämmerlicht des Waldes und verleihen ihr eine wabernde, pulsierende Aura.\n\nIhr glaubt, dass Denalan bestimmt gern ein Exemplar davon hätte.", sourceObjective = "Bringt Denalan einen der schimmernden Wedel. Er hält sich meistens am Al'Amethsee auf, reist aber manchmal zur Hütte am Quell.", progress = "Habt Ihr etwas für mich?", completion = "Wo habt Ihr das her? So eine Pflanze habe ich seit meiner Exkursion in die Sümpfe des Elends nicht mehr gesehen... das ist Jahrzehnte her! Wie erstaunlich, dass ein Exemplar es bis nach Teldrassil geschafft hat. Und wie hochgewachsen sie ist!\n\nDanke, {name}. Vergebt mir, dass ich so kurz angebunden bin, aber ich würde zu gern etwas mit diesem Wedel testen...", sourceObjectiveStatus = "unverified-source-field" }
quests[932] = { id = 932, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krankhafter Hass", description = "Ich muss Euch warnen, {name}, das hier muss absolut unter uns bleiben. Die Satyrn bereiten uns schon genug Ungelegenheiten, aber dieser eine hier scheint sich zu einer echten Bedrohung zu entwickeln.\n\nLord Melenas ist sein Name. Er lebt in der nahegelegenen Teufelsfelshöhle, in der er ein großes Kontingent Grellkrieger um sich versammelt hat. Sein Herz ist so schwarz wie die Nacht und er führt etwas äußerst Übles im Schilde.\n\nIhr müsst ihn in der nahe gelegenen Höhle gleich nördlich von hier suchen und mir seinen Kopf bringen.", sourceObjective = "Erhaltet den Kopf von Lord Melenas.", progress = "Habt Ihr Lord Melenas schon getötet? Es ist wichtig, dass man ihn schnell und stillschweigend beseitigt, {name}. Solange er lebt, wird er uns allen Ungemach bereiten.", completion = "Da Lord Melenas jetzt endlich zur Strecke gebracht ist, kann ich mich anderen Dingen zuwenden. Danke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[933] = { id = 933, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teldrassil: Der Anbruch des Tages", description = "Ich möchte, dass Ihr noch einen letzten Mondbrunnen besucht. Er liegt direkt südlich von hier am Ufer der Teiche von Arlithrien. Seid vorsichtig, wenn Ihr Euch dem Brunnen nähert und haltet Eure Waffen bereit. Ich verspüre eine wachsende Verderbnis von den südlichen Ästen Teldrassils her.\n\nSobald Ihr das Wasser habt, möchte ich, dass Ihr es zu einem vertrauten Gesicht bringt, dem Ihr dort an den Teichen begegnen werdet. Sie möchte die Verderbnis bekämpfen und hat nach Euch persönlich gefragt.", sourceObjective = "Füllt die Turmalinphiole.", progress = "Es ist schön, Euch wiederzusehen, {name}. Wie ich sehe, habt Ihr erfolgreich das Wasser der Mondbrunnen für Corithras Mondzorn gesammelt. Ich hoffe, Ihr habt währenddessen viel gelernt.", completion = "Ich habe in der Tat auf meinem Weg hierher mit Corithras gesprochen und er hat mir das Wasser, das Ihr gesammelt habt, zur Verfügung gestellt. Es könnte sich sehr wohl noch als nützlich erweisen, und zwar früher als wir dachten.\n\nMerkwürdigerweise ist die wachsende Verderbnis, die wir verspürt haben, in Wahrheit ein gutes Zeichen. Teldrassil ist schon seit langer Zeit mit dieser Verunreinigung belastet und dank des Segens der Drachenaspekte tritt sie nun in einer Form ans Tageslicht, gegen die wir etwas ausrichten können.", sourceObjectiveStatus = "unverified-source-field" }
quests[934] = { id = 934, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krone der Erde", description = "Mit Teldrassil stand es jedoch nicht zum Besten. Hirschhaupts sorgfältig durchdachte Pläne für den neuen Weltenbaum entwickelten sich nicht so, wie er gehofft hatte, denn es gab ein kleines Problem. Ein Problem, das die Ursache für viele weitere Probleme Teldrassils ist.\n\nWie dem auch sei, dazu komme ich später. Ihr müsst den letzten Mondbrunnen nordwestlich von hier in der Lichtung des Orakels aufsuchen. Unter den Ästen des Orakelbaums befindet sich der wichtigste und mächtigste unserer Brunnen. Beschafft eine Phiole seines Wassers und bringt sie mir.", sourceObjective = "Füllt die Amethystphiole und bringt sie Corithras Mondzorn in Dolanaar.", sourceObjectiveStatus = "unverified-source-field" }
quests[935] = { id = 935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wasser von Teldrassil", description = "Unsere Arbeit ist hier fürs Erste getan. Dieses Wasser hat sich als sehr bedeutsam herausgestellt, doch war es ursprünglich nicht für mich bestimmt. Geht nur und bringt es zu Corithras an der Wegkreuzung. Ich bin mir sicher, er möchte gern, dass Ihr es an seinen eigentlichen Bestimmungsort bringt.", sourceObjective = "Bringt das gefüllte Gefäß zu Corithras Mondzorn an der Kreuzung vor Darnassus.", progress = "Es ist schön, Euch wiederzusehen. Ich spüre, dass Tarindrellas Aufgabe mit Euch an ihrer Seite reibungslos verlaufen ist.", completion = "Danke, dass Ihr so schnell zu mir zurückgekehrt seid. Ich muss Euch nur um einen letzten Dienst bitten. Wollen wir?", sourceObjectiveStatus = "unverified-source-field" }
quests[936] = { id = 936, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erzdruide Runentotem helfen", description = "Entschuldigung, {class}, könnt Ihr einen Moment Eurer Zeit für mich erübrigen?\n\nDer Zirkel des Cenarius in Donnerfels ist sehr an erfahrenen Abenteurern wie Euch interessiert, die bei einem wichtigen Forschungsprojekt helfen können. Ich weiß zwar nichts Genaues, kann Euch aber sagen, dass kein Geringerer als Hamuul Runentotem an der Spitze dieses Projektes steht.\n\nBitte... wenn Ihr interessiert seid, sprecht direkt mit ihm auf der Anhöhe der Ältesten in Donnerfels.", sourceObjective = "Sprecht in Donnerfels mit Erzdruide Hamuul Runentotem.", sourceObjectiveStatus = "unverified-source-field" }
quests[937] = { id = 937, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verzauberte Lichtung", description = "Man hat mich mit einer kleinen Gruppe Schildwachen hierher beordert, um den Orakelbaum vor den Harpyien zu beschützen, die überall im Tal Nester gebaut haben. Wir versuchen, sie langsam aber sicher zurückzudrängen.\n\nBeim Versuch des Orakelbaums, einen Läufer mit einem Bericht nach Darnassus zu entsenden, wurde dieser von einer Gruppe eben jener Harpyien angegriffen und getötet.\n\nWenn Ihr glaubt, dieser Aufgabe gewachsen zu sein, begebt Euch zu ihren Nestern, erschlagt sie und bringt mir zum Beweis Eurer Taten ihre Gürtel.", sourceObjective = "Erhaltet 6 Blutfedergürtel.", progress = "Ihre scharfen Krallen und spitzen Schnäbel könnten Eure Fähigkeiten auf eine harte Probe stellen, {name}, aber ich vertraue darauf, dass Ihr bei dieser Aufgabe nicht versagt.", completion = "Ich bin beeindruckt, was Ihr in so kurzer Zeit alles bewerkstelligt habt, {name}. Ich würde Euch am liebsten bitten, hierzubleiben und mir bei meinen Pflichten zu helfen... aber tief in meinem Herzen weiß ich, dass größere Aufgaben auf Euch warten.", sourceObjectiveStatus = "unverified-source-field" }
quests[938] = { id = 938, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nebel", description = "Das Fell der Säblerkatze ist von einer unverwechselbaren grauen Farbe, die sich nur wenig vom sie umgebenden Wald abhebt. Wie sie da liegt, erkennt Ihr, dass sie schwer verletzt ist und tiefe Wunden an Rücken und Bauchseite aufweist.\n\nSie hebt ihren Kopf und starrt Euch an, ihre glänzenden blauen Augen voll wacher Intelligenz. Sie scheint Euch folgen zu wollen.", sourceObjective = "Begleitet Nebel zur Schildwache Arynia Wolkenbruch beim Mondbrunnen in der Nähe des Orakelbaums.", completion = "Oh, danke, {name}! Ich fürchtete schon, dass ich Nebel nie wiedersehen würde. Ich fürchtete, sie sei tot und ich würde nie wieder mit meiner treuen Begleiterin zusammen sein. Ich schulde Euch mehr, als Ihr Euch vorstellen könnt und werde Euch auf ewig dankbar sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[939] = { id = 939, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flöte des Xavaric", description = "Ihr untersucht die einfache Holzflöte, die Ihr nach dem Sieg über Xavaric aufgehoben habt.\n\nDas knorrige Holz fühlt sich fest an, aber es scheint, als würden sich die Spiralen und Muster auf der Oberfläche bewegen und herumwirbeln, als Ihr sie in den Händen dreht. Plötzlich überkommt Euch ein Gefühl der Furcht...\n\nIhr schüttelt den Kopf, sicher, dass Euch Euer Gehirn einen Streich spielt.\n\nMöglicherweise tragen andere Satyrn Hinweise darüber mit sich, was Ihr da gefunden habt. Bringt Euren Fund zu dem Druiden Eridan Blauwind, der im südlichen Teil des Teufelswalds lebt.", sourceObjective = "Bringt die Flöte von Xavaric und 5 Jadefeuerteufelsbinder zu Eridan Blauwind im südlichen Teil des Teufelswalds.", sourceObjectiveStatus = "unverified-source-field" }
quests[940] = { id = 940, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teldrassil", description = "Der Wald flüstert von Euren wagemutigen Heldentaten, {name}. Sobald die Harpyien aus ihren Nestern vertrieben waren, spürte ich, wie sich große Ruhe im Wald verbreitete, und dass sich die Kreaturen des Waldes wieder sicher fühlten. Ich habe nicht gewagt, noch einen Boten zum Erzdruiden zu schicken, aber ich weiß, dass Ihr dafür sorgen werdet, dass ihn meine Nachricht sicher erreicht.\n\nBringt ihm dies und wisset, dass der Wald Euch auf all seinen Wegen beschützen wird, sodass Ihr den Wald aus Stein sicher erreicht.", sourceObjective = "Überbringt dem Erzdruiden Fandral Hirschhaupt in Darnassus den Bericht des Orakelbaums.", sourceObjectiveStatus = "unverified-source-field" }
quests[941] = { id = 941, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Einpflanzen des Herzens", description = "Ich habe das üble Moos von dem Herzen entfernt, aber es bleibt dennoch besudelt...\n\nVersucht, das Herz in meinem Blumentopf einzusetzen. Er ist mit einer nährstoffreichen Erde gefüllt, die das Herz säubern und heilen kann.", sourceObjective = "Pflanzt das besudelte Herz in Denalans Blumentopf ein.", progress = "Der Blumentopf ist mit speziell von Denalan vorbereiteter Erde gefüllt.", completion = "Ihr setzt das Herz in den Blumentopf ein, und es beginnt sich im Handumdrehen selbst einzugraben!\n\nNach ein paar Sekunden windet es sich wieder heraus und ist gesäubert. Es pulsiert leicht und bedeutet Euch, es in die Hand zu nehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[942] = { id = 942, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der geistesabwesende Ausgrabungsleiter", description = "Dieses Fossil hat eine auffallende Ähnlichkeit mit einem anderen, das ich einst in Eisenschmiede sah. Ein Archäologe namens Magenbitter brachte es zur jährlichen Konferenz der Forscherliga mit. Er dachte, das Fossil besäße eine besondere Macht, die man irgendwie freisetzen könnte.\n\nZuletzt hörte ich, dass er sich in der Tiefenwassertaverne im Hafen von Menethil verschanzt hatte und dort auf eine Eskorte zu Whelgars Ausgrabungsstätte wartete. Sucht ihn auf und zeigt ihm Wirrbarts Fossil. Vielleicht kann er die Geheimnisse der Vergangenheit lüften.\n\nNach Menethil gelangt Ihr, indem Ihr über Auberdine per Schiff nach Sturmwind und von dort per Tiefenbahn nach Eisenschmiede reist. Das letzte Stück müsst Ihr leider laufen. Viel Glück!", sourceObjective = "Bringt das rätselhafte Fossil zum Archäologen Magenbitter im Hafen von Menethil.", sourceObjectiveStatus = "unverified-source-field" }
quests[943] = { id = 943, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der geistesabwesende Ausgrabungsleiter", description = "Ausgrabungsleiter Whelgar ist jetzt im Besitz des Originalfundstücks. Er hält sich in seiner Ausgrabungsstätte im Sumpfland auf. Als ich den Stein von Relu entdeckte, glaubte ich, dass er der Schlüssel sei, mit dem das Rätsel des Fossils gelöst werden könne.\n\nAuf dem Weg zu Whelgar wurde ich dann von Raptoren angegriffen und das Relikt ging verloren. Ich weiß nicht, welche dieser scheckigen Bestien das Relikt verschlungen hat, aber falls es Euch gelingen sollte, es zurückzuholen, könnte ich die Macht dieser Artefakte freisetzen.\n\nBringt mir den Stein von Relu und das Originalfossil.", sourceObjective = "Der Archäologe Magenbitter im Hafen von Menethil möchte, dass Ihr ihm den Stein von Relu und Magenbitters Fossil bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[944] = { id = 944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Meistergleve", description = "Wie seltsam, dass sich Naga hier herumtreiben, hier in Dunkelküste. Aber was noch seltsamer ist... es sind auch welche vom Klan des Schattenhammers da. Dieser Kult verehrt die alten, alten Fürsten der Erde. Fürsten, die schon vor Urzeiten besiegt wurden.\n\nDie Meistergleve im Süden ist ein Ort, an dem ein solcher Fürst einst gefallen ist.\n\nBegebt Euch dorthin und sucht nach weiteren Anhängern der Schattenhammerkultisten.\n\nNehmt diese Wahrsagephiole. Erschafft damit eine Wahrsageschale, nachdem Ihr die Meistergleve durchsucht habt. Sprecht dann mit mir mittels der Schale.", sourceObjective = "Tragt Informationen zusammen und benutzt dann die Wahrsagephiole, um eine Wahrsageschale zu erschaffen. Benutzt die Schale, um mit Onu zu sprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[945] = { id = 945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Therylunes Flucht", description = "Hilfe!\n\nDiese dreckigen Kultisten haben mich umzingelt, während ich durch die Meistergleve spazierte. Was für ein Glück, dass ich so gut im Verstecken bin!\n\nKönnt Ihr mir hier raushelfen? Ich sollte auch meiner Schwester Therysil Bescheid geben, dass es mir gut geht. Sie wohnt im Eschental im Süden, beim Schrein von Aessina.", sourceObjective = "Verhelft Therylune zur Flucht und teilt dann Therysil beim Schrein von Aessina mit, dass ihre Schwester in Sicherheit ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[947] = { id = 947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höhlenpilze", description = "Ich entwickle gerade einen Trank, für den rare Pilze erforderlich sind. Pilze, die nur in einer bestimmten Höhle wachsen. Diese Höhle liegt hinter den Klippenquellfällen im Osten, leicht nördlich entlang der Berge.\n\nIch würde ja selbst dorthin gehen, aber der Hain der Uralten hat mir geraten, mich von diesem Ort fern zu halten. Unsere altehrwürdigen Verbündeten spüren, dass die Höhle ein Versteck für etwas Neues, Böses in Dunkelküste ist.\n\nBitte, {name}, sammelt doch ein paar Pilze für mich, und wenn Ihr schon dabei seid, könntet Ihr auch gleich die Höhle erkunden, um die Befürchtungen der Urtume eventuell zu bestätigen.", sourceObjective = "Bringt Barithras Mondschatten in Auberdine 5 Schorfstänglinge und 1 Todeskappe.", sourceObjectiveStatus = "unverified-source-field" }
quests[948] = { id = 948, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Onu", description = "Onu, ein Urtum der Lehren im Hain der Uralten, hat von Eurer Reise zu den Klippenquellfällen erfahren und möchte Euch sprechen. Der Hain liegt im Süden, im Schatten der Berge.\n\nDie Urtume sind geduldig und weise, {name}. Aber wenn Onu Euch um Rat bezüglich dessen ersucht, was Ihr in den Fällen gesehen habt, fürchte ich, dass es wichtig ist.", sourceObjective = "Sprecht im Hain der Uralten mit Onu.", sourceObjectiveStatus = "unverified-source-field" }
quests[949] = { id = 949, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Lager des Schattenhammers", description = "Niemand weiß, was der Schattenhammer in der Meistergleve vorhat. Aber es muss etwas Böses sein.\n\nDurchsucht ihr Lager bei der Meistergleve... Sucht nach etwas, das uns ihre Absichten verraten könnte.\n\nWir müssen unbedingt wissen, was sie im Schilde führen, bevor wir einen Plan schmieden können.", sourceObjective = "Sucht im Lager des Schattenhammers in der Meistergleve nach einem Hinweis.", sourceObjectiveStatus = "unverified-source-field" }
quests[950] = { id = 950, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Onu", description = "Der Blick in den Schattenhammerfolianten kann einen wahnsinnig machen. Der Text verschwimmt und tanzt vor Euren Augen, kaum dass Ihr ihn einen Moment betrachtet habt, und die einst so wunderschönen Illustrationen verzerren sich zu grotesken Formen und Mustern.\n\nIhr könnt gerade noch eine Seite des irrsinnigen Gekritzels herausreißen, bevor Ihr ohnmächtig werdet.", sourceObjective = "Bringt Onu das irrsinnige Gekritzel, das Ihr gefunden habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[951] = { id = 951, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relikte von Mathystra", description = "Das Pergament, das Ihr in der Meistergleve gefunden habt, ist eine Seite aus einem alten Text... geschrieben von Elfen! Es ist übelst verflucht und besudelt von der Verderbnis des Schattenhammers, aber es scheint, als würde der Kult alte Elfenmagie benutzen, um seine alten Meister in unsere Welt zurückzuholen.\n\nReist zu den Ruinen von Mathystra im Nordosten und sucht nach alten Relikten unter dem Gras und den zerbrochenen Steinen. Indem wir sie studieren, können wir vielleicht herausbekommen, auf welche Weise der Schattenhammer die Magie der Elfen nutzen will.", sourceObjective = "Bringt 6 Relikte von Mathystra zu Onu in den Hain der Uralten.", sourceObjectiveStatus = "unverified-source-field" }
quests[952] = { id = 952, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hain der Uralten", description = "Wenn Ihr genug Zeit hattet, um für den Orakelbaum Nachrichten zu übermitteln, kann ich Euch sicherlich dazu bewegen, eine Nachricht in den Hain der Uralten in Dunkelküste zu bringen, südlich von Auberdine.\n\nIhr werdet höchstwahrscheinlich ein sicheres Transportmittel wie einen Hippogryphen benötigen, aber ich baue darauf, dass Ihr das regeln könnt. Bringt dies Onu, dem Urtum der Lehren. Er wartet auf eine Nachricht von mir, so wie ich auf Neuigkeiten aus der Lichtung des Orakels wartete.", sourceObjective = "Bringt Fandrals Nachricht zu Onu in den Hain der Uralten in Dunkelküste, südlich von Auberdine.", sourceObjectiveStatus = "unverified-source-field" }
quests[953] = { id = 953, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Untergang von Ameth'Aran", description = "Im Osten findet Ihr die Ruinen von Ameth'Aran. Sie werden heute von den ruhelosen Geistern der Hochgeborenen bewohnt, die einst dort lebten. Damals jedoch war es ein Ort, an dem die Diener Azsharas ihre mächtige Magie ungestört praktizieren konnten.\n\nMan hat mich geschickt, die Ruinen zu erkunden und ich stieß auf zwei große Schrifttafeln, auf denen die Geschichten Ameth'Arans und seines Unterganges beschrieben werden. Während ich die Runen las, traten Geister an mich heran und ich floh.\n\nBitte, wenn es Euch möglich ist, begebt Euch zu den Ruinen und entziffert an meiner statt die Schrifttafeln.", sourceObjective = "Studiert die Schrifttafeln, die von Ameth'Aran und ihrem Untergang erzählen, und kehrt dann zur Schildwache Tysha Mondklinge in Dunkelküste zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[954] = { id = 954, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bashal'Aran", description = "Die Ruinen von Bashal'Aran im Osten sind von dämonischen Dienern überrannt worden. Die Grimmlinge und Satyrn haben sich in dem Gebiet niedergelassen und nähren sich von den magischen Energien dort. Ihre Macht wächst, je länger sie sich dort aufhalten.\n\nDennoch habe ich festgestellt, dass es dort einen Schrein gibt, dem sie nicht zu nahe kommen wollen. An der Westseite der Ruinen auf einem kleinen Steilhang entspringt eine seltsame blaue Aura... Das muss eine Erklärung für das Widerstreben der Dämonen sein.\n\nIch hätte gern, dass Ihr das untersucht.", sourceObjective = "Sucht in den Ruinen von Bashal'Aran nach der Quelle der seltsamen blauen Aura.", sourceObjectiveStatus = "unverified-source-field" }
quests[955] = { id = 955, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bashal'Aran", description = "Sollte ich jemals gehalten sein, die Geschichte meines Lebens zu erzählen, würde dies zweifellos die Grenzen Eurer Geduld überstrapazieren. Sagen wir einfach, dass mein Leben lang und schmerzvoll war, und dass diese meine spektrale Gestalt die schlimmste Pein von allem ist.\n\nIch werde durch Magie hier festgehalten. Mögen meine Worte auch unaufrichtig erscheinen, so versichere ich Euch doch, dass ich über die Maßen dankbar wäre, würdet Ihr mir helfen, den Grund für meine Gefangenschaft herauszufinden. Ein Siegel bindet mich, und vielleicht finde ich einen Hinweis darauf, wenn ich den Ohrschmuck der Grimmlinge und Grells nur näher betrachten könnte.", sourceObjective = "Beschafft für Asterion in Bashal'Aran 8 Grellohrringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[956] = { id = 956, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bashal'Aran", description = "Wenn die Grells erst kürzlich mit dem Siegel in Berührung gekommen sind, das mich an dieses ewige Gefängnis bindet, glaube ich, den Grund dafür zu wissen. Zweifellos ist das Siegel in den Besitz des Satyrs gelangt, der sie anführt.\n\nIch bin mir ganz sicher, dass es so ist, {name}. Einer der Satyrn muss es besitzen. Wenn Ihr es an Euch bringen könntet, würde es mich der Überwindung der Gitterstäbe meines Gefängnisses so nahe bringen, dass es mich zu Tränen rühren würde.", sourceObjective = "Beschafft das alte Mondsteinsiegel und bringt es Asterion in Bashal'Aran.", sourceObjectiveStatus = "unverified-source-field" }
quests[957] = { id = 957, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bashal'Aran", description = "Es war die Kunst eines der mächtigsten Hochgeborenen, der das Siegel erschuf, das mein Gefängnis war. In Ameth'Aran, den Ruinen im Süden, die diesen hier aufs Haar gleichen, gibt es sogar heute noch eine uralte Flamme, blau ist ihre Farbe. In dieser Flamme könnte man dieses Siegel zerstören.\n\nAchtet auf die Ruinen, {name}!", sourceObjective = "Zerstört das alte Mondsteinsiegel in der uralten Flamme in Ameth'Aran und kehrt dann zu Asterion in Bashal'Aran zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[958] = { id = 958, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Werkzeuge der Hochgeborenen", description = "{class}, ich möchte Euch um etwas bitten.\n\nHabt Ihr die Ruinen von Ameth'Aran gesehen? Falls nicht, findet Ihr sie auf der Ostseite der Hauptstraße, ein paar Straßen weiter südlich. Einst waren sie die Heimat vieler mächtiger Hochgeborener, doch heute sind sie Zeugnis der Zerstörung, die sie mit ihrem Dilettantismus angerichtet haben.\n\nDie Schildwachen sagten mir, dass die Geister der Hochgeborenen immer noch umgehen und dass sie ihre alten, magischen Utensilien immer noch benutzen. Wir müssen uns diese Relikte aneignen, damit wir sie zerstören können.", sourceObjective = "Sucht sieben Hochgeborenenrelikte und bringt sie Thundris Windwirker in Auberdine.", sourceObjectiveStatus = "unverified-source-field" }
quests[959] = { id = 959, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger auf den Docks", description = "Upps!\n\nWie Ihr seht, ist mir ein kleines Malheur passiert! Die Morgenlieferung aus Beutebucht war umfangreich. Wirklich gewaltig! Noch nie habe ich so viele Kisten gesehen. Tja, ich wollte die Sache etwas beschleunigen, deshalb habe ich begonnen mehr abzuladen, als ich auf einmal bewältigen konnte. Und dann ist alles zusammengebrochen.\n\nBevor ich wusste, was überhaupt los war, sah ich diese Nervensäge Zausel den Verrückten mit einer Flasche 99-jährigem Portwein wegrennen. Hab ihn bis zu den Höhlen des Wehklagens verfolgt. Da wollte ich auf keinen Fall rein.\n\nVielleicht seid Ihr ja mutig genug, um nach ihm zu suchen?", sourceObjective = "Kranführer Moppelfuzz in Ratschet möchte, dass Ihr Zausel dem Verrückten, der sich in den Höhlen des Wehklagens versteckt, die Flasche mit 99-jährigem Portwein wieder abnehmt.", sourceObjectiveStatus = "unverified-source-field" }
quests[960] = { id = 960, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Onu meditiert" }
quests[961] = { id = 961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Onu meditiert" }
quests[962] = { id = 962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlangenflaum", description = "Die Königliche Apothekervereinigung, die in der großen Unterstadt Lordaerons ansässig ist, hat mich geschickt, um eine ganz besondere Aufgabe zu erledigen, {name}. Vielleicht möchtet Ihr mich und damit auch die Dunkle Fürstin bei unseren Bemühungen, die Verlassenen weiterzubringen, unterstützen.\n\nIch studiere seit Kurzem eine rare Pflanzenart namens Schlangenflaum. Ich denke, dass dieses Kraut in größeren Mengen außerordentliches Potenzial besitzt.\n\nLeider findet man Schlangenflaum nur in den dunkelsten Winkeln der Höhlen des Wehklagens, einem gefährlichen Höhlensystem im Brachland.", sourceObjective = "Die Apothekerin Zamah in Donnerfels möchte, dass Ihr zehn Schlangenflaum für sie sammelt.", sourceObjectiveStatus = "unverified-source-field" }
quests[963] = { id = 963, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In ewiger Liebe", description = "Nach den Schlachten um den Brunnen der Ewigkeit hörte ich, dass Ameth'Aran zerstört wurde und alle Bewohner ums Leben kamen, darunter auch meine geliebte Anaya.\n\nIch hätte nie gedacht, dass mich noch heute, Tausende von Jahren später, die Erinnerungen an Anaya um den Schlaf bringen würden. Ich wanderte wie in Trance durch die Wälder von Dunkelküste und fand mich schließlich in den Ruinen von Ameth'Aran wieder... wo ich den gequälten Geist meiner Geliebten sah.\n\nSie muss befreit werden, aber ich kann es nicht über mich bringen, dies zu tun. Ihr Geist muss zerstört werden.", sourceObjective = "Befreit den Geist von Anaya Dämmerflucht und bringt ihren Anhänger zu Cerellean Weißklaue in Auberdine.", sourceObjectiveStatus = "unverified-source-field" }
quests[964] = { id = 964, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skelettfragmente", description = "Um in die Scholomance zu gelangen, benötigt ihr einen Dietrich. Er muss aus den Überresten eines Skeletts geschmiedet werden - eigentlich aus mehreren - und er darf nur durch die stärksten Metalle in einer geeigneten Form gehärtet werden. Ein Signet der Macht von einem Wesen, das das Portal zur Scholomance natürlich öffnen kann, gibt dem Schlüssel seine endgültige Funktion.\n\nAber eines nach dem anderen, {name}. Wir benötigen Skelettfragmente für das Schmieden des Schlüssels. Skelette innerhalb von Andorhal sollten den gewünschten Effekt bringen, aber die außerhalb der Mauern könnten vielleicht auch ausreichen.", sourceObjective = "Bringt 15 Skelettfragmente zu Apotheker Zitters am Bollwerk in Tirisfal.", sourceObjectiveStatus = "unverified-source-field" }
quests[965] = { id = 965, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Turm von Althalaxx", description = "Grüße, {race}. Ich bin Elissa Sternenhauch und es ist meine Aufgabe, Auberdine vor Schaden zu schützen.\n\nAus diesem Grund habe ich Balthule Schattenhieb ausgeschickt, um die seltsamen Vorkommnisse rund um den Turm von Althalaxx im Nordosten zu beobachten.\n\nEr hätte eigentlich schon längst wieder zurück sein sollen. Daher fürchte ich, dass er im Wald auf eine unvorhersehbare Gefahr gestoßen ist. Ich würde es außerordentlich zu schätzen wissen, wenn Ihr nach ihm suchen und dafür sorgen würdet, dass es ihm gut geht.", sourceObjective = "Sucht Balthule Schattenhieb in der Nähe des Turms von Althalaxx in Dunkelküste.", sourceObjectiveStatus = "unverified-source-field" }
quests[966] = { id = 966, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Turm von Althalaxx", description = "Eine Gruppe Hexenmeister hat sich in und um den Turm herum niedergelassen. Ich wollte ja schon früher nach Auberdine zurückkehren, um Elissa Bericht zu erstatten, aber ich befürchtete, hier etwas zu verpassen, solange ich fort wäre.\n\nDelgren vermutete, dass sich eine solche Gesellschaft beim Turm versammeln würde, aber er wusste nicht, warum.\n\nEin paar Pergamentfetzen, die die Hexenmeister bei sich führten, sind mir in die Hände gefallen, aber ich brauche noch mehr, um das Rätsel zu lösen. Ich warne Euch jedoch, geht lieber nicht in den Turm hinein, denn die Hexenmeister dort sind noch viel mächtiger!", sourceObjective = "Sammelt 4 abgenutzte Pergamentfetzen für Balthule Schattenhieb in der Nähe des Turms von Althalaxx.", sourceObjectiveStatus = "unverified-source-field" }
quests[967] = { id = 967, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Turm von Althalaxx", description = "Mein Meister, Delgren der Läuterer, ist ein Paladin, der gütigerweise seine Unterstützung bei der Verteidigung unseres Waldes vor den Streitkräften der Dämonen und Untoten angeboten hat. Er hat mich viel über das Heilige Licht und die Kampfkunst gelehrt.\n\nDelgren muss sofort über die Machenschaften des Kults informiert werden.\n\nIhr findet ihn ganz weit südlich von hier in Maestras Posten im Eschental. Beeilt Euch, ich fürchte nämlich, dass die Bedrohung durch den Dunklen Strang stündlich größer wird.", sourceObjective = "Überbringt Delgren dem Läuterer im Eschental Balthules Brief.", sourceObjectiveStatus = "unverified-source-field" }
quests[968] = { id = 968, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht in der Tiefe", description = "Obwohl das Buch ziemlich abgenutzt und zerfleddert ist, ist der Titel auf dem Buchdeckel noch gut lesbar:\n\n'Die Macht in der Tiefe'\n\nIn diesem Buch findet sich eine Auflistung unaussprechlicher Namen mit viel sagenden Betitelungen, Verehrungsmethoden und bevorzugten Opferritualen... bei denen sehr oft lebende, humanoide Kreaturen verwendet werden.\n\nAuf der Innenseite des Einbands stehen die Worte: 'Knochengriffs Runen und Verhängnisse, Düsteres Viertel, Eisenschmiede. Inhaber: Gerrig Knochengriff.'\n\nWenn Knochengriff derartige Bücher verkauft, nimmt er dieses hier vielleicht zurück.", sourceObjective = "Bringt das Buch: 'Die Macht in der Tiefe' zu Gerrig Knochengriff im Düsteren Viertel in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[969] = { id = 969, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Glück sei mit Euch", description = "Ah, ich seh's Euch direkt an: Ihr möchtet, dass ich Euch einen Glücksbringer anfertige. Mau'ari weiß immer Bescheid!\n\nIm Süden findet Ihr eine Schlucht und Riesen, die komplett aus Eis bestehen. Die Riesen tragen die Splitter manchmal bei sich, aber Ihr könnt sie auch selbst in der Schlucht sammeln. Diese Splitter haben mächtige reflektierende Eigenschaften.\n\nBringt mir 4 Frosthagelsplitter und mein Glücksbringer wird Euch gehören.", sourceObjective = "Sammelt 4 Frosthagelsplitter für die Hexendoktorin Mau'ari in der Ewigen Warte.", sourceObjectiveStatus = "unverified-source-field" }
quests[970] = { id = 970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Turm von Althalaxx", description = "Balthules Brief verkündet Unheil. Dieser Kult des Dunklen Strangs ist mir ein Dorn im Auge, der entfernt werden muss. Ich hatte nordöstlich von hier in Ordil'Aran schon einmal mit dem Abschaum des Dunklen Strangs zu tun. Eines seiner Mitglieder besitzt einen Seelenedelstein, der, wie ich glaube, das Geheimnis der Macht des Kults enthält.\n\nBringt ihn mir, dann kann ich die darin zu findenden Geheimnisse entschlüsseln.", sourceObjective = "Beschafft einen leuchtenden Seelenedelstein und bringt ihn Delgren dem Läuterer in Maestras Posten.", sourceObjectiveStatus = "unverified-source-field" }
quests[971] = { id = 971, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wissen in der Tiefe", description = "Wie Ihr vielleicht wisst, trage ich Lehren zusammen. Alte Lehren. Mächtige Lehren. Lehren, die Portale öffnen, und Lehren, die die schlafenden Alten Götter erwecken können.\n\nEs kursieren Gerüchte um einen alten Text, das 'Manuskript von Lorgalis', das sich tief unten in der Tiefschwarzen Grotte im Westen. Dieser Ort ist die ehemalige Heimat unserer längst verstorbenen Ahnen. Elfen, die über großes Wissen verfügten, bevor ihre Stadt zerfiel.\n\nSucht in der Tiefschwarzen Grotte nach dem Manuskript. Wenn Ihr das tut, werde ich Euch das nie vergessen. Auch nicht... nach dem Ende aller Tage.", sourceObjective = "Bringt das 'Manuskript von Lorgalis' zu Schildwachenschülerin Issara zum Stützpunkt an der Grotte.", sourceObjectiveStatus = "unverified-source-field" }
quests[972] = { id = 972, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wassersapta" }
quests[973] = { id = 973, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Turm von Althalaxx", description = "Ilkrud Magskluve. Ja, ich kenne ihn. Er ist ein mächtiger orcischer Hexenmeister, der im Schrein des Sengenden Feuers lebt, einem äußerst bösen Ort im südwestlichen Eschental.\n\nBislang ist er nur ein geringes Ärgernis und ich hatte noch nichts mit ihm zu tun, aber es sieht so aus, als wäre jetzt seine Zeit gekommen.", sourceObjective = "Bringt Delgren dem Läuterer in Maestras Posten Ilkrud Magskluves Folianten.", sourceObjectiveStatus = "unverified-source-field" }
quests[974] = { id = 974, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Quelle finden", description = "Die heißen Quellen hier sind eine Quelle der Geheimnisse für mich. Woher kommt die Hitze?\n\nWenn ich mir überlege, wie nah diese Teiche beim Feuersäulengrat sind, frage ich mich wirklich, ob der Vulkan etwas damit zu tun hat. Ich habe ein Thermometer entwickelt, um die Temperaturen am Vulkan zu messen, und ich würde gern die heißeste Stelle finden. Es zeigt die Messungen in Grad Kraklenheit an!\n\nHier, nehmt es und messt die Temperaturen am Grat, wann immer Ihr eine heiße Stelle seht!", sourceObjective = "Krakle im Krater von Un'Goro möchte, dass Ihr den heißesten Bereich des Feuersäulengrats findet.\n\nImmer, wenn Ihr eine heiße Stelle findet, klickt Ihr das Thermometer mit der rechten Maustaste an, um die Temperatur zu überprüfen. Sucht, bis Ihr die heißeste Stelle gefunden habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[975] = { id = 975, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Behälter von Mau'ari", description = "Also, bevor ich Euch dies'n Glücksbringer geb, erklär ich Euch besser, wie er zu verwenden is'.\n\nWenn Ihr den Glücksbringer bei Euch tragt, werdet Ihr feststell'n, dass die Kreaturen, gegen die Ihr kämpft, bestimmte Gegenstände fallenlassen. Wenn Ihr den Glücksbringer nich' dabei habt, werdet Ihr sie nich' find'n. Kapiert?\n\nIhr erkennt diese speziellen Gegenstände am Namen - sie werden E'ko genannt. Wenn Ihr solche Gegenstände findet, bringt Ihr sie einfach der alten Mau'ari, und sie hilft Euch.\n\nWartet hier, während ich Euren Glücksbringer anfertige.", sourceObjective = "Wartet einen Moment und sprecht dann erneut mit Hexendoktorin Mau'ari, um den Glücksbringer zu erhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[976] = { id = 976, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachschub für Auberdine", description = "Delgren hat mich gebeten, der Schildwache Sternenhauch in Auberdine Nachrichten und Nachschub zu bringen, aber es schmeckt mir gar nicht, allein dorthin zu gehen. Im Wald sind gefährliche Feinde zugange und ich möchte nicht riskieren, dass der Nachschub und die Informationen in die falschen Hände geraten.\n\nWenn Ihr und ein paar andere als Wachen mit mir kämen, könnte ich sofort gehen. Mit Eurem Schutz zweifle ich nicht daran, dass wir diese Dinge sicher nach Auberdine bringen können.", sourceObjective = "Sprecht mit Delgren dem Läuterer bei Maestras Posten, nachdem Ihr Feero sicher durch das Eschental geführt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[977] = { id = 977, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sind wir endlich da, Yeti?", description = "Nachdem ich jetzt alles habe, was ich benötige, um die mechanischen beweglichen Teile abzudecken, benötige ich nur noch eine weitere Sache. Na ja, eigentlich zwei. Zwei Hörner!\n\nDie Eisdistelpatriarchen und -matriarchinnen haben die größten Hörner, also will ich natürlich diese. Diese Yetiart bewohnt eine Höhle im Südosten. Es gibt viele von ihnen; Ihr solltet keine Probleme haben, sie zu finden.\n\nDenkt daran, ich will nur die bestaussehenden - keine beschädigten oder zerbrochenen Hörner, bitte!", sourceObjective = "Sammelt 2 makellose Yetihörner für Umi Rumpelkicher in der Ewigen Warte.", sourceObjectiveStatus = "unverified-source-field" }
quests[978] = { id = 978, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mondbestrahltes Wildekin", description = "Wildekinfedern aus dem Hinterland scheinen Spuren magischer Fähigkeiten zu enthalten. Diese Kräfte... sie scheinen von den Kreaturen nicht bewusst eingesetzt zu werden, es scheint eher, als wären sie der Art angeboren; ein Teil ihres innersten Wesens.\n\nWährend meiner Studien habe ich gehört, dass eine große Population von Wildekin die schneebedeckten Länder von Winterquell bewohnt. Könnten diese Kreaturen über die gleichen Kräfte verfügen? Helft mir bitte, eine Antwort zu finden, {name}. Begebt Euch nach Winterquell und sammelt die auf dem Boden gefallenen Federn ein. Kehrt dann zu mir zurück.", sourceObjective = "Sammelt 10 mondbestrahlte Federn aus Winterquell und kehrt dann zu Erelas Himmelsbern in Rut'theran zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[979] = { id = 979, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ranshalla suchen", description = "Ja, ja, diese Federn scheinen die gleiche magische Verzauberung zu enthalten, die mir schon zuvor auffiel... Auch wenn ich mir nicht sicher bin, was wir vorfinden werden, solltet Ihr weiterhin nach Antworten suchen, {name}.\n\nEine meiner Kolleginnen reiste kürzlich nach Winterquell, um die Wildekin dort in ihrer heimischen Umgebung zu beobachten. Warum sucht Ihr sie nicht auf und seht, was sie herausgefunden hat?", sourceObjective = "Sucht nach Ranshalla im östlichen Winterquell.", sourceObjectiveStatus = "unverified-source-field" }
quests[980] = { id = 980, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die neuen Quellen", description = "Tja, ich habe von anderen heißen Quellen an einem Ort namens Winterquell gehört, von hier aus gesehen weit im Norden. Das Merkwürdige ist, dass es dort in der Nähe keine Vulkane gibt. Interessant, ich weiß.\n\nAlso, wenn Ihr mehr herausfinden möchtet, solltet Ihr Euch nach Winterquell begeben und mit einer Freundin von mir sprechen. Ihr Name ist Donova Schneeweh und sie hält sich derzeit bei den heißen Quellen dort auf.\n\nIch danke Euch erneut, dass Ihr mir mit meinem Thermometer geholfen habt! Auf dann!", sourceObjective = "Reist nach Winterquell und sprecht mit Donova Schneeweh.", sourceObjectiveStatus = "unverified-source-field" }
quests[981] = { id = 981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Turm von Althalaxx", description = "Für all das, was Ihr geleistet habt, habt Ihr eine ordentliche Belohnung verdient. Kehrt zu Delgren zurück und sagt ihm, dass Ihr Athrikus Narassin eigenhändig den Garaus gemacht habt, und dass der Kult des Dunklen Strangs zerschlagen ist.", sourceObjective = "Sprecht mit Delgren dem Läuterer in Maestras Posten.", sourceObjectiveStatus = "unverified-source-field" }
quests[982] = { id = 982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefer Ozean, weites Meer", description = "Nahe der Ufer von Dunkelküste im Norden liegen zwei havarierte Schiffe - die Silbermorgen und die Nebelschleier. Vor einiger Zeit kollidierten die beiden Schiffe wegen der verfluchten Murlocs, als sie über das weite Meer nach Auberdine segelten. Jetzt liegen sie auf dem Grund des Ozeans als Trophäen für diese Scheusale.\n\nBeide Kapitäne haben es in dieser Nacht nicht geschafft, ihre Schiffe zu verlassen. Ihre Logbücher und anderen Habseligkeiten befinden sich immer noch dort unten in Schließkassetten. Ich möchte Euch bitten, sie für uns zu beschaffen; es würde den Mannschaftsmitgliedern, die sich noch hier aufhalten, viel bedeuten.", sourceObjective = "Beschafft die Schließkassette der Silbermorgen und die Schließkassette der Nebelschleier für Gorbold Stahlhand in Auberdine. Beide Gegenstände findet Ihr an Bord der Schiffswracks nördlich des Dorfes.", sourceObjectiveStatus = "unverified-source-field" }
quests[983] = { id = 983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dröhnkiste 827", description = "He! Helft mir bei meiner neuesten Erfindung, der Dröhnkiste. Man kann damit mit Leuten sprechen, die weit weg sind!\n\nVielleicht habt Ihr sie schon mal gesehen, das sind kleine Kästchen mit Hebeln daran. Ihr einziges Problem ist, dass sie ständig gewartet werden müssen.\n\nJede hat ein anderes Problem, aber ich hab mir etwas ziemlich Schlaues ausgedacht. Ich habe alle in der Nähe von Kreaturen platziert, die über die passenden Teile verfügen, um die jeweilige Maschine zu reparieren. Momentan hat Dröhnkiste 827 den Geist aufgegeben. Sie steht südlich von Auberdine, also gleich in der Nähe. Es werden sechs Kriecherbeine benötigt, um sie zu reparieren. Ich bezahl Euch auch dafür...", sourceObjective = "Sammelt 6 Kriecherbeine und baut sie in Dröhnkiste 827 ein.", sourceObjectiveStatus = "unverified-source-field" }
quests[984] = { id = 984, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie groß ist die Bedrohung?", description = "Einige meiner Brüder konnten in Teldrassil vor einem verderbten Furbolg gerettet werden und ich habe geschworen, weitere Gräueltaten zu verhindern, bevor noch mehr von uns verletzt werden... oder schlimmer.\n\nIch habe auch in Dunkelküste schon die ersten Anzeichen von Verderbnis entdeckt, jedoch noch nichts gefunden, was auf Ausbreitung hindeutet. Ich denke, es wäre logisch, wenn man die Untersuchungen bei den Furbolgs fortsetzen würde. Würdet Ihr wohl eines ihrer Lager aufsuchen und zu mir zurückkehren, falls Ihr dort irgendwelche Anzeichen von Verderbnis entdeckt?", sourceObjective = "Sucht in Dunkelküste nach einem verderbten Furbolglager und kehrt dann zu Terenthis in Auberdine zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[985] = { id = 985, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie groß ist die Bedrohung?", description = "Ihr habt Euer Talent im Ausspähen unserer Feinde bereits unter Beweis gestellt, {name}. Aber habt Ihr auch das Zeug dazu, sie zu bekämpfen?\n\nNicht alle Abenteurer ziehen ein offenes Gefecht der Kunst der Verstohlenheit und des Ausweichens vor.\n\nWenn Ihr glaubt, der Aufgabe gewachsen zu sein, solltet Ihr Euch das Furbolglager südlich von Auberdine vornehmen. Das stellt momentan die größte Bedrohung für unser Volk dar. Ihr werdet dort ein paar Mitglieder des Schwarzfellstamms finden. Tötet 8 Pfadfinder und 5 Windsprecher und kommt dann zu mir zurück.", sourceObjective = "Tötet 8 Pfadfinder der Schwarzfelle und 5 Windsprecher und kehrt dann zu Terenthis in Auberdine zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[986] = { id = 986, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein verirrter Meister", description = "{name}, Eure Fertigkeiten haben mir bei meinen Bemühungen sehr geholfen. Kann ich es wagen, Euch dennoch erneut zu bitten, Grimmklaue und seinem Meister Volcor zu helfen? Ich könnte Euch dazu einen magischen Umhang anfertigen, mit dem Ihr ungehindert an den Kreaturen Dunkelküstes vorbeigelangt, während Ihr nach ihm sucht.\n\nUm den Umhang anzufertigen, benötige ich fünf Mondpirscherpelze von einer Mondpirschermatriarchin oder einem Mondpirscherpatriarchen, um genügend Material zur Verfügung zu haben. Die Katzen findet Ihr südlich von hier, in der Nähe der Wildschnellen, oder noch weiter im Süden, in der Nähe des Eschentals.", sourceObjective = "Sucht 5 feine Mondpirscherpelze und bringt sie Terenthis in Auberdine.", sourceObjectiveStatus = "unverified-source-field" }
quests[990] = { id = 990, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marsch ins Eschental", description = "{name}, meine Herrin Raene Wolfsläufer erwartet Euch in Astranaar im Eschental. Mit Eurer Hilfe könnten wir vielleicht wenigstens eines Teils der Verderbnis Herr werden, die sich dort breitgemacht hat.\n\nGeht von hier aus nach Süden und haltet Euch dicht an der Straße. Wenn Ihr Euch an diese Richtungsangaben haltet, erreicht Ihr problemlos Euer Ziel.", sourceObjective = "Sucht Raene Wolfsläufer im Eschental auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[991] = { id = 991, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Findet Teronis", description = "Eine Freundin von mir aus Astranaar, Raene Wolfsläufer, hat mich gebeten, einen Kundschafter zum Falathimsee im Westen zu schicken. Teronis ist vor Tagen aufgebrochen, kurz bevor die Horde angegriffen hat.\n\nEr war auf der Suche nach einem Gegenstand, von dem er dachte, dass er die Furbolgangriffe auf unser Volk mildern könnte: eine Rute, die von einem mittlerweile toten, bösen Zauberer.\n\nBevor er aufbrach, erwähnte er einen Edelstein für die Rute, von dem er wusste, dass er in einem Schrein auf einer Insel im See ruht.\n\nLeider wissen wir, dass der See von einer bösen Macht heimgesucht worden ist. Bitte, {name}, macht meinen Freund ausfindig.", sourceObjective = "Sucht am Falathimsee im Eschental nach Teronis.", sourceObjectiveStatus = "unverified-source-field" }
quests[992] = { id = 992, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gadgetzan Wassersondierung", description = "Wenn Ihr interessiert seid, hätten wir einen offenen Posten im Rang eines temporären Unterfeldmessers in der Gadgetzan Water Company.\n\nDa die Nomaden unsere Brunnen erobern, müssen wir weitere freie Wasserquellen ausschöpfen! Es gibt Wasser in der Wüste, aber nur für die, die klug genug sind, sie erst zu erforschen.\n\nNehmt diesen Wünschelrutenapparat und zapft damit eine Wasserprobe vom Teich in der Nähe der Sandmarterwache. Er befindet sich direkt in Sichtweite der Trolle dort. Bringt mir den angezapften Apparat zurück, wenn Ihr fertig seid!", sourceObjective = "Benutzt den unangezapften Wünschelrutenapparat in der Nähe des Teichs bei der Sandmarterwache. Bringt den angezapften Wünschelrutenapparat zum Leitenden Feldmesser Rutenwünschels nach Gadgetzan zurück, wenn Ihr die Probe entnommen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[993] = { id = 993, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein verirrter Meister", description = "Der Umhang ist fertig, {name}. Jetzt ist es an der Zeit, Volcor zu suchen. Ich hoffe nur, dass wir es noch rechtzeitig schaffen.\n\nDie Magie des Umhangs hält nicht lang an, nachdem sie herbeigerufen wurde - etwa fünf Minuten. Es liegt an Euch zu entscheiden, wann Ihr sie benutzt: Ich schlage vor, dass Ihr damit wartet, bis Ihr Grimmklaue gefunden habt.\n\nFalls es wahr ist, was er mir erzählte, findet Ihr seinen Meister in einer Höhle südlich von hier. Grimmklaue wird an der Straße auf Euch warten. Gebt ihm ein Signal, indem Ihr winkt, sobald Ihr ihn gesehen habt, dann wird er Euch den Weg zu seinem Meister weisen.", sourceObjective = "Sucht Volcor in Dunkelküste und gebt ihm den verzauberten Mondpirscherumhang.", sourceObjectiveStatus = "unverified-source-field" }
quests[994] = { id = 994, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flucht durch Gewalt", description = "Gut, {name}, dann sei es Gewalt. Lasst uns hier verschwinden, sobald Ihr bereit seid. Wir werden uns unseren Weg hinunter zur Straße erkämpfen - Grimmklaue dürfte immer noch dort sein. Sobald wir sie erreicht haben, können wir uns trennen.\n\nTerenthis wird sofort Eure Version der Geschichte hören wollen, also geht nach Auberdine, sobald wir es hier herausgeschafft haben.", sourceObjective = "Beschützt Volcor, bis Ihr die Straße erreicht habt und sprecht dann mit Terenthis in Auberdine.", sourceObjectiveStatus = "unverified-source-field" }
quests[995] = { id = 995, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flucht durch Verstohlenheit", description = "Na gut... wenn Ihr sicher seid, werden wir uns hier hinausschleichen. Lasst uns verschwinden, sobald Ihr bereit seid.\n\nVergesst nicht, Euch in Auberdine mit Terenthis zu treffen, sobald Euch die Flucht gelungen ist. Ich werde mich auf eigene Faust dort hinbegeben, da ich wahrscheinlich schneller bin als Ihr.", sourceObjective = "Flieht aus der Furbolghöhle und trefft Euch in Auberdine mit Terenthis.", sourceObjectiveStatus = "unverified-source-field" }
quests[996] = { id = 996, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbte Windblüte" }
quests[997] = { id = 997, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Denalans Erde", description = "Seid Ihr nach Süden unterwegs? Zum Al'Amethsee? Wenn dem so ist, möchte ich Euch um einen Gefallen bitten...\n\nMein Kollege Denalan hat am Ostende des Sees ein Lager aufgeschlagen, in dem er die Pflanzenwelt Teldrassils studiert und Experimente betreibt. Er hat in Darnassus ein Päckchen seltener Erden bestellt, und die Lieferung kam erst kürzlich mit Verspätung hier in Dolanaar an.\n\nWürdet Ihr ihm dieses Päckchen wohl bringen?", sourceObjective = "Bringt Denalan am Al'Amethsee das Päckchen seltener Erden.", progress = "Habt Ihr etwas für mich?", completion = "Ah, es ist da! Ich habe schon eine ganze Weile auf diese seltenen Erden gewartet. Hoffentlich sind sie noch frisch...\n\nDanke, dass Ihr sie mir gebracht habt, {name}. Ihr seid ein {race}, der sich noch die Zeit nimmt.", sourceObjectiveStatus = "unverified-source-field" }
quests[998] = { id = 998, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbte Windblüte" }
quests[999] = { id = 999, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn Träume zu Alpträumen werden" }
quests[1000] = { id = 1000, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die neue Grenze", description = "Aufgemerkt, Helden!\n\nDer Zirkel des Cenarius sucht nach einsatzfähigen Individuen, die dazu beitragen möchten, ihn bei der Erforschung der riesigen neuen Grenzgebiete Kalimdors zu unterstützen! Weit im Westen von Tanaris und Gadgetzan liegt eine abschreckende Ödnis voller unvorstellbarer Gefahren, und der Zirkel braucht ehrbare und gewillte Vertreter, die an seiner statt agieren.\n\nInteressenten mögen bitte zwecks einer Audienz beim Zirkel des Cenarius vorstellig werden. Weitere Informationen erhaltet Ihr beim Erzdruiden Hamuul Runentotem auf der Anhöhe der Ältesten in Donnerfels.", sourceObjective = "Sprecht auf der Anhöhe der Ältesten in Donnerfels mit dem Erzdruiden Hamuul Runentotem über den Aufruf des Zirkels des Cenarius zur Erforschung der Grenzgebiete von Kalimdor.", sourceObjectiveStatus = "unverified-source-field" }
quests[1001] = { id = 1001, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dröhnkiste 411", description = "Aus dem Inneren der Maschine ist eine leise Stimme zu hören.\n\n\"Hier spricht Hexknall! Die nächste Dröhnkiste befindet sich nördlich von Auberdine, am Strand.\n\nAlso, es ist die Dröhnkiste mit der Nummer 411 und es werden 3 Drescheraugen benötigt, um sie zu reparieren. Sie befinden sich direkt vor der Küste! Die Dunkelküstendrescher... *Hick*... Tut mir leid...\n\nÜbrigens, wie beim letzten Mal wird die Dröhnkiste Eure Belohnung ausspucken, sobald Ihr die Sachen in die Maschine eingebaut habt. *Hick*... Was? Nein, mir geht's gut!\"", sourceObjective = "Besorgt Euch 3 Drescheraugen von den Dunkelküstendreschern im tiefen Meer in der Nähe der Dröhnkiste 411.", sourceObjectiveStatus = "unverified-source-field" }
quests[1002] = { id = 1002, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dröhnkiste 323", description = "Die Dröhnkiste gibt statische Geräusche von sich, als Hexknall zu sprechen beginnt.\n\n\"Die nächste Dröhnkiste ist Nummer 323. Schteht nördlich von Auberdine, aber... wo's das Bier? Wa...? Oh, schteht direkt an der Straße, kann man gar nicht verfehlen, gleich neben der Brücke.\"\n\nHexknall murmelt wirres Zeug vor sich hin, bevor Ihr ein lautes Schluckgeräusch hört.\n\n\"Der da fehlen Mondpirscherfangzähne... sechs davon.\"", sourceObjective = "Sammelt 6 Mondpirscherfangzähne und baut sie in Dröhnkiste 323 ein.", sourceObjectiveStatus = "unverified-source-field" }
quests[1003] = { id = 1003, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dröhnkiste 525", description = "Hexknalls zitternde Stimme übertönt die Blubber- und Tropfgeräusche, die aus dem Inneren der Maschine dringen.\n\n\"Näxte is' die Straße weiter runter nach Süden. Is' leicht zu find'n... direkt am Straßenrand... neben ei'm Sssaun. Glaub, ich hab sie hinner'n paar Büscheln verschteckt... Büschen. Hehehe... Jaaa, Dröhnkiste 525 fehlen ergraute Skalps von dies'n grauhaarigen Dischtelbären. Mann, das schpricht sich blöd. Dissstelbär... Hehehe...\"\n\nIhr hört weitere Schluckgeräusche, dann schaltet sich die Maschine aus. Plötzlich erwacht sie jedoch wieder zum Leben.\n\n\"4!\"", sourceObjective = "Sammelt 4 ergraute Skalps von ergrauten Distelbären südlich von Auberdine und legt sie in die Dröhnkiste 525.", sourceObjectiveStatus = "unverified-source-field" }
quests[1004] = { id = 1004, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die neue Grenze", description = "Aufgemerkt, Helden!\n\nDer Zirkel des Cenarius sucht nach einsatzfähigen Individuen, die dazu beitragen möchten, ihn bei der Erforschung der riesigen neuen Grenzgebiete Kalimdors zu unterstützen! Weit im Westen von Tanaris und Gadgetzan liegt eine abschreckende Ödnis voller unvorstellbarer Gefahren, und der Zirkel braucht ehrbare und gewillte Vertreter, die an seiner statt agieren.\n\nInteressenten mögen bitte zwecks einer Audienz beim Zirkel des Cenarius vorstellig werden. Weitere Informationen erhaltet Ihr beim Erzdruiden Hamuul Runentotem auf der Anhöhe der Ältesten in Donnerfels.", sourceObjective = "Sprecht auf der Anhöhe der Ältesten in Donnerfels mit dem Erzdruiden Hamuul Runentotem über den Aufruf des Zirkels des Cenarius zur Erforschung der Grenzgebiete von Kalimdor.", sourceObjectiveStatus = "unverified-source-field" }
quests[1005] = { id = 1005, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was dahinter lauert" }
quests[1006] = { id = 1006, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was dahinter liegt" }
quests[1007] = { id = 1007, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die antiken Statuetten", description = "Ich würde Euch gern eine Aufgabe übertragen, {name}.\n\nIch war auf meinem kleinen Schiff und kreuzte über den versunkenen Ruinen von Zoram, als ich plötzlich von Naga angegriffen wurde, die aus dem Wasser stießen und mich mit ihren Klauen beharkten! Ich floh und der Rest ist, wie man so schön sagt, Geschichte.\n\nIch bin eine Art Archäologe und versuche die Artefakte der versunkenen Stadt zu bergen.\n\nWürdet Ihr Euch zum Zoramstrand im Südwesten aufmachen und alle antiken Statuetten bergen, die Ihr finden könnt? Sie sind der Grund, warum ich die Gefahren des Zoramstands auf mich genommen habe.", sourceObjective = "Sammelt 10 Antike Statuetten.", sourceObjectiveStatus = "unverified-source-field" }
quests[1008] = { id = 1008, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zoramstrand", description = "Böses lauert an unserer nordwestlichen Küste, die als Zoramstrand bekannt ist.\n\nEs ist die Ruhestätte der untergegangenen Stadt Zoram, die während der Großen Zerschlagung zerstört wurde und im Meer versank. Die Nachtelfen verloren sie vor Urzeiten. Sie war verloren und fast vergessen.\n\nJetzt allerdings sind die Naga zurückgekehrt, aber warum, wissen wir nicht. Es ist auch unwichtig. Wir müssen diese Scheusale vernichten und zurück in die Tiefe treiben!\n\nKehrt zu mir zurück, wenn Ihr Eure Mission abgeschlossen habt.", sourceObjective = "Bringt Shindrell Feuerflink in Astranaar 20 Köpfe von Rächerflossen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1009] = { id = 1009, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruuzel", description = "Ich fürchte, die Geheimnisse der antiken Statuetten werden für immer verborgen bleiben, wenn Ihr nicht den Schlüssel zu ihren antiken Schlössern findet.\n\nDieser Schlüssel ist ein Ring, der Ring von Zoram. Er gehörte einst den Herrschern dieser Stadt, bevor sie in den Wellen der Großen Zerschlagung unterging.\n\nÜber Jahre hinweg war der Ring verloren, aber die Naga haben ihn vor Kurzem gefunden.\n\nRuuzel, ihre Anführerin, haust auf einer Insel am nördlichen Ende des Zoramstrands. Bitte, {name}, beschafft mir den Ring!", sourceObjective = "Nehmt den Ring von Zoram an Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[1010] = { id = 1010, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bathranshaar", description = "Es gibt eine Pflanze, die in den alten Ruinen von Bathrans Schlupfwinkel im Osten wächst. Die Planze heißt Bathranshaar und es heißt, sie könne Erkrankungen des Geistes heilen.\n\nDieser Tage ist die Horde dort damit beschäftigt, die Pflanzen für ihre eigenen finsteren Pläne zu sammeln.\n\nEs gibt ein krankes Kind in Astranaar und wir glauben, dass ihre Krankheit mehr als nur körperlicher Natur ist. Ich habe meinem Meister versprochen, dass ich nach einem Heilmittel suchen würde, nur bin ich kein Kämpfer.\n\nWürdet Ihr die Pflanzen für mich aus Bathrans Schlupfwinkel besorgen?", sourceObjective = "Sammelt 8 Bathranshaar.", sourceObjectiveStatus = "unverified-source-field" }
quests[1011] = { id = 1011, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verlassenenkrankheit", description = "Die Verlassenen, der untote Arm der Horde, haben sich ins Eschental eingeschlichen und treiben sich in unseren Ruinen und Grabhügeln herum. Wir glauben, dass sie die Krankheit im Land der Nachtelfen verbreiten wollen. Wir müssen das genau wissen!\n\nDie Verlassenen haben südlich von hier, in der Nähe des Grabhügels von Dor'Danil, ein Lager, in dem sie Gifte und Krankheiten entwickeln und in Flaschen füllen. Kämpft Euch in das Lager hinein und stehlt eine Krankheitsflasche. Bringt mir eine solche Flasche. Ich werde sie testen und herausfinden, was sie bewirkt.", sourceObjective = "Bringt Kayneth Stillwind in Waldeslied eine Krankheitsflasche.", sourceObjectiveStatus = "unverified-source-field" }
quests[1012] = { id = 1012, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Irrsinnige Druiden", description = "Die Druiden sind tot, von ihren Anführern ermordet, die wegen der Verunreinigung des Herzen des Waldes durch die Horde in den Wahnsinn getrieben wurden! Ich kann die Verderbnis sogar hier spüren und wage mich nicht näher heran.\n\nZwar bin ich zu sehr im Einklang mit dem Eschental und dem Herz des Waldes, Ihr jedoch... Ihr könntet in den Grabhügel hinabsteigen und tun, was getan werden muss. Ich habe im Inneren eine Spur für Euch gelegt.\n\nAuch wenn es mir das Herz zerbricht, muss ich Euch bitten, die einst so großen Anführer der Druiden zur letzten Ruhe zu betten: Taneel Finsterwald, Uthil Mondweise, Mavoris Wolkenbruch.", sourceObjective = "Tötet die wahnsinnigen Druiden Taneel Finsterwald, Uthil Mondweise und Mavoris Wolkenbruch.", sourceObjectiveStatus = "unverified-source-field" }
quests[1013] = { id = 1013, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Buch von Ur", description = "{name}, in der Burg Schattenfang gibt es ein Buch, das Buch von Ur, das ich unbedingt in meiner Sammlung haben möchte. Ur war einst ein großer Magier aus Dalaran bevor die Geißel kam. Seine Studien anderer Welten sind von großem Wert für... bestimmte Kreise der Verlassenen.\n\nBetretet die Burg Schattenfang und sucht das Buch. Bringt es mir, dann kann ich unserer Dunklen Fürstin von Euren Diensten berichten...", sourceObjective = "Bringt dem Bewahrer Bel'dugur im Apothekarium in Unterstadt das Buch von Ur.", sourceObjectiveStatus = "unverified-source-field" }
quests[1014] = { id = 1014, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arugal muss sterben", description = "Arugal lebt immer noch in der Burg Schattenfang. Wir können Silberwald erst dann als strategische Festung für die Dunkle Fürstin beanspruchen, wenn Arugal erschlagen ist.\n\nIch werde mich darum kümmern, seine Magie zu neutralisieren, {name}. Ich überlasse es jedoch Euch, für Arugals Tod zu sorgen, den er mehr als verdient.\n\nReist zur Burg Schattenfang und setzt Arugals üblen Zaubern ein für alle Mal ein Ende. Bringt mir den Kopf dieses niederträchtigen Hexers!", sourceObjective = "Tötet Arugal und bringt Dalar Morgenweber in dem Grabmal seinen Kopf.", sourceObjectiveStatus = "unverified-source-field" }
quests[1015] = { id = 1015, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die neue Grenze", description = "Aufgemerkt, Helden!\n\nDer Zirkel des Cenarius sucht nach einsatzfähigen Individuen, die dazu beitragen möchten, ihn bei der Erforschung der riesigen neuen Grenzgebiete Kalimdors zu unterstützen! Weit im Westen von Tanaris und Gadgetzan liegt eine abschreckende Ödnis voller unvorstellbarer Gefahren, und der Zirkel braucht ehrbare und gewillte Vertreter, die an seiner statt agieren.\n\nInteressenten mögen bitte zwecks einer Audienz beim Zirkel des Cenarius vorstellig werden. Sprecht in Darnassus mit dem Erzdruiden Fandral Hirschhaupt, er hat weitere Informationen!", sourceObjective = "Sprecht in der Enklave des Cenarius in Darnassus mit dem Erzdruiden Fandral Hirschhaupt über den Aufruf des Zirkels des Cenarius zur Erforschung der Grenzgebiete von Kalimdor.", sourceObjectiveStatus = "unverified-source-field" }
quests[1016] = { id = 1016, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückeroberung des Mystralsees", description = "Wir hätten die Silberwindzuflucht ohne Weiteres gegen den Ansturm der Horde halten können, wenn sie uns nicht die Kontrolle über unsere Wasserelementarverteidiger im Mystralsee entrissen hätten.\n\nEiner ihrer Schamanen hat Tideress heraufbeschworen, einen alten, wütenden Wassergeist des Waldes, der unsere Elementare besudelt und gegen uns aufgebracht hat. Da sowohl der See als auch die Horde über uns hereingebrochen sind, hatten wir keine andere Wahl, als uns hierher zur Spitze zurückzuziehen.\n\nBegebt Euch nach Osten. Erobert den See zurück, sodass eine Chance besteht, dass wir eines Tages die Zuflucht wieder einnehmen können.", sourceObjective = "Tötet 12 beschmutzte Wasserelementare und Tideress.", sourceObjectiveStatus = "unverified-source-field" }
quests[1017] = { id = 1017, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magier-Beschwörer", description = "Es gibt nur einen untoten Magier im Brachland, der in der Lage wäre, so viele Wasserelementare zu entweihen. Er ist auch der Einzige, der dumm genug wäre, es zu versuchen. Sarilus Faulmut sitzt wahrscheinlich jetzt gerade oben auf dem Glutnebelgipfel und lacht mich aus.\n\n{name}, Ihr müsst Euch in Feindesland begeben und diesen Übeltäter vernichten. Ich habe genug von seinem Schwachsinn und wir müssen ihm zeigen, was mit jenen geschieht, die die Schildwachen verärgern.\n\nVernichtet ihn und bringt mir seinen Kopf. Vorsicht allerdings, die Horde könnte nach Euch Ausschau halten.", sourceObjective = "Erschlagt Sarilus Faulmut und bringt Schildwache Velene Sternenschlag in der Silberwindzuflucht seinen Kopf.", sourceObjectiveStatus = "unverified-source-field" }
quests[1018] = { id = 1018, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die neue Grenze", description = "Aufgemerkt, Helden!\n\nDer Zirkel des Cenarius sucht nach einsatzfähigen Individuen, die dazu beitragen möchten, ihn bei der Erforschung der riesigen neuen Grenzgebiete Kalimdors zu unterstützen! Weit im Westen von Tanaris und Gadgetzan liegt eine abschreckende Ödnis voller unvorstellbarer Gefahren, und der Zirkel braucht ehrbare und gewillte Vertreter, die an seiner statt agieren.\n\nInteressenten mögen bitte zwecks einer Audienz beim Zirkel des Cenarius vorstellig werden. Weitere Informationen erhaltet Ihr beim Erzdruiden Hamuul Runentotem auf der Anhöhe der Ältesten in Donnerfels.", sourceObjective = "Sprecht auf der Anhöhe der Ältesten in Donnerfels mit dem Erzdruiden Hamuul Runentotem über den Aufruf des Zirkels des Cenarius zur Erforschung der Grenzgebiete von Kalimdor.", sourceObjectiveStatus = "unverified-source-field" }
quests[1019] = { id = 1019, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die neue Grenze", description = "Aufgemerkt, Helden!\n\nDer Zirkel des Cenarius sucht nach einsatzfähigen Individuen, die dazu beitragen möchten, ihn bei der Erforschung der riesigen neuen Grenzgebiete Kalimdors zu unterstützen! Weit im Westen von Tanaris und Gadgetzan liegt eine abschreckende Ödnis voller unvorstellbarer Gefahren, und der Zirkel braucht ehrbare und gewillte Vertreter, die an seiner statt agieren.\n\nInteressenten mögen bitte zwecks einer Audienz beim Zirkel des Cenarius vorstellig werden. Sprecht in Darnassus mit dem Erzdruiden Fandral Hirschhaupt, er hat weitere Informationen!", sourceObjective = "Sprecht in der Enklave des Cenarius in Darnassus mit dem Erzdruiden Fandral Hirschhaupt über den Aufruf des Zirkels des Cenarius zur Erforschung der Grenzgebiete von Kalimdor.", sourceObjectiveStatus = "unverified-source-field" }
quests[1020] = { id = 1020, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orendils Heilmittel", description = "{name}, nun da es von Elunes gesegnetem Licht durchflutet wurde, glaube ich, dass das Gebräu dem kranken Kind helfen wird. Bitte bringt es nach Astranaar und gebt es dem Vater des Kindes, Pelturas Weißmond.\n\nUm nach Astranaar zu gelangen, folgt ihr der Straße nach Süden und dann nach Osten. Wenn Ihr aber schneller dorthin gelangen wollt, sprecht mit Schildwache Avana.", sourceObjective = "Bringt Orendils Heilung zu Pelturas Weißmond in Astranaar im Eschental.", sourceObjectiveStatus = "unverified-source-field" }
quests[1021] = { id = 1021, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elende Satyrn! Die Dryaden sind in Gefahr!", description = "Ich weiß zwar nicht, wer Ihr seid, aber ich brauche Eure Hilfe. Meine Schwestern wollten den Satyrn den Zweig des Cenarius abnehmen. Sie sagten, dass sie bald zurück sein werden, aber das war vor zwei vollen Tagen!\n\n{name}, Ihr müsst sie finden! Sie wollten nach den Ruinen eines Nachtelfentempels in Xavian im Nordwesten suchen. Ich weiß nicht, was ich davon halten soll. Sucht nach Anilia, sie wollte sie bei der Suche führen.", sourceObjective = "Sucht in Xavian im Eschental nach Anilia.", sourceObjectiveStatus = "unverified-source-field" }
quests[1022] = { id = 1022, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Heulende Tal", description = "Obwohl wir viele Mittel und große Bemühungen investiert haben, um auch die letzten Dämonen aus dem Teufelswald im Norden zu vertreiben, hatten wir nur wenig Erfolg damit. Wir konnten jedoch einen Großteil der Dämonen vom Eschental fern halten.\n\nIm Norden, nahe der Grenze zum Teufelswald, wurde der verfallene Mel'Thandris-Schrein von rätselhaften Wolfmenschen übernommen. Ihre Schreie, die einem das Blut in den Adern gerinnen lassen, haben dem als Das Heulende Tal bekannten Gebiet seinen Namen gegeben. Der Foliant von Mel'Thandris, der im Schrein aufbewahrt wird, könnte etwas Licht darauf werfen, warum die Wolfmenschen hier sind.", sourceObjective = "Begebt Euch ins Heulende Tal, studiert den Folianten von Mel'Thandris und kehrt dann zur Schildwache Melyria Frostschatten in Waldeslied zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[1023] = { id = 1023, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der verlorene Stein", description = "Während Ihr Teronis Habseligkeiten durchstöbert, stoßt Ihr auf ein Tagebuch, das noch in gutem Zustand ist.\n\nIhr nehmt das Tagebuch und lasst Teronis' Kadaver so wie er ist zurück.\n\nJetzt müsst Ihr nur noch eines tun: den Edelstein finden, den Teronis suchte. Orendil deutete an, dass er sich in diesem Gebiet befinden würde. Vielleicht haben ihn die Ranken...", sourceObjective = "Findet den leuchtenden Edelstein.", sourceObjectiveStatus = "unverified-source-field" }
quests[1024] = { id = 1024, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dryadenlieferung", description = "Ah, da seid Ihr ja, {name}. Ich habe mich in die Anmerkungen vertieft, die Teronis gemacht hat, und es sieht so aus, als ist Euer nächster Schritt, die Teile von Dartols Rute zu finden.\n\nIch würde zunächst nach Osten reisen, zum Rajenbaumturm.\n\nDort findet Ihr eine Dryade namens Shael'dryn, die Euch eine bessere Führerin sein wird. Sucht sie auf.\n\nBehaltet den Edelstein bei Euch - Shael'dryn wird ihn brauchen, um Euch bei der Wiederherstellung der Rute zu helfen.", sourceObjective = "Sucht Shael'dryn am Rajenbaumturm im Eschental auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[1025] = { id = 1025, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine aggressive Verteidigung", description = "Bevor Ihr zum Mondbrunnen aufbrecht, habe ich noch eine andere Aufgabe für Euch, wenn Ihr gern Eure Fertigkeiten auf die Probe stellen und dem Volk des Eschentals helfen würdet.\n\nEntlang der Straße, die nach Osten führt, haben Furbolgs kurz vor dem Falfarren Reisende angegriffen. Ihre gequälten Seelen nähren sich von Angst und sie stillen ihren Appetit mit dem Blut Unschuldiger.\n\nHelft den Schildwachen, das Land zu schützen, indem Ihr diesen Monstern dieselbe Gnade zeigt, die sie uns erwiesen haben.\n\nIch glaube, ihre Lager liegen südlich der Straße... seid vorsichtig.", sourceObjective = "Tötet 1 Höhlenbehüter, 2 Ursa, 10 Totemiker sowie 12 Krieger der Fäulnisklauen und kehrt dann zu Raene Wolfsläufer in Astranaar zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[1026] = { id = 1026, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchsucht den Baumstamm", description = "Ich wünschte, Ihr hättet bessere Nachrichten.\n\nRaene hat Recht, ich weiß von Dartols Werk und den Treants, den Baumwesen in diesem Gebiet - zumindest wusste ich es einst. Heute sind sie verderbt, ihre Natur verzerrt.\n\nFalls es Euer Ziel ist, das nächste Teil der Rute zu finden, solltet Ihr zunächst den Schlüssel suchen, mit dem die Truhe geöffnet werden kann, in der es sich befindet.\n\nEiner der Treants nordöstlich von hier in der Nähe des Teufelswalds hat ihn. Sobald Ihr ihn habt, sucht nach einem kleinen Tal westlich der Straße nahe der Grenze zum Teufelswald am Heulenden Tal. Wenn Ihr es gefunden habt, sucht nach einer kleinen Lichtung hinter dem Tunnel in diesem Tal. Die Truhe ist dort irgendwo versteckt.", sourceObjective = "Sucht den hölzernen Schlüssel und benutzt ihn, um den Eisenschaft von Dartols Rute zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[1027] = { id = 1027, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sich tot stellen", description = "Das letzte Stück der Rute ist im Besitz der Druiden der Klaue. Ich habe ihren Anführer, Oso Dornennarbe, gebeten, es mir auszuhändigen, aber er und seine Wächter hätten mich beinahe umgebracht! Offenbar hat die Verderbnis des Herzens des Waldes seitens der Horde auch die Druiden betroffen.\n\nAber ich habe eine Idee, wie Ihr in Osos Höhle gelangen und den Knauf an Euch nehmen könnt.\n\nSchon als kleiner Faun war ich immer ziemlich gut darin, mich tot zu stellen. Das funktioniert wunderbar gegen Bären! Ich kann es Euch beibringen! Geht nach Osten zum Schattenwinkel und wenn sie versuchen, Euch anzugreifen, probiert einfach meine Taktik aus.", sourceObjective = "Erhaltet das letzte Teil von Dartols Rute, den Eisenschwertknauf.", sourceObjectiveStatus = "unverified-source-field" }
quests[1028] = { id = 1028, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raenes Säuberung", description = "Hier habt Ihr die vollständige Rute, {name}. Es war nicht schwer, sie wieder zusammenzusetzen... Den Schrein zu finden, der die Kraft hat, sie wieder aufzuladen, ist der schwierige Teil.\n\nMit etwas Konzentration und Einsatz sollte es für jemanden wie Euch, der bereits so viel erreicht hat, allerdings nicht zu schwer sein.\n\nGeht von hier aus nach Südosten - es gibt nur wenige Wege, also seid vorsichtig - und behaltet immer den Norden im Auge. Der Schrein liegt in den Bergen verborgen, die dieses Tal umgeben.\n\nDort angekommen legt Ihr die Rute in den Schrein... der Rest ist Magie. Hehe.", sourceObjective = "Sucht den verborgenen Schrein und verzaubert Dartols Rute erneut.", sourceObjectiveStatus = "unverified-source-field" }
quests[1029] = { id = 1029, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Raene", description = "Ich schlage vor, dass Ihr Raene aufsucht und sie wissen lasst, dass die Rute fertig gestellt ist. Sie weiß bestimmt, was Ihr als Nächstes tun solltet.\n\nSeid vorsichtig damit... ich spüre eine große Macht darin, zum Guten wie auch zum Bösen. Ich hoffe nur, dass Raene und Ihr wisst, was Ihr tut.\n\nViel Glück, {name}.", sourceObjective = "Liefert Dartols Rute bei Raene Wolfsläufer in Astranaar im Eschental ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[1030] = { id = 1030, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dartols Rute", description = "Leider bin ich mir nicht ganz sicher, was er als Nächstes vorhatte.\n\nWenn es wahr ist, was er über die Macht der Rute sagte, könnt Ihr mit ihrer Hilfe eine völlig andere Gestalt annehmen, vermutlich die eines Furbolgs.\n\nVielleicht wollte er ihre Kräfte nutzen, um näher an die besudelten Furbolgs heranzukommen, aber selbst die nicht verderbten Kreaturen hätten ihn getötet, wäre er nicht vorsichtig gewesen. Durch die Rute verwandelt, hätte Dartol wahrscheinlich mit einem Furbolg gesprochen, der noch unverderbt war.\n\nIch würde meine Suche bei dem Furbolg beginnen, der als Krolg bekannt ist. Sucht nach seiner Hütte südöstlich vom Mystralsee.", sourceObjective = "Benutzt Dartols Rute, um mit Krolg bei Krolgs Hütte im Eschental kommunizieren zu können.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[1031] = { id = 1031, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zweig des Cenarius", description = "Anilia legt Euch die Hände auf die Schultern und zieht Euch zu sich heran. Nach Luft ringend zeigt sie in Richtung des Bogens im Norden, bevor sich ihre Augen schließen und sie einen letzten, keuchenden Atemzug ausstößt. \"Er hat ihn... Geltharis...\" In Eurem Herzen wisst Ihr, dass es Anilias letzter Wunsch war, den Zweig des Cenarius wieder in den Händen der Dryaden zu sehen.", sourceObjective = "Erhaltet den Zweig des Cenarius.", sourceObjectiveStatus = "unverified-source-field" }
quests[1032] = { id = 1032, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Satyrn schlachten!", description = "Ich kann nicht glauben, dass Anilia von uns gegangen ist... Wir haben doch immer zusammen in den Wäldern gespielt. Ich fühle beinahe so etwas wie... Trauer.\n\nEs gibt aber etwas, das mich vielleicht aufheitern könnte! Bitte, erschlagt die Satyrn, die mir Anilia genommen haben! Bringt mir ihre Hörner als Beweis Eurer Taten und Ihr könnt Euch auf ewig meines Dankes gewiss sein.", sourceObjective = "Erhaltet 16 Satyrhörner.", sourceObjectiveStatus = "unverified-source-field" }
quests[1033] = { id = 1033, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elunes Träne", description = "Ich hatte gehofft, Orendils Heilmittel würde Relara retten, aber ich fürchte, es hat die Krankheit, die in meinem Kind wütet, nur gedämpft. Wir müssen eine stärkere Medizin finden! Zum Glück hat mir Orendil von weiteren Arzneien erzählt, sollte seine Erste versagen.\n\nElunes Träne ist eine Gesteinsart, die nur an einem Ort vorkommt: den Überresten des Irissees, der durch den Ausbruch des Donnergipfels nordöstlich von Astranaar zerstört worden ist. Orendil sagte, der Stein könne Verderbnis wegwaschen.\n\nBitte, {name}, bringt mir eine Träne Elunes und betet, dass sich die Erkrankung meiner Tochter damit heilen lässt!", sourceObjective = "Erhaltet eine Träne Elunes.", sourceObjectiveStatus = "unverified-source-field" }
quests[1034] = { id = 1034, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Sternenstaubruinen", description = "Elunes Träne hat einen Teil der Erkrankung meiner Tochter weggewaschen. Ihre Alpträume haben nachgelassen und ich danke der Göttin für ihren Segen. Aber... immer noch wütet das Fieber in ihr.\n\nOrendil erzählte mir von einem gefrorenen Staub, den man in den Sternenstaubruinen findet. Vielleicht kann man damit Relaras Fieber senken. Sammelt etwas von diesem Staub und kommt dann bitte wieder zu mir zurück.\n\nDie Sternenstaubruinen liegen im Süden, {name}. Möge Elune Eure Reise beschleunigen.", sourceObjective = "Bringt Pelturas in Astranaar 5 Handvoll Sternenstaub.", sourceObjectiveStatus = "unverified-source-field" }
quests[1035] = { id = 1035, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Himmelssturzsee", description = "Relara hat kein Fieber mehr, aber sie ist immer noch sehr schwach. Ich glaube nicht, dass sie wieder zu Kräften kommt, wenn wir einfach nur abwarten. Ich glaube, dazu bedarf es der Kraft eines Mondsteins.\n\nWir haben Mondsteine früher immer beim Himmelssturzsee im Südosten gesammelt... bis die Schattendickichtbäumlinge kamen.\n\nIhr Anführer, das Schattendickichtorakel, hat alle gefallenen Mondsteine eingesammelt und hortet sie. Jetzt müsst Ihr Euch einen Mondstein von dem Orakel holen.\n\nUnd dazu werdet Ihr ihn wohl erschlagen müssen, fürchte ich.", sourceObjective = "Holt von dem Schattendickichtorakel einen gefallenen Mondstein und bringt ihn Pelturas in Astranaar.", sourceObjectiveStatus = "unverified-source-field" }
quests[1036] = { id = 1036, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hierher, Taugenichts", description = "{name}... Ja, ich habe von Euch gehört. Ich habe gehört, dass Ihr kein Freund von Beutebucht seid - genau wie wir Blutsegelbukaniere. Flottenmeister Firallon sucht nach gesunden und tüchtigen <Männern/Frauen> wie Euch für eine spezielle Mission.\n\nWenn Ihr interessiert seid, begebt Euch zur Purpurschleier und sprecht mit ihm unter Deck. Sie ankert vor der wilden Küste östlich von hier, bei der Springflut und der Maid im Glück.", sourceObjective = "Sprecht mit Flottenmeister Firallon an Bord der Purpurschleier vor der Küste des Schlingendorntals.", completion = "Hierher, Taugenichts. Ich hörte, Ihr wärt der Typ für ein paar kleine Betrügereien. Also, wenn Ihr kein Freund von Beutebucht seid, dann gibt es vielleicht ein besonderes Plätzchen für Euch bei den Blutsegelbukanieren.\n\nArrrrr...", sourceObjectiveStatus = "unverified-source-field" }
quests[1037] = { id = 1037, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Velinde Sternensang", description = "Velinde Sternensang war hier im Eschental meine Vorgängerin. Zunächst schien es, als hätte sie die Lage im Teufelswald unter Kontrolle, aber nach und nach ließen ihre Bemühungen nach. Eines Tages verschwand sie einfach.\n\nMan schickte mich hierher, um ihre Arbeit fortzusetzen. Ich fürchte jedoch, dass ich nichts über die Priesterin weiß. Vielleicht weiß Thyn'tel Klingenweber, eine der Kommandantinnen der Schildwache, mehr über ihr Verschwinden, das ich nicht miterlebt habe.\n\nSie wird sicherlich wissen, wie wichtig diese Informationen sind.", sourceObjective = "Sprecht auf der Terrasse der Krieger in Darnassus mit Thyn'tel Klingenweber.", sourceObjectiveStatus = "unverified-source-field" }
quests[1038] = { id = 1038, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Velindes Besitztümer", description = "Der Foliant von Mel'Thandris hat Euch das gezeigt? Dann könnte es wohl nicht schaden, wenn ich Euch erlaubte, ihre Habseligkeiten durchzusehen. Mit diesem Schlüssel könnt Ihr die Truhe öffnen, in der wir ihre Sachen in der Schildwachenbaracke aufbewahren. Sie führte ein Tagebuch über ihre Pflichten und wenn es etwas zu erfahren gibt, dann daraus.\n\nIch sollte Euch noch sagen, dass die Schildwachen denken, dass sie Gründe für ihr Verschwinden hatte und damit rechnen, dass sie jederzeit wieder auftaucht. Die Priesterin hat in der Vergangenheit viel geleistet und unser Vertrauen verdient.", sourceObjective = "Durchsucht Velindes Truhe nach ihrem Tagebuch und bringt es zusammen mit dem Schlüssel nach Darnassus zu Thyn'tel Klingenweber.", sourceObjectiveStatus = "unverified-source-field" }
quests[1039] = { id = 1039, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Brachlandhafen", description = "Ratschet ist der einzige Hafen des Brachlandes. Höchstwahrscheinlich hat Velinde in Ratschet ein Handelsschiff gefunden, das sie zur Schwarzmeerbucht in Azeroth brachte. Wir haben nur wenig mit den Goblins zu tun, die den Hafen leiten, aber der Dockmeister sollte über das Kommen und Gehen von Schiffspassagieren informiert sein.\n\nFolgt der Straße in südöstlicher Richtung durch das Eschental, dann gelangt Ihr irgendwann ins Brachland. Seid auf der Hut, {name}, Krieger der Horde streifen durch das Land. Im Hafen werdet Ihr jedoch sicher sein.", sourceObjective = "Sprecht in Ratschet mit Werftmeister Flunkerblick.", sourceObjectiveStatus = "unverified-source-field" }
quests[1040] = { id = 1040, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Passage nach Beutebucht", description = "Ah ja, da steht's ja. Hättet mir sagen sollen, dass sie vor so langer Zeit hier durchgekommen ist. Mal sehen.\n\nVelinde. Hat eine Passage auf der BLACK OSPREY nach Beutebucht gebucht. Da hier nichts anderes steht, nehme ich an, dass sie den Hafen dort sicher erreicht hat.\n\nViel mehr Hilfe kann ich Euch nicht anbieten, aber sie hat mich nach einem Überlandtransport zur anderen Seite der Welt gefragt und ich habe ihr Ruzzgot vorgeschlagen, einen Karawanenführer aus Beutebucht. Kann sein, dass Velinde mit ihm gereist ist.\n\nUnd jetzt fort mit Euch. Ich hab zu tun.", sourceObjective = "Nehmt ein Schiff nach Beutebucht und sprecht dort mit dem Karawanenführer Ruzzgot.", sourceObjectiveStatus = "unverified-source-field" }
quests[1041] = { id = 1041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Karawanenstraße", description = "Da hab ich mich wohl in Euch getäuscht und das passiert mir nicht alle Tage.\n\nZufällig erinnere ich mich an diese Velinde, nach der Ihr sucht. Kommt nicht jeden Tag vor, dass eine Nachtelfenpriesterin mit einer schmutzigen alten - aber alle Transportwünsche erfüllenden - Karawane wie der meinigen reisen will.\n\nAuf dem Weg nach Norden trennten wir uns, sie wollte weiter nach Dunkelhain. Der Amtmann dort macht alle möglichen Aufzeichnungen. Kann sein, dass er etwas Nützliches weiß.\n\nSeid im Dschungel vorsichtig, der ist selbst in günstigsten Zeiten tödlich.", sourceObjective = "Sprecht in Dunkelhain mit Amtmann Daltry.", sourceObjectiveStatus = "unverified-source-field" }
quests[1042] = { id = 1042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Familie Treuwein", description = "Nein, ich habe keinen Eintrag über eine Velinde Sternensang, die sich in Dunkelhain aufgehalten haben soll... Wenn Ihr erlaubt, ich kann mir auch nicht vorstellen, dass eine Nachtelfenpriesterin sich in einem Gasthaus einquartiert, wenn Ihr wisst, was ich meine.\n\nDiese Wolfmenschen, die Ihr erwähntet, von denen hab ich schon mal gehört. Erst kürzlich kam Calor mit einer ganzen Reihe Köpfe von denen in die Stadt zurück. Er arbeitet für die Familie Treuwein. Sie jagen Dämonen, Untote und andere Monster. Sprecht mit Jonathan, er ist der Haushaltsvorstand.", sourceObjective = "Sprecht mit Jonathan Treuwein in Dunkelhain.", sourceObjectiveStatus = "unverified-source-field" }
quests[1043] = { id = 1043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Sichel von Elune", description = "Eure Geschichte klingt glaubhaft... Ich habe Eure Beweggründe zwar noch nicht ganz begriffen, aber wenn es zu Euren Angelegenheiten hier im Dämmerwald gehört, die Worgen im Wald auszurotten, dann können mir Eure Beweggründe auch herzlich egal sein, solange das Ergebnis stimmt.\n\nIm Süden gibt es eine Mine, die von Worgen überrannt wurde... Sie kamen aus dem Nichts, aber nach allem, was wir wissen, hat man sie dort zuerst gesehen.\n\nGeht Ihr nur Euren Angelegenheiten nach, aber ich möchte Euch bitten, dass Ihr mir Bescheid gebt, sobald Ihr etwas Wichtiges entdeckt. Wir sind für jede Hilfe gegen das Böse dankbar.", sourceObjective = "Sucht nach Hinweisen auf die Sichel von Elune und kehrt dann zu Jonathan Treuwein in Dunkelhain zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[1044] = { id = 1044, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beantwortete Fragen", description = "Wir werden das Worgproblem in den Griff bekommen, keine Frage. Das Böse, das Eure Freundin in unseren Wald gebracht hat, wird eingedämmt werden und ich nehme ihr ihre Handlungen nicht übel. In letzter Zeit gehen seltsame Dinge vor sich, {name}, und die Dunkelheit kennt keine Atempausen.\n\nIch will Euch nicht länger aufhalten. Mir scheint, dass auch andere erfahren sollten, was Ihr in den Minen des Dämmerwalds entdeckt habt.", sourceObjective = "Kehrt nach Darnassus zu Thyn'tel Klingenweber zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[1045] = { id = 1045, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine neue Verzierung", description = "Ich bin mir sicher, dass der seit langem tote Zauberer Dartol diese Rute dazu benutzen wollte, uns zu unterwerfen und zu zerstören, genauso wie es die Nachtelfen und Orcs versucht haben. Jetzt aber werden wir dieses Ding einem unvorhergesehenen Zweck zuführen.\n\nRan Blutreißer ist König über alle Furbolgs im Eschental. Sein Stamm, die Blutreißer, sind am mächtigsten und grenzen sich in einem Lager im Osten ab.\n\nTötet sie alle und bringt mir seinen Schädel. Wollen wir doch einmal sehen, ob wir nicht einen guten Verwendungszweck dafür finden können.", sourceObjective = "Erhaltet Ran Blutreißers Schädel und Dartols Rute.", sourceObjectiveStatus = "unverified-source-field" }
quests[1046] = { id = 1046, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die wahre Macht der Rute", description = "Nehmt jetzt die Rute und sprecht, während Ihr unter ihrem Effekt steht, mit meinem Bruder Ota Wen.\n\nOta ist bei den anderen Furbolgs, die von den Orcs gefangen genommen und in den riesigen Käfig nördlich der Silberwindzuflucht gesperrt worden sind. Die Rute wird es Euch erlauben, Ota und die anderen Furbolgs dazu zu bringen, sich gegen die Horde aufzulehnen.\n\nDanach dürft Ihr Eures Weges ziehen. Wisst nur, dass Ihr mit Euren Taten einen neuen Freund gefunden habt.", sourceObjective = "Benutzt Dartols Rute und sprecht mit Ota Wen. Überzeugt ihn, sich gegen die Unterdrücker der Horde aufzulehnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1047] = { id = 1047, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die neue Grenze", description = "Aufgemerkt, Helden!\n\nDer Zirkel des Cenarius sucht nach einsatzfähigen Individuen, die dazu beitragen möchten, ihn bei der Erforschung der riesigen neuen Grenzgebiete Kalimdors zu unterstützen! Weit im Westen von Tanaris und Gadgetzan liegt eine abschreckende Ödnis voller unvorstellbarer Gefahren, und der Zirkel braucht ehrbare und gewillte Vertreter, die an seiner statt agieren.\n\nInteressenten mögen bitte zwecks einer Audienz beim Zirkel des Cenarius vorstellig werden. Sprecht in Darnassus mit dem Erzdruiden Fandral Hirschhaupt, er hat weitere Informationen!", sourceObjective = "Sprecht in der Enklave des Cenarius in Darnassus mit dem Erzdruiden Fandral Hirschhaupt über den Aufruf des Zirkels des Cenarius zur Erforschung der Grenzgebiete von Kalimdor.", sourceObjectiveStatus = "unverified-source-field" }
quests[1048] = { id = 1048, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In das Scharlachrote Kloster", description = "Während die Dunkle Fürstin sich um die dringende Angelegenheit des Vormarsches des Lichkönigs im Norden kümmert, sorge ich dafür, dass Dinge, die uns unmittelbar betreffen, entsprechend geregelt werden.\n\nDie Menschenplage, die sich selbst Scharlachroter Kreuzzug nennt, hat sich als der schärfste Dorn in unserem Fleisch erwiesen. Tirisfal wimmelt förmlich von diesen kleinen roten Ameisen.\n\nBegebt Euch zum Kloster, {class}, und vernichtet Hochinquisitorin Weißsträhne und ihre obersten Offiziere.", sourceObjective = "Tötet Hochinquisitorin Weißsträhne, den Scharlachroten Kommandant Mograine, Herod, den Scharlachroten Helden sowie den Hundemeister Loksey und meldet Euch dann wieder bei Varimathras in Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[1049] = { id = 1049, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kompendium der Gefallenen", description = "Der Irdene Ring hatte nur die besten Absichten, was unsere geplagten Brüder betraf. Aber wer weiß schon, welche Absichten jene verfolgen, die dem Ältestenrat Dinge einflüstern?\n\nDie Geschichte der Verlassenen, mit denen wir uns verbündet haben, ist von Lug und Trug durchzogen. Zu übereilt gingen wir unseren Pakt ein. Vielleicht hätte Cairne gut daran getan, die Warnungen aus Orgrimmar zu beherzigen.\n\nTief im Inneren des Scharlachroten Klosters liegt das 'Kompendium der Gefallenen' verborgen, das von irren menschlichen Zeloten bewacht wird. Ihr Tun ist von ihrem Wahnsinn geprägt, aber ihre Forschungen könnten nützlich für uns sein.", sourceObjective = "Holt das 'Kompendium der Gefallenen' aus dem Kloster in Tirisfal und bringt es zu dem Weisen Wahrspruch in Donnerfels.", sourceObjectiveStatus = "unverified-source-field" }
quests[1050] = { id = 1050, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mythologie der Titanen", description = "Die Zukunft ist unausweichlich! Wir stürzen ihr entgegen wie Regentropfen, die auf das Große Meer prasseln.\n\nAber vielleicht erfahren wir, indem wir die Vergangenheit studieren, was uns erwartet, und könnten uns besser auf das Unbekannte vorbereiten.\n\nBevor Lordaeron von all diesen schrecklichen Dingen heimgesucht wurde, gab es eine Bastion des Wissens, die in Tirisfal versteckt lag. Gerüchten zufolge soll es in der Bibliothek des alten Klosters ein Buch mit dem Titel 'Mythologie der Titanen' gegeben haben.\n\nBringt es mir, dann können wir vielleicht gemeinsam die Geheimnisse der Vergangenheit entschlüsseln!", sourceObjective = "Holt die 'Mythologie der Titanen' aus dem Kloster und bringt die der Bibliothekarin Mae Bleichstaub in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
